window.__D("text/kuntres-umaayan/c001",{"p":[[4401900075,"<h2>מַאֲמָר יח.</h2>\nוְהִנֵּה לְהָבִין סְתִירַת הַמַּאֲמָרִים בְּעִנְיַן מְזוֹנוֹתָיו וּצְרָכָיו שֶׁל הָאָדָם, דְּפַעַם אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה כָּל מְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִים לוֹ מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים, וּפַעַם אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָדָם נִידּוֹן בְּכָל יוֹם, וְרַב יֵיבָא הָיָה מִתְפַּלֵּל בְּכָל יוֹם שֶׁיִּנָּתֵן לוֹ מְזוֹנוֹ וְכִדְאִיתָא בְּזֹהַר דְּאַף עַל גַּב דַּהֲוִי לֵיהּ לְמֵיכְלָא לָא הֲוָה מְתַקֵּן לֵיהּ עַד דְּשָׁאִיל לֵיהּ מִבֵּי מַלְכָּא בִּצְלוֹתָא,\nהַיְינוּ שֶׁיֵּשׁ ג' עִנְיָנִים הָא' מַה שֶּׁמְּזוֹנוֹתָיו וּצְרָכָיו שֶׁל אָדָם קְצוּבִים לוֹ מֵרֹאשׁ הַשָּׁנָה הַב' דְּאָדָם נִידּוֹן בְּכָל יוֹם, וְהַג' דְּאַף גַּם שֶׁכְּבָר הַכֹּל מוּכָן לְפָנָיו הִנֵּה אֵינוֹ מִשְׁתַּמֵּשׁ בּוֹ עַד דְּשָׁאִיל לֵיהּ מִבֵּי מַלְכָּא בִּצְלוֹתָא,\nדְּהִנֵּה מְבוֹאָר בִּפְרִי עֵץ חַיִּים אֲשֶׁר מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים הוּא תִּקּוּן וּבִנְיַן הַמַּלְכוּת דַּאֲצִילוּת עַד שֶׁבִּתְפִלַּת נְעִילָה הוּא תַּכְלִית הָעֲלִיָּה שֶׁל הַמַּלְכוּת שֶׁמִּתְעַלֵּית עַד דִּיקְנָא דַאֲרִיךְ אַנְפִּין, שֶׁגַּם בַּשַּׁבָּת אֵין לָהּ עֲלִיָּה כָּזוֹ, דְּבַשַּׁבָּת מִתְעַלֵּית בִּמְקוֹם אַבָּא, וְרַק זָ\"א [זְעֵיר אַנְפִּין] עוֹלֶה עַד הַדִּיקְנָא, וּבִנְעִילָה דְיוֹם הַכִּפּוּרִים הַמַּלְכוּת עוֹלָה עַד הַדִּיקְנָא וּמְקַבֶּלֶת שָׁם ה' גְבוּרוֹת דְּעַתִּיק יוֹמִין, וְזֶהוּ עִנְיַן הַחוֹתָם דִּנְעִילָה דְיוֹם הַכִּפּוּרִים שֶׁהוּא עִנְיַן הַה' גְבוּרוֹת דְּעַתִּיק יוֹמִין.\n<b>וְצָרִיךְ</b> לְהָבִין מַהוּ עִנְיַן הַה' גְבוּרוֹת דְּעַתִּיק יוֹמִין שֶׁמְּקַבֶּלֶת הַמַּלְכוּת בִּתְפִלַּת נְעִילָה, וַהֲלֹא בִּנְעִילָה אָז עִיקַּר הַמְשָׁכַת בְּחִינַת רַחֲמִים פְּשׁוּטִים מַמָּשׁ, וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (פְּסִיקְתָּא דְרַב כַּהֲנָא פַּרְשָׁה וּלְקַחְתֶּם לָכֶם) הַסְּלִיחָה מוּפְקֶדֶת אֶצְלְךָ מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים, דְּיוֹם הַכִּפּוּרִים בִּכְלָל הוּא בִּבְחִינַת רַחֲמִים פְּשׁוּטִים, וּבִפְרָט בְּעֵת הַנְּעִילָה שֶׁאָז הוּא בְּחִינַת תַּכְלִית הָרַחֲמִים וְעֵת רָצוֹן כְּיָדוּעַ, וְאִם כֵּן מַהוּ עִנְיַן הַה' גְבוּרוֹת שֶׁמְּקַבֶּלֶת אָז, וְגַם מַהוּ עִנְיַן הַחוֹתָם.\n<b>אַךְ</b> הָעִנְיָן הוּא דְּהִנֵּה יָדוּעַ דִּבְחִינַת מַלְכוּת דַּאֲצִילוּת הִיא מְקוֹר הָעוֹלָמוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, וּכְמוֹ שֶׁכָּתוּב (תְּהִלִּים קמה. יג) מַלְכוּתְךָ מַלְכוּת כָּל עוֹלָמִים, דְּכָל עוֹלָמִים שֹׁרֶשׁ הִתְהַוּוּתָם הוּא מִבְּחִינַת הַמַּלְכוּת,\nוְנִקְרֵאת אֵם כָּל חַי לְפִי שֶׁהִיא מְקוֹר הַחַיִּים וּמְקוֹר כָּל הַהַשְׁפָּעוֹת בְּכָל הָעוֹלָמוֹת, וְכִדְאִיתָא בְּפַרְדֵּס בְּשַׁעַר עֶרְכֵי הַכִּנּוּיִים עֶרֶךְ חַוָּה שֶׁהִיא סְפִירַת הַמַּלְכוּת שֶׁנִּקְרֵאת אֵם כָּל חַי.\n<b>וְהִנֵּה</b> בְּכָל יוֹם הֲרֵי מִדָּה זוֹ מְחַדֶּשֶׁת שֶׁפַע הָאוֹר וְהַחֶסֶד עֶלְיוֹן בְּכָל הָעוֹלָמוֹת, וְזֶהוּ שֶׁאָנוּ אוֹמְרִים בְּבִרְכַּת הַמָּזוֹן הַזָּן אֶת הָעוֹלָם כּוּלּוֹ בְּטוּבוֹ בְּחֵן בְּחֶסֶד כו' וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (עֲבוֹדָה זָרָה ג. ב) שְׁלִישִׁיּוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב וְזָן אֶת כָּל הָעוֹלָם כּוּלּוֹ מִקַּרְנֵי רְאֵמִים עַד בֵּיצֵי כִנִּים, דְּהַיְינוּ מֵעוֹלָם הַבְּרִיאָה בְּגַן עֵדֶן הָעֶלְיוֹן עַד תַּחְתִּית עוֹלָם הָעֲשִׂיָּה בָּעוֹלָם הַשָּׁפָל, שֶׁכָּל הַנִּבְרָאִים נִכְלָלִים בִּכְלַל זֶה,\nדִּסְפִירַת הַמַּלְכוּת חֲלוּקָה מִכָּל הַסְּפִירוֹת בָּזֶה דִּסְפִירַת הַמַּלְכוּת נֶאֶצְלָה בִּנְקוּדָּה וְהַט' סְפִירוֹת שֶׁבָּהּ בָּאוֹת בְּסוֹד תּוֹסָפוֹת, דְּמִסְּפִירַת הַמַּלְכוּת שֶׁבְּחָכְמָה נִמְשָׁךְ לִהְיוֹת סְפִירַת הַחָכְמָה שֶׁבְּמַלְכוּת וּמִסְּפִירַת הַמַּלְכוּת שֶׁבְּבִינָה נִמְשָׁךְ לִהְיוֹת סְפִירַת הַבִּינָה שֶׁבְּמַלְכוּת וְכֵן כּוּלָּם, וְהַיְינוּ דְּהָאוֹר וְהַחַיּוּת מְקַבֶּלֶת סְפִירַת הַמַּלְכוּת מֵהַסְּפִירוֹת שֶׁלְּמַעְלָה מִמֶּנָּה, וְשֹׁרֶשׁ הַהַמְשָׁכָה הוּא מִכֶּתֶר עֶלְיוֹן, וְזֶהוּ עִנְיַן בִּנְיַן הַמַּלְכוּת בְּרֹאשׁ הַשָּׁנָה, לִהְיוֹת שֶׁבְּרֹאשׁ הַשָּׁנָה נִמְשָׁךְ בְּחִינַת כֶּתֶר מַלְכוּת דְּהַיְינוּ הָרָצוֹן לִמְלוּכָה, כְּיָדוּעַ וּמְבוֹאָר בְּמָקוֹם אַחֵר בַּאֲרִיכוּת, וְלָכֵן אָז הוּא עִיקַּר הַמְשָׁכַת הָאוֹר בִּבְחִינַת מַלְכוּת (שֶׁזֶּהוּ עִנְיַן הָרָצוֹן לִמְלוּכָה)\nוּבְכָל רֹאשׁ הַשָּׁנָה נִמְשָׁךְ אוֹר חָדָשׁ מֵאֵין סוֹף בָּרוּךְ הוּא לְמִדַּת מַלְכוּתוֹ יִתְבָּרֵךְ עַל כָּל הַשָּׁנָה כּוּלָּהּ לְהַחֲיוֹת עוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה לְזוּנָם וּלְפַרְנְסָם, שֶׁאוֹר וְחַיּוּת זֶה הוּא כּוֹלֵל חַיּוּת עוֹלָם שָׁנָה נֶפֶשׁ שֶׁל כָּל הַשָּׁנָה כּוּלָּהּ, אֶלָּא דִּבְרֹאשׁ הַשָּׁנָה הוּא בַּכֶּסֶה עֲדַיִין שֶׁמְּכוּסֶּה וְנֶעְלָם, וּבְיוֹם הַכִּפּוּרִים נִמְשָׁךְ בִּבְחִינַת הַמְשָׁכָה וְגִילּוּי לְמַעְלָה, וּבַסֻּכּוֹת הוּא לְיוֹם חַגֵּינוּ שֶׁנִּמְשָׁךְ בְּגִילּוּי יוֹתֵר אַךְ בִּבְחִינַת מַקִּיף, וּבַשְּׁמִינִי עֲצֶרֶת נִמְשָׁךְ בִּבְחִינַת פְּנִימִיּוּת שֶׁזֶּהוּ עִנְיַן הַקְּלִיטָה דִּשְׁמִינִי עֲצֶרֶת, וְאַחַר כַּךְ נִמְשָׁךְ עַל יְדֵי בְּחִינַת מַלְכוּת בְּכָל יוֹם וָיוֹם בְּגִילּוּי לְמַטָּה בָּעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה.\n<b>וְזֶהוּ</b> בְּחִינַת הַמְשָׁכַת הַחֶסֶד עֶלְיוֹן שֶׁנִּמְשָׁךְ מִבְּחִינַת הַכֶּתֶר בְּחִינַת חֲסָדִים דְּעַתִּיק בִּבְחִינַת מַלְכוּת בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וּמִבְּחִינַת מַלְכוּת נִמְשָׁךְ בְּכָל הָעוֹלָמוֹת.\nקִיצּוּר.\nאֲצִילוּת סְפִירַת הַמַּלְכוּת בְּסוֹד שֹׁרֶשׁ וּנְקוּדָּה אַחַת וּבְרֹאשׁ הַשָּׁנָה בִּנְיַן הַמַּלְכוּת שֶׁמְּקַבֶּלֶת מֵהַט' סְפִירוֹת שֶׁלְּמַעְלָה וְשֹׁרֶשׁ הַהַמְשָׁכָה מִכֶּתֶר מַלְכוּת, שֶׁבְּרֹאשׁ הַשָּׁנָה עֲדַיִין מְכוּסֶּה וּבְיוֹם הַכִּפּוּרִים מִתְגַּלֶּה וּבַסֻּכּוֹת בְּמַקִּיף וּבַשְּׁמִינִי עֲצֶרֶת בִּקְלִיטָה וְנִמְשָׁךְ עַל יְדֵי סְפִירַת הַמַּלְכוּת."],[4401900076,"וְהִנֵּה שֹׁרֶשׁ הַהַמְשָׁכָה שֶׁנִּמְשָׁךְ בִּסְפִירַת הַמַּלְכוּת מִכֶּתֶר מַלְכוּת בְּרֹאשׁ הַשָּׁנָה שֶׁהוּא הָאוֹר וְהַחַיּוּת מִבְּחִינַת חֶסֶד דְּעַתִּיק שֶׁנִּמְשָׁךְ בִּבְחִינַת מַלְכוּת, הֲרֵי הוּא בְּחִינַת אוֹר כְּלָלִי וְלֹא נִתְחַלֵּק לִפְרָטִים כְּלָל וְאִי אֶפְשָׁר שֶׁיִּתְקַבֵּל אֶל הַמְקַבְּלִים, וּבִכְדֵי שֶׁיִּתְקַבֵּל הָאוֹר בַּמְקַבְּלִים זֶהוּ עַל יְדֵי בְּחִינַת ה' גְבוּרוֹת דְּעַתִּיק, שֶׁהֵם הַמְחַלְּקִים אֶת הַחֶסֶד לַחֲלָקִים, שֶׁעַל יְדֵי זֶה יִתְקַיֵּים עִיקַּר אֲמִיתַּת הַחֶסֶד שֶׁעַל יְדֵי זֶה יוּכְלוּ הַנִּבְרָאִים לְקַבֵּל אֶת הַחֶסֶד,\nוּכְעִנְיַן גְּבוּרוֹת גְּשָׁמִים שֶׁיּוֹרְדִין בִּגְבוּרָה שֶׁמִּתְחַלְּקִים טִיפִּין טִיפִּין וְזֶהוּ תַּכְלִית וַאֲמִיתִּית הַחֶסֶד שֶׁעַל יְדֵי זֶה דַוְקָא וְהִרְוָה אֶת הָאָרֶץ וְהוֹלִידָהּ וְהִצְמִיחָהּ,\nוְכֵן בְּכֹחוֹת הַנֶּפֶשׁ בָּאָדָם, דְּהַקּוֹל הַיּוֹצֵא מֵהֶבֶל הַלֵּב הוּא קוֹל פָּשׁוּט וּמִתְחַלֵּק לְאוֹתִיּוֹת בְּה' מוֹצְאוֹת הַפֶּה אחה\"ע מֵהַגָּרוֹן גיכ\"ק מֵהַחֵיךְ כו' וְהַיְינוּ עַל יְדֵי ה' גְבוּרוֹת מנצפ\"ך מְקוֹר הַדִּבּוּר, וְכִדְאִיתָא בְּהַקְדָּמַת הַזֹּהַר בְּעִנְיַן כּוֹס יְשׁוּעוֹת אֶשָּׂא, כּוֹס שֶׁל בְּרָכָה אִצְטְרִיךְ לְמֶהֱוֵי עַל חֲמֵשׁ אֶצְבָּעִין, וּמְבוֹאָר שָׁם שֶׁהֵן בְּחִינַת ה' גְבוּרוֹת, וְהֵם דַּוְקָא נִקְרְאוּ יְשׁוּעוֹת וּכְאָמְרוֹ וְאִינּוּן חֲמֵשׁ אִיקְרִין יְשׁוּעוֹת, וְעַיֵּן שָׁם בְּפֵירוּשׁ הָרְמָ''ז [רַבִּי מֹשֶׁה זַכּוּת] שֶׁהֵן ה' גְבוּרוֹת הַנִּמְשָׁכוֹת מִיסוֹד דְּעַתִּיק.\n<b>וְזֶהוּ</b> שֶׁנִּקְרְאוּ הַה' גְבוּרוֹת ה' אֶצְבָּעוֹת, דִּכְמוֹ עַל דֶּרֶךְ מָשָׁל הַיָּד הִנֵּה קוֹדֶם הִתְחַלְּקוּתָהּ לְה' אֶצְבָּעוֹת הֲרֵי הַכֹּחַ כָּלוּל בָּהּ בְּיַחַד בְּלִי הִתְחַלְּקוּת, וּכְשֶׁמִּתְחַלֶּקֶת לְה' אֶצְבָּעוֹת מִתְחַלֵּק כֹּחַ הַהוּא שֶׁיִּהְיֶה לְכָל אֶצְבַּע כֹּחַ פְּרָטִי מְצוּמְצָם בִּפְנֵי עַצְמוֹ זוֹ זֶרֶת וְזוֹ קְמִיצָה כו' וְכִדְאִיתָא בִּגְמָרָא (כְּתוּבּוֹת ה. א וְשָׁם) דְּכָל חֲדָא וַחֲדָא לְמִילְּתֵיהּ עֲבִידָא וְהִתְחַלְּקוּת זוֹ הִיא בְּחִינַת גְּבוּרוֹת\nאַךְ ה' גְבוּרוֹת אֵלּוּ הֵן אֲמִיתִּית הַחֶסֶד, שֶׁהֲרֵי הַיָּד אִם לֹא הָיָה בָהּ חִלּוּק הָאֶצְבָּעוֹת לֹא הָיָה יָכוֹל לַעֲשׂוֹת בָּהּ מְלָאכָה וּפְעוּלָּה וְלֹא לִכְתּוֹב שֶׁכָּל פְּעוּלּוֹת אֵלּוּ נַעֲשׂוֹת דַּוְקָא עַל יְדֵי הָאֶצְבָּעוֹת, נִמְצָא שֶׁהֲגַם שֶׁהַיָּד עַצְמָהּ הִיא כְּלָלוּת הַכֹּחַ מִכָּל מָקוֹם אִם לֹא עַל יְדֵי ה' גְבוּרוֹת דְּחִילּוּק הָאֶצְבָּעוֹת לֹא הָיָה יָכוֹל לִהְיוֹת פְּעוּלָּה וְהַשְׁפָּעָה מֵהַכֹּחַ שֶׁבַּיָּד, וְאִם כֵּן הֲרֵי ה' גְבוּרוֹת אֵלּוּ הֵן שְׁלֵמוּת פְּעוּלַּת הַחֶסֶד וּכְעִנְיַן גְּבוּרוֹת גְּשָׁמִים הַנַ\"ל.\n<b>וְזֶהוּ</b> עִנְיַן מַה שֶּׁנִּקְרְאוּ גְּבוּרוֹת הַנַ\"ל בְּשֵׁם יְשׁוּעוֹת, דְּזֶהוּ גַם כֵּן שֶׁכּוֹס שֶׁל בְּרָכָה צָרִיךְ לִהְיוֹת עַל ה' אֶצְבָּעִין דַּוְקָא. וּמִכָּל שֶׁכֵּן בִּבְחִינַת עַתִּיק שֶׁהַה' גְבוּרוֹת דְּשָׁם הֵן וַדַּאי כְּלוּלוֹת וּמְיוּחָדוֹת בְּהַה' חֲסָדִים, דְּהָא לֵית שְׂמָאלָא בְּהַאי עַתִּיקָא, וְלָכֵן מֵהֶן מִיתּוּק כָּל הַגְּבוּרוֹת שֶׁלְּמַטָּה, וּכְיָדוּעַ מֵעִנְיַן אֵין הַדִּינִין נִמְתָּקִין אֶלָּא בְּשָׁרְשָׁן, וּכְמוֹ שֶׁכָּתוּב בִּפְרִי עֵץ חַיִּים בְּכַוָּונַת הַשּׁוֹפָר, וְאַף עַל פִּי כֵן נִקְרָא ה' גְבוּרוֹת שֶׁבָּהֶן וְעַל יָדָן נִמְשָׁךְ שְׁלֵימוּת פְּעוּלַּת הַה' חֲסָדִים שֶׁתִּתְחַלֵּק הַשֶּׁפַע בִּכְדֵי שֶׁתּוּכַל לְהִתְקַבֵּל אֶל הַנִּבְרָאִים, וְגַם עַל יְדֵי זֶה נִמְשָׁךְ הַחֶסֶד לְכָל אֶחָד וְאֶחָד מֵהַנִּבְרָאִים בִּפְרָט.\n<b>דְּהִנֵּה</b> בְּחִינַת הַחֶסֶד שֶׁנִּמְשָׁךְ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים מִבְּחִינַת ה' חֲסָדִים דְּעַתִּיק הוּא בְּחִינַת הַמְשָׁכַת חֶסֶד כְּלָלִי לִכְלָלוּת הָעוֹלָם, וְהַה' גְבוּרוֹת דְּעַתִּיק שֶׁנִּמְשָׁכִים בִּנְעִילָה הוּא שֶׁמִּתְחַלֵּק בְּחִינַת הַחֶסֶד לְכָל נִבְרָא בִּפְרָט כַּמָּה מִן הַחֶסֶד יוּמְשַׁךְ לְכָל אֶחָד וְאֶחָד, וְגַם עַל יְדֵי זֶה נִמְשָׁךְ הַחוֹתָם שֶׁלֹּא תוּמְשַׁךְ הַשֶּׁפַע וְתִתְפַּשֵּׁט יוֹתֵר מִדַּאי לְמָקוֹם שֶׁאֵין צָרִיךְ, וְהַיְינוּ שֶׁלֹּא תִהְיֶה יְנִיקַת הַחִיצוֹנִים, דְּעַל יְדֵי שֶׁנִּמְשָׁךְ הַחֶסֶד לְכָל אֶחָד וְאֶחָד עַל יְדֵי בְּחִינַת הַה' גְבוּרוֹת, שֶׁבָּאָה הַשְׁפָּעַת הַחֶסֶד בִּבְחִינַת הַגְבָּלָה, מִמֵּילָא לֹא תִהְיֶה מִזֶּה יְנִיקַת הַחִיצוֹנִים, דְּדַוְקָא כְּשֶׁהָאוֹר הוּא בִּבְחִינַת בְּלִי גְבוּל אָז יִתְפַּשֵּׁט בְּיוֹתֵר וְיָכוֹל לִהְיוֹת שֶׁיּוּמְשַׁךְ גַּם לְמָקוֹם שֶׁאֵינוֹ רָאוּי, אֲבָל כְּשֶׁהוּא בִּבְחִינַת הַגְבָּלָה אֵינוֹ נִמְשָׁךְ לְמָקוֹם שֶׁאֵינוֹ רָאוּי.\n<b>וְזֶהוּ</b> גַם כֵּן עִנְיַן הַה' גְבוּרוֹת, דִּבְכָל אֶחָד וְאֶחָד לֹא תִהְיֶה יְנִיקַת הַחִיצוֹנִים מֵהַשְׁפָּעַת הַחֶסֶד שֶׁנִּמְשָׁךְ אֵלָיו. וְזֶהוּ עִנְיַן הַחוֹתָם דִּנְעִילָה שֶׁהַיְינוּ מַה שֶּׁנֶּחְתָּם וְנֶחֱלָק הַשְׁפָּעַת הַחֶסֶד בִּפְרָט לְכָל אֶחָד וְאֶחָד.\nקִיצּוּר.\nה' גְבוּרוֹת דְּעַתִּיק מְחַלְּקוֹת הַשֶּׁפַע שֶׁנִּמְשָׁךְ בְּמַלְכוּת, גְּבוּרוֹת גְּשָׁמִים, ה' מוֹצָאוֹת מְחַלְּקִים הַקּוֹל, ה' אֶצְבָּעוֹת מְחַלְּקִים כֹּחַ הַכְּלָלִי וְעַל יָדָן הֵן הַפְּעוּלּוֹת, כּוֹס יְשׁוּעוֹת דְּיָתְבָא עַל ה' אֶצְבָּעִין, הַחוֹתָם בִּכְדֵי שֶׁהַשֶּׁפַע יַגִּיעַ לְמָקוֹם הָרָאוּי וּלְכָל אֶחָד בִּפְרָט."],[4401900077,"<h2>מַאֲמָר יט.</h2>\nוְהִנֵּה הַחוֹתָם דִּנְעִילָה דְיוֹם הַכִּפּוּרִים הִנֵּה מִלְּבַד זֹאת שֶׁעִנְיָנוֹ הוּא שֶׁהַשֶּׁפַע הַכְּלָלִי שֶׁנִּמְשָׁךְ בִּסְפִירַת הַמַּלְכוּת יַגִּיעַ לְמָקוֹם הָרָאוּי וּלְכָל אֶחָד בִּפְרָט, הִנֵּה עוֹד זֹאת עִנְיַן הַחוֹתָם דִּנְעִילָה הוּא הַשְּׁמִירָה כְלָלִית שֶׁלֹּא תִהְיֶה יְנִיקַת הַחִיצוֹנִים מֵהַחֶסֶד הַנִּמְשָׁךְ, וּכְמוֹ חוֹתָם שֶׁמַּנִּיחִים עַל אִגֶּרֶת הוּא בִּכְדֵי שֶׁלֹּא יִקְרָאֶנָּה זָר, וּכְמוֹ כֵן הוּא עִנְיַן הַחוֹתָם לְמַעְלָה שֶׁלֹּא יִנְקוּ הַחִיצוֹנִים מֵהַהַשְׁפָּעָה, וְהַיְינוּ עַל יְדֵי ה' גְבוּרוֹת דְּעַתִּיק שֶׁמְּקַבֶּלֶת אָז בְּחִינַת הַמַּלְכוּת, שֶׁבָּהֶם וְעַל יָדָם נִמְשָׁךְ הִתְחַלְּקוּת הַחֶסֶד עֶלְיוֹן דְּעַתִּיק לְכָל הַנִּבְרָאִים דְּעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה הַמְקַבְּלִים מִבְּחִינַת מַלְכוּת דַּאֲצִילוּת.\n<b>וְזֶהוּ</b> מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה דִּמְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִים לוֹ מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים, הַיְינוּ שֶׁעַל יְדֵי ה' גְבוּרוֹת נִמְשָׁךְ הַקִּצְבָה שֶׁהוּא כַּמָּה יוּמְשַׁךְ הַחֶסֶד עֶלְיוֹן לְכָל אָדָם בִּפְרָט, מַה שֶּׁאֵין כֵּן מִתְּחִלָּה הָיָה הַחֶסֶד אוֹר וְחַיּוּת כְּלָלִי לִכְלָלוּת הָעוֹלָמוֹת, וְעַל יְדֵי ה' גְבוּרוֹת הַחוֹתָם דִּנְעִילָה נַעֲשׂוּ שְׁנֵי עִנְיָנִים כְּאֶחָד, וְהוּא שֶׁלֹּא יִקְרַב זָר לְקַבֵּל גַּם שֶׁמֶץ מִשֶּׁפַע זוּ וַאֲשֶׁר יוּמְשַׁךְ לְמָקוֹם הָרָאוּי וְנוֹתֵן קִצְבָה שֶׁיִּתְחַלֵּק וְיוּמְשַׁךְ לְכָל נִבְרָא וּלְכָל אָדָם בְּדֶרֶךְ פְּרָט.\n<b>דְּהִנֵּה</b> כְּשֶׁמַּלְכוּת דַּאֲצִילוּת מְקַבֶּלֶת בִּנְעִילָה דְּיוֹם הַכִּפּוּרִים מֵה' גְבוּרוֹת דְּעַתִּיק אוֹר הַחֶסֶד עֶלְיוֹן שֶׁנִּקְצַב עַל יְדֵי הַה' גְבוּרוֹת לְכָל הָעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה וּלְכָל בְּרִיָּה בִּפְרָט, הִנֵּה גַּם אָז עֲדַיִין הַחֶסֶד הוּא כְּמוֹ שֶׁהוּא לְמַעְלָה בַּאֲצִילוּת שֶׁהוּא בִּבְחִינַת תַּכְלִית הָרוּחָנִיּוּת וְלֹא נִמְצָא וְלֹא נִצְטַיֵּיר בּוֹ עֲדַיִין מֵהַשְׁפָּעוֹת וְחַיּוּת גַּשְׁמִי דְּעִנְיְנֵי עוֹלָם הַזֶּה כְּלָל, כְּמוֹ שֶׁאֵין עֲרוֹךְ חַיּוּת עוֹלָם הַזֶּה לְעוֹלָם הָאֲצִילוּת,\nוּכְיָדוּעַ דַּאֲצִילוּת מוּבְדָּל בְּעֶרֶךְ מֵעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה וְלָכֵן בְּהַד' יְסוֹדוֹת אֵשׁ-רוּחַ-מַיִם-עָפָר, שֶׁכְּלָלוּת הַד' עוֹלָמוֹת אֲצִילוּת-בְּרִיאָה-יְצִירָה-עֲשִׂיָּה נִכְלָלִים בְּד' יְסוֹדוֹת אֵלּוּ כְּמוֹ שֶׁכָּתוּב בְּעֵץ חַיִּים, הִנֵּה אֲצִילוּת הוּא בְּחִינַת יְסוֹד הָאֵשׁ וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים ד. כד) כִּי ה' אֱלֹקֶיךָ אֵשׁ אֹכְלָה הוּא שֶׁנִּמְשָׁל לְאֵשׁ, וְהַיְינוּ כְּמוֹ שֶׁהָאֵשׁ אֵין לוֹ הִתְחַבְּרוּת עִם שְׁאָר הַיְסוֹדוֹת וְלָכֵן הוּא תָּמִיד בִּבְחִינַת עֲלִיָּה וְהִסְתַּלְּקוּת לְמַעְלָה, וּכְמוֹ כֵן עוֹלָם הָאֲצִילוּת אֵין לוֹ הִתְחַבְּרוּת עִם עוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה, דַּאֲצִילוּת הוּא אֱלֹקוּת מַמָּשׁ וְאֵין שָׁם בְּחִינַת יֵשׁ כְּלָל,\nוְעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה הֲרֵי מֵעוֹלָם הַבְּרִיאָה מַתְחִיל בְּחִינַת מְצִיאוּת הַיֵּשׁ, שֶׁעַל זֶה מוֹרֶה לְשׁוֹן בָּרָא כְּמוֹ שֶׁכָּתַב הָרַמְבַּ\"ן [רַבִּי מֹשֶׁה בֶּן נַחְמָן] בְּפֵירוּשׁוֹ עַל הַתּוֹרָה בְּפָסוּק בְּרֵאשִׁית בָּרָא, וְלָכֵן אֲצִילוּת מוּבְדָּל מִבְּרִיאָה-יְצִירָה-עֲשִׂיָּה וְכָל שֶׁכֵּן מֵעוֹלָם עֲשִׂיָּה הַגַּשְׁמִי מַמָּשׁ, וְלָזֹאת בִּבְחִינַת הַשְׁפָּעַת הַחֶסֶד שֶׁבְּעוֹלָם הָאֲצִילוּת אֵין שָׁם שׁוּם צִיּוּר עֲדַיִין מִבְּחִינַת הַחֶסֶד הַגַּשְׁמִי דְּעוֹלָם הַזֶּה רַק שֶׁנִּמְשָׁךְ סְתָם הַשְׁפָּעַת הַחֶסֶד לִכְנֶסֶת יִשְׂרָאֵל, וְנֶחֱלָק עַל יְדֵי הה' גְבוּרוֹת לְכָל אֶחָד וְאֶחָד בִּפְנֵי עַצְמוֹ, אֲבָל הַכֹּל הוּא בִּבְחִינַת חֶסֶד רוּחָנִי עֲדַיִין.\n<b>וּבִכְדֵי</b> שֶׁיּוּמְשַׁךְ אַחַר כַּךְ מֵחֶסֶד זֶה חַיּוּת וְהַשְׁפָּעוֹת גַּשְׁמִיּוֹת בְּבָנֵי חַיֵּי וּמְזוֹנֵי, הוּא עַל יְדֵי הִתְלַבְּשׁוּת הַמַּלְכוּת דַּאֲצִילוּת בִּבְרִיאָה יְצִירָה וַעֲשִׂיָּה, וּכְמוֹ שֶׁכָּתוּב בְּאִגֶּרֶת הַקֹּדֶשׁ בְּסוֹפוֹ בִּדְרוּשׁ הַמַּתְחִיל לְהָבִין מַה שֶּׁכָּתוּב בִּפְרִי עֵץ חַיִּים שֶׁאֲפִילוּ בְּיוֹם טוֹב בְּחִינַת חֶסֶד דַּאֲצִילוּת מִתְלַבֵּשׁ לְגַמְרֵי בְּחֶסֶד דִּבְרִיאָה וּמְחַיֶּה עוֹלָם הַזֶּה הַגַּשְׁמִי עַל יְדֵי מַעֲבַר חֶסֶד דִּיצִירָה וַעֲשִׂיָּה הַנִּקְרָא גַם כֵּן הִתְלַבְּשׁוּת שֶׁאִם לֹא כֵן לֹא הָיָה פוֹעֵל בְּגַשְׁמִיּוּת עוֹלָם הַזֶּה עַד כַּאן דִּבּוּרוֹ.\n<b>וּבְיוֹמִין</b> דְּחוֹל הוּא עַל יְדֵי הִתְלַבְּשׁוּת גְּמוּרָה בְּחֶסֶד דִּיצִירָה וַעֲשִׂיָּה, וְהַיְינוּ גַם כֵּן עַל יְדֵי יִחוּד זוּ\"נ [זְעֵיר אַנְפִּין וְנוּקְבָא] דִּיצִירָה וְאֵין מַסְפִּיק בְּחִינַת הַהִתְלַבְּשׁוּת בְּחֶסֶד דִּיצִירָה לְבָד, כִּי זָ\"א דִּיצִירָה גַּם כֵּן עֲדַיִין אֵינוֹ בְגֶדֶר שֶׁתִּהְיֶה מִזֶּה הַשְׁפָּעַת חֶסֶד דַּעֲשִׂיָּה, וְלֹא הָיָה יָכוֹל לְהִתְהַוּוֹת מִזֶּה חַיּוּת הָעֲשִׂיָּה, כִּי אִם כְּשֶׁהוֹלֵךְ הַשֶּׁפַע עַל יְדֵי מַלְכוּת דִּיצִירָה וְנִתְצַמְצֵם עֶצֶם הָאוֹר דְּזָ\"א דִּיצִירָה,\nוּבַעֲשִׂיָּה צָרִיךְ לִהְיוֹת גַּם כֵּן יִחוּד זוּ\"נ דַּעֲשִׂיָּה, כִּי עִיקַּר הִתְהַוּוּת הַיֵּשׁ וְדָבָר נִפְרָד לְגַמְרֵי הוּא מִבְּחִינַת מַלְכוּת דַּוְקָא לְפִי שֶׁאֵין מֶלֶךְ בְּלֹא עָם כו', וְאָז נִמְשָׁךְ מִזֶּה הַהַשְׁפָּעוֹת בַּעֲשִׂיָּה הַגַּשְׁמִית לְמַטָּה דְּבַר יוֹם בְּיוֹמוֹ עַל יְדֵי הַמִּדָּה שֶׁבַּיּוֹם הַהוּא מִו' קְצָווֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, דְּכָל הַהִתְחַלְּקוּת בָּא מֵה' גְבוּרוֹת דְּעַתִּיק.\nקִיצּוּר.\nהַחוֹתָם הוּא שֶׁיַּגִּיעַ הַשֶּׁפַע לְמָקוֹם הָרָאוּי וּלְכָל אֶחָד בִּפְרָט. הַשֶּׁפַע הַכְּלָלִי הַמִּתְקַבֵּל בְּמַלְכוּת דַּאֲצִילוּת בִּנְעִילָה הוּא חֶסֶד רוּחָנִי דַּאֲצִילוּת. אֲצִילוּת מוּבְדָּל מִבְּרִיאָה-יְצִירָה-עֲשִׂיָּה כְּאֵשׁ הַנִּבְדָּל מִשְּׁאָר הַיְסוֹדוֹת, וְרַק בְּהִשְׁתַּלְשְׁלוּת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הִנֵּה עַל יְדֵי ה' גְבוּרוֹת דְּעַתִּיק נַעֲשֶׂה חֶסֶד שֶׁבְּעֶרֶךְ הַנִּבְרָאִים."],[4401900078,"וְעַל פִּי זֶה יוּבַן עִנְיַן הַדִּין וּמִשְׁפָּט שֶׁיֵּשׁ בְּכָל יוֹם וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (רֹאשׁ הַשָּׁנָה טז. א) דְּאָדָם נִידּוֹן בְּכָל יוֹם, דְּהִנֵּה כְּתִיב (שְׁמוֹת כ. ט) שֵׁשֶׁת יָמִים תַּעֲבוֹד וְעָשִׂיתָ כָּל מְלַאכְתֶּךָ (שָׁם יא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֶת הַיָּם וְאֶת כָּל אֲשֶׁר בָּם וַיָּנַח בְּיוֹם הַשְּׁבִיעִי וְאִיתָא בְּזֹהַר בְּכָל יוֹמָא עָבִיד עֲבִידְתֵּיהּ וְכֵן הוּא בַּעֲבוֹדַת הָאָדָם דְּשֵׁשֶׁת יָמִים תַּעֲבוֹד וְעָשִׂיתָ כָּל מְלַאכְתֶּךָ, דְּכָל אֶחָד וְאֶחָד מִיִּשְׂרָאֵל יֵשׁ לוֹ מְלַאכְתּוֹ אֲשֶׁר בִּשְׁבִילָהּ נִבְרָא וּבִשְׁבִילָהּ יָרְדָה נִשְׁמָתוֹ לְמַטָּה,\nוּכְתִיב (תְּהִלִּים קלט, טז) יָמִים יוּצָּרוּ וְלוֹ אֶחָד בָּהֶם דְּתַכְלִית כָּל הַיָּמִים אֲשֶׁר נוֹצְרוּ וְנִיתְּנוּ לְהָאָדָם הוּא בִּכְדֵי וְלוֹ אֶחָד בָּהֶם שֶׁהָאָדָם בַּעֲבוֹדָתוֹ יַמְשִׁיךְ בְּחִינַת אֶחָד, דְּאֶחָד הוּא רָאשֵׁי תֵבוֹת דְּא' הוּא אֵין סוֹף בָּרוּךְ הוּא אַלּוּפוֹ שֶׁל עוֹלָם, ח' הֵם ז' רְקִיעִים וָאָרֶץ וְד' הֵם ד' רוּחוֹת הָעוֹלָם וּבִכְלָלוּת הוּא עִנְיַן הַמָּקוֹם וְיָמִים הוּא עִנְיַן הַזְּמַן, וְהַיְינוּ דְּהָאָדָם עֲבוֹדָתוֹ לְחַבֵּר זְמַן וּמָקוֹם וּלְיַחֲדָם בֵּאלֹקוּת. וְזֶהוּ מְלַאכְתְּךָ שֶׁהִיא מְלֶאכֶת הָאָדָם בְּתַכְלִית יְרִידַת נִשְׁמָתוֹ לְמַטָּה.\n<b>אָמְנָם</b> מְלָאכָה זוֹ צְרִיכָה לְהֵעָשׂוֹת בְּכָל יוֹם וָיוֹם וּבַעֲבוֹדָה בִּיגִיעָה שֶׁהִיא יְגִיעַת בָּשָׂר וִיגִיעַת נֶפֶשׁ. וְזֶהוּ שֵׁשֶׁת יָמִים תַּעֲבוֹד דִּבְכָל יוֹם וָיוֹם צְרִיכָה לִהְיוֹת הָעֲבוֹדָה בַּעֲבוֹדַת ה' לְפִי מַעֲלַת הַיּוֹם הַהוּא וְעִנְיָנוֹ בִּסְפִירוֹת הָעֶלְיוֹנוֹת,\nדְּיוֹם רִאשׁוֹן הוּא חֶסֶד וְעִנְיָנוֹ בַּעֲבוֹדָה אַהֲבָה, וְיוֹם שֵׁנִי הוּא גְבוּרָה וְעִנְיָנוֹ בַּעֲבוֹדָה הוּא יִרְאָה, יוֹם הַשְּׁלִישִׁי תִּפְאֶרֶת וְעִנְיָנוֹ בַּעֲבוֹדָה הוּא לְאִסְתַּכָּלָא בִּיקָרָא דְמַלְכָּא בְּהִתְכַּלְלוּת חֶסֶד וּגְבוּרָה וְאַהֲבָה וְיִרְאָה,\nוְיוֹם הָרְבִיעִי נֶצַח וְעִנְיָנוֹ בַּעֲבוֹדָה לְעוֹרֵר מִדַּת הַנִּצָּחוֹן לְבָעֵר וּלְשָׁרֵשׁ גַּם אֶת הַדַּקּוּת דְּדַקּוּת שֶׁל הַלֹּא טוֹב, וְזֶהוּ דְּבָרְבִיעִי נִתְלוּ הַמְּאוֹרוֹת שֶׁהוּא אוֹר הַמֵּאִיר דְּשֶׁמֶשׁ הוי' הַדּוֹחֶה וּמְכַלֶּה גַּם הַדַּקּוּת שֶׁבְּדַקּוּת הַלֹּא טוֹב,\nוְיוֹם הַחֲמִישִׁי הוֹד וְעִנְיָנוֹ בַּעֲבוֹדָה לְהִתְבּוֹנֵן וּלְהַשִּׂיג הוֹד כְּבוֹד מַלְכוּתוֹ יִתְבָּרֵךְ כְּמוֹ שֶׁהוּא מוּבָן וּמוּשָּׂג מֵהַבְּרִיאָה כוּלָּהּ כְּשֶׁמִּתְבּוֹנֵן בְּעִנְיְנֵי מָה רַבּוּ מַעֲשֶׂיךָ הוי' וּמַה גָּדְלוּ מַעֲשֶׂיךָ ה',\nוּבְיוֹם הַשִּׁשִּׁי יְסוֹד וְעִנְיָנוֹ בַּעֲבוֹדָה הוּא דְּאַחִיד בִּשְׁמַיָּא וּבְאַרְעָא הַיִּחוּד דִּמְמַלֵּא כָּל עָלְמִין וְסוֹבֵב כָּל עָלְמִין,\nוְיָדוּעַ דְּכָל הַמִּדּוֹת מִתְכַּלְלוֹת זֶה מִזֶּה וְזוֹהִי שְׁלֵמוּתָם, וְכֵן הוּא בְּעִנְיְנֵי הָעֲבוֹדָה שֶׁהֵם מִתְכַּלְלִים וּמַשְׁלִימִים זֶה אֶת זֶה, דְּאַהֲבָה כְּלוּלָה מִיִּרְאָה וּבְיִרְאָה כְּלוּלָה אַהֲבָה וְכֵן כֻּלָּם, אֲבָל עִם זֶה הִנֵּה כָּל יוֹם וָיוֹם יֵשׁ לוֹ עֲבוֹדָתוֹ הַפְּרָטִית לְפִי עִנְיָנוֹ בְּהַסְּפִירוֹת שֶׁל מַעְלָה.\n<b>וְזֶהוּ</b> דְּאָדָם נִדּוֹן בְּכָל יוֹם, דְּהִנֵּה לְפִי הַמְבוֹאָר לְעֵיל מוּבָן דְּמִבְּחִינַת הַחֶסֶד שֶׁנִּקְצַב בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וְנִמְשַׁךְ בִּבְחִינַת מַלְכוּת דַּאֲצִילוּת יָכוֹל לִהְיוֹת מִזֶּה כַּמָּה מִינֵי אוֹפַנֵּי חֶסֶד בַּעֲשִׂיָּה, כִּי מֵאַחַר דְּבְּהַחֶסֶד כְּמוֹ שֶׁהוּא בַּאֲצִילוּת אֵין בּוֹ צִיּוּר כְּלָל מֵאוֹפֶן הַשְׁפָּעַת הַחֶסֶד דַּעֲשִׂיָּה, וַהֲרֵי הוּא בִּבְחִינַת חֶסֶד פָּשׁוּט עֲדַיִין שֶׁיָּכוֹל לְהִצְטַיֵּיר עַל יְדֵי הַהִתְלַבְּשׁוּת דְּעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה כַּנַ\"ל, שֶׁעַל יְדֵי זֶה נַעֲשֶׂה בִּבְחִינַת חֶסֶד גַּשְׁמִי בָּעוֹלָם הַזֶּה הַגַּשְׁמִי בְּכַמָּה אוֹפַנִּים שׁוֹנִים,\nוְעַל זֶה הוּא הַדִּין וּמִשְׁפָּט בְּכָל יוֹם בְּהַחֶסֶד שֶׁנִּמְשַׁךְ לְהָאָדָם לְצוֹרֶךְ מָה יִתְפַּשֵּׁט וְיוּמְשַׁךְ מִמֶּנּוּ בַּעֲשִׂיָּה, אִם לְכָל מִילֵּי דְמֵיטַב לְבָנֵי חַיֵּי וּמְזוֹנֵי בְּרֶיוַח אוֹ רַק שְׁנַיִם מֵהֶם בְּרֶיוַח אוֹ רַק אֶחָד מֵהֶם, וְהַדִּין וּמִשְׁפָּט הַזֶּה הוּא עַל יְדֵי הַבֵּית דִּין שֶׁל מַעְלָה שֶׁבְּהֵיכַל הַזְּכוּת וְהַיְינוּ בְּהֵיכָלוֹת דִּבְרִיאָה, וְאִם הַפְּסַק דִּין שֶׁאוֹתוֹ הַחֶסֶד שֶׁנִּקְצַב לְאָדָם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים אֵין בְּאֶפְשָׁרִי שֶׁיּוּמְשַׁךְ מִמֶּנּוּ לְמַטָּה כָּל הַחוּט הַמְשׁוּלָּשׁ דְּבָנֵי חַיֵּי וּמְזוֹנֵי כִּי אִם לִשְׁנַיִם מֵהֶם עַל דֶּרֶךְ מָשָׁל, אֲזַי יֵשׁ מִשְׁפָּט לְמָה יוּמְשַׁךְ שֶׁפַע הַחֶסֶד אִם לְבָנֵי וְחַיֵּי שֶׁיִּהְיוּ לוֹ בָּנִים חַיִּים וְקַיָּימִים וּבְרִיאוּת בִּכְלָלוּת נַפְשׁוֹת בֵּיתוֹ אוֹ לִמְזוֹנֵי רְוִיחֵי וְחַיֵּי שֶׁיִּהְיֶה לוֹ עוֹשֶׁר וּבְרִיאוּת.\n<b>וּבָזֶה</b> מוֹעֶלֶת תְּפִלַּת הַצַּדִּיק לְהַחֲלִיף מֵעִנְיָן לְעִנְיָן, וּבָזֶה יוּבַן הַמַּעֲשֶׂה שֶׁאֵירַע אֵצֶל הַבַּעַל שֵׁם טוֹב נִשְׁמָתוֹ עֵדֶן בְּאֶחָד שֶׁהִתְאַמֵּץ בְּבַקָּשָׁתוֹ שֶׁיִּתְפַּלֵּל עֲבוּרוֹ לְהִוָּושֵׁעַ בְּבָנִים וְהָאִישׁ הַהוּא הָיָה עָשִׁיר גָּדוֹל וְלֹא עָנָהוּ הַבַּעַל שֵׁם טוֹב נִשְׁמָתוֹ עֵדֶן עַל בַּקָּשָׁתוֹ, עַד כִּי פַּעַם הִתְאַמְּצוּ הָאִישׁ וְאִשְׁתּוֹ בְּיוֹתֵר וְרָאָה הַבַּעַל שֵׁם טוֹב נִשְׁמָתוֹ עֵדֶן כִּי חֲפֵצִים הֵמָּה בֶּאֱמֶת מִקִּירוֹת הַלֵּב, וַיֹּאמֶר לָהֶם כִּי כְּשֶׁיּוֹלִידוּ בָנִים יְאַבְּדוּ הָעֲשִׁירוּת וְיִהְיוּ עֲנִיִּים וַיִּבְחֲרוּ בְּבָנִים וַיּוֹלִידוּ בָנִים וְנַעֲשׂוּ עֲנִיִּים.\n<b>וְהַיְינוּ</b> שֶׁהַבַּעַל שֵׁם טוֹב נִשְׁמָתוֹ עֵדֶן הֶחֱלִיף שֹׁרֶשׁ הַחֶסֶד לְמַעְלָה שֶׁנִּמְשַׁךְ לוֹ עַל יְדֵי הַבֵּית דִּין שֶׁל מַעְלָה עַל עוֹשֶׁר הֶחֱלִיף אוֹתוֹ עַל בָּנִים, וְהַיְינוּ מִפְּנֵי שֶׁהַחֶסֶד הַנִּקְצַב לוֹ לֹא הָיָה נִמְשָׁךְ מִמֶּנּוּ שְׁנֵי דְבָרִים וְהֶחֱלִיף אוֹתוֹ בִּתְפִלָּתוֹ מֵעֲשִׁירוּת לְבָנִים.\n<b>גַּם</b> הַדִּין הוּא אִם רָאוּי וּכְדַאי הָאָדָם שֶׁיּוּמְשַׁךְ וְיִשְׁתַּלְשֵׁל הַחֶסֶד הַהוּא בַּעֲשִׂיָּה בָּעוֹלָם הַזֶּה הַגַּשְׁמִית, אוֹ אֶפְשָׁר אֵינוֹ רָאוּי אָז לָזֶה בַּיּוֹם הַהוּא לְפִי מַעֲשָׂיו, וַהֲגַם שֶׁכְּבָר נִקְצַב לוֹ חֶסֶד בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים יוּמְשַׁךְ לוֹ הַחֶסֶד בְּרוּחָנִיּוּת אוֹ יְקַבְּלוֹ לָעוֹלָם הַבָּא כו',\nוְעַל פִּי זֶה יִתַּוְּוכוּ ב' הַמַּאֲמָרִים הַנַ\"ל דִּמְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִים לוֹ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וּמִכָּל מָקוֹם אָדָם נִידּוֹן בְּכָל יוֹם, כִּי קְצוּבִים לוֹ הַיְינוּ שֶׁנִּקְצְבָה לוֹ הַמְשָׁכַת חֶסֶד עֶלְיוֹן מֵרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים עַל כָּל הַשָּׁנָה, וְאַף עַל פִּי כֵן אָדָם נִידּוֹן בְּכָל יוֹם הַיְינוּ בְּאוֹפַנֵּי צִיּוּרֵי הַחֶסֶד בְּאֵיזֶה חֶסֶד יִצְטַיֵּיר בָּעוֹלָם הַזֶּה בְּפוֹעַל כו'.\n<b>וְעַל</b> פִּי זֶה יוּבַן מַה שֶּׁאָנוּ מִתְפַּלְלִים וּמְבַקְשִׁים בְּכָל יוֹם רְפוּאָה וּפַרְנָסָה כו', דְּאַף עַל פִּי שֶׁכְּבָר נִקְצַב בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים מִכָּל מָקוֹם זֶהוּ רַק בִּכְלָלוּת הַחֶסֶד אֲבָל אֵין בּוֹ עֲדַיִין תּוֹאַר מֵהָעִנְיָנִים הַגַּשְׁמִים, וּבְכָל יוֹם אָנוּ מְבַקְשִׁים שֶׁהַחֶסֶד הַנִּקְצַב לוֹ וְנִמְשַׁךְ מִבְּחִינַת מַלְכוּת דַּאֲצִילוּת יִתְלַבֵּשׁ בְּעִנְיָנִים גַּשְׁמִים הָאֵלּוּ. וְזֶהוּ גַם כֵּן מַה שֶּׁהִתְפַּלֵּל רַב יֵיבָא סָבָא עַל סְעוּדָּתוֹ אַף עַל פִּי שֶׁהִיא כְּבָר מוּכֶנֶת לְפָנָיו, מִפְּנֵי שֶׁיָּכוֹל לִהְיוֹת שֶׁאֵין זֶה שֶׁלּוֹ וְעַל זֶה הִתְפַּלֵּל שֶׁתָּבֹא הִתְלַבְּשׁוּת שֹׁרֶשׁ חַסְדּוֹ בְּמָזוֹן הַזֶּה.\nקִיצּוּר.\nשֵׁשֶׁת יָמִים עִנְיָנָם בִּסְפִירוֹת וּבַעֲבוֹדָה. מְלֶאכֶת אָדָם לְחַבֵּר זְמַן וּמָקוֹם וּלְיַחֲדָם בֵּאלֹקוּת בְּכָל יוֹם כְּפִי מַעֲלָתוֹ בְּסוֹד הַסְּפִירוֹת, וְעַל זֶה הוּא הַדִּין אִם שֶׁפַע הַנִּקְצַב יָבֹא בְּגַשְׁמִיּוּת אוֹ רַק בְּרוּחָנִיּוּת, וְאִם בְּבָנֵי חַיֵּי וּמְזוֹנֵי אוֹ בְּאֶחָד מֵהֶם וְאֶפְשָׁר לְהַחֲלִיף מֵעִנְיָן לְעִנְיָן. הַבַּעַל שֵׁם טוֹב נִשְׁמָתוֹ עֵדֶן הֶחֱלִיף עֲשִׁירוּת עַל בָּנִים."],[4401900079,"<h2>מַאֲמָר כ.</h2>\nוְהִנֵּה זֶה שֶׁהָאָדָם נִידּוֹן בְּכָל יוֹם, הוּא דַּעַת רַבִּי יוֹסֵי בִּבְרַיְיתָא דְרֹאשׁ הַשָּׁנָה (טז. א) וּלְדַעַת רַבִּי נָתָן נִידּוֹן בְּכָל שָׁעָה שֶׁנֶּאֱמַר לִרְגָעִים תִּבְחָנֶנּוּ (אִיּוֹב ז. יח) וְהִקְשׁוּ עַל זֶה דְּאִם כֵּן לְרַבִּי יוֹסֵי וּלְרַבִּי נָתָן אֵין בֵּין רֹאשׁ הַשָּׁנָה לְכָל יְמוֹת הַשָּׁנָה כְּלוּם לְעִנְיַן דִּין שֶׁל מַעְלָה וְאֵיךְ יְפָרְשׁוּ הַפָּסוּק דְּכִי חֹק לְיִשְׂרָאֵל הוּא מִשְׁפָּט לֵאלֹקֵי יַעֲקֹב (תְּהִלִּים פא. ה) דְּקָאֵי עַל רֹאשׁ הַשָּׁנָה.\n<b>וְגַם</b> מַה שֶּׁכָּתוּב עֵינֵי ה' אֱלֹקֶיךָ בָּהּ מֵרֵאשִׁית הַשָּׁנָה (דְּבָרִים יא. יב) שֶׁמִּזֶּה לָמְדוּ בִּגְמָרָא (שָׁם ח סוֹף עַמּוּד א) דְּרֹאשׁ הַשָּׁנָה הוּא רֹאשׁ הַשָּׁנָה לְדִין,\nוְעוֹד מַהוּ עִנְיַן מַלְכִיּוֹת זִכְרוֹנוֹת וְשׁוֹפְרוֹת שֶׁאוֹמְרִים בְּרֹאשׁ הַשָּׁנָה, וּמַה יּוֹם מִיּוֹמַיִים, וְאֵין לְהַעֲלוֹת עַל הַדַּעַת כְּלָל דִּלְרַבִּי יוֹסֵי וּלְרַבִּי נָתָן אֵין חִידּוּשׁ בְּרֹאשׁ הַשָּׁנָה לְגַבֵּי שְׁאָר הַיָּמִים,\nאֶלָּא וַדַּאי אֵין מַחֲלוֹקֶת בָּזֶה כְּלָל אֲשֶׁר רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים הוּא יוֹם הַדִּין, וְכֵן כָּתַב בַּעֲשָׂרָה מַאֲמָרוֹת מַאֲמַר חִקּוּר דִּין חֵלֶק ב פֶּרֶק א וּפֶרֶק כ\"ו שֶׁלֹּא נֶחֱלַק אָדָם בַּדָּבָר, וְהַיְינוּ דְּהַכֹּל מוֹדִים שֶׁאָז נֶחְתָּךְ קִצְבַת הַחֶסֶד לְכָל בְּרִיָּה כו', וְלָכֵן אוֹמְרִים מַלְכִיּוֹת זִכְרוֹנוֹת וְשׁוֹפְרוֹת בְּרֹאשׁ הַשָּׁנָה בִּכְדֵי שֶׁתַּמְלִיכוּנִי עֲלֵיכֶם כו'\nדְּבִנְיַן הַמַּלְכוּת דַּאֲצִילוּת הוּא מֵרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים, שֶׁאָז בִּנְעִילָה מְקַבֶּלֶת הַמַּלְכוּת מֵה' גְבוּרוֹת דְּעַתִּיק, וְהוּא הַמְשָׁכַת מְקוֹר הַחַיּוּת לִבְרִיאָה-יְצִירָה-עֲשִׂיָּה לְכָל הַשָּׁנָה, וְהַיְינוּ דִּבְרֹאשׁ הַשָּׁנָה נִמְשָׁךְ הַחֶסֶד כְּפִי שֶׁנִּקְצָב לְכָל הָעוֹלָם בִּכְלָל, וּבִנְעִילָה דְיוֹם הַכִּפּוּרִים נֶחְתָּם וְנֶחְתָּךְ קִצְבַת הַחֶסֶד לְכָל אֶחָד וְאֶחָד בִּפְרָט וְזֶה לְדִבְרֵי הַכֹּל,\nאֶלָּא דְּמִכָּל מָקוֹם סְבִירָא לֵיהּ לְרַבִּי יוֹסֵי וְרַבִּי נָתָן, דְּאָדָם נִידּוֹן בְּכָל יוֹם דִּין וּמִשְׁפָּט גָּמוּר עַל כָּל הָעִנְיָנִים לְחוֹלִי וְלִבְרִיאוּת וּלְחַיִּים כו', וְהַיְינוּ לְפִי שֶׁהַחֶסֶד הַקָּצוּב לוֹ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים אַף שֶׁכְּבָר נִמְשַׁךְ לִבְחִינַת מַלְכוּת דַּאֲצִילוּת אֵין בּוֹ עֲדַיִין שׁוּם תּוֹאַר וּתְמוּנָה מֵעִנְיְנֵי עוֹלָם הַזֶּה, כִּי אֵין עֲרוֹךְ עֲשִׂיָּה לְגַבֵּי אֲצִילוּת, עַל כֵּן אַף שֶׁיּוּכַל לִהְיוֹת מִמֶּנּוּ כָּל הַשְׁפָּעוֹת עִנְיְנֵי עוֹלָם הַזֶּה, מִכָּל מָקוֹם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים לֹא נִגְמַר הַמִּשְׁפָּט בְּפֵירוּשׁ מַה יִּהְיֶה מֵהַחֶסֶד הַזֶּה וּבַמֶּה תִּהְיֶה הַהַשְׁפָּעָה אִם בְּבָנֵי אוֹ בְּחַיֵּי אוֹ בִּמְזוֹנֵי אוֹ בְּכֻלָּם אוֹ בְּעִנְיָנִים הָרוּחָנִים וּבְחַיֵּי עוֹלָם הַבָּא, וְהַדִּין וּמִשְׁפָּט בַּמֶּה תִּהְיֶה הַהַשְׁפָּעָה הוּא בְּבֵית דִּין שֶׁלְּמַעְלָה בְּהֵיכָלוֹת דִּבְרִיאָה וִיצִירָה כו', וְזֶהוּ הַדִּין וּמִשְׁפָּט שֶׁבְּכָל יוֹם מַמָּשׁ וּכְמוֹ שֶׁנִּתְבָּאֵר.\n<b>וְהַדִּין</b> וּמִשְׁפָּט דְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים הוּא קִצְבַת הַחֶסֶד שֶׁיּוּמְשַׁךְ לְכָל הָעוֹלָם בִּכְלָל וּלְכָל בְּרִיָּה בִּפְרָט כַּמָּה מֵהַחֶסֶד נִקְצַב אֵלָיו, וְזֶה עִיקַּר הַדִּין וּבוֹ תָּלוּי הַכֹּל כִּי לְפִי רִיבּוּי קִצְבַת הַחֶסֶד כַּךְ תִּהְיֶה הַבְּרָכָה וְהַטּוֹב כָּל הַשָּׁנָה מַה שֶּׁאֵין כֵּן בְּמִיעוּטוֹ חַס וְשָׁלוֹם, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר יט פֶּרֶק ב) דְּכַאֲשֶׁר הַחֶסֶד בְּרִיבּוּי יֵשׁ בְּאֶפְשָׁרִי שֶׁתִּהְיֶה הַשְׁפָּעַת הַחֶסֶד בְּכָל הַדְּבָרִים דְּבָנֵי חַיֵּי וּמְזוֹנֵי וְלִפְעָמִים אֵין בְּאֶפְשָׁרִי שֶׁיִּהְיוּ כָּל הַדְּבָרִים כִּי אִם שְׁנַיִם מֵהֶם אוֹ אֶחָד מֵהֶם כו', וְגַם אִם אֲפִילוּ בְּכָל הַג' דְּבָרִים יֵשׁ נַפְקָא מִינָּהּ אִם בְּרִיבּוּי אוֹ בְּצִמְצוּם חַס וְשָׁלוֹם, וְזֶה תָּלוּי בִּכְלָלוּת קִצְבַת הַחֶסֶד בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים לְכָל הָעוֹלָם בִּכְלָל וְאֵלָיו בִּפְרָט אִם בְּרִיבּוּי אוֹ כו',\nמִכָּל מָקוֹם יֵשׁ דִּין וּמִשְׁפָּט בִּפְרָט בְּכָל יוֹם מַה יִּצְטַיֵּיר וְיוּמְשַׁךְ מֵהַחֶסֶד הַזֶּה, וּכְמוֹ אִם יֵשׁ בְּאֶפְשָׁרוּת הַחֶסֶד שֶׁנִּקְצַב אֵלָיו בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁיִּהְיוּ ב' דְּבָרִים מֵהַג' הַנַ\"ל אֵיזֶה ב' דְבָרִים יִהְיוּ אִם בָּנֵי וְחַיֵּי אוֹ מְזוֹנֵי וְחַיֵּי וְכַדּוֹמֶה וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל. וְגַם אִם יֵשׁ בְּאֶפְשָׁרִי עַל כָּל הַג' דְּבָרִים הַנַ\"ל מִכָּל מָקוֹם הַמִּשְׁפָּט הוּא אוּלַי יִהְיֶה הַחֶסֶד הַזֶּה הַשְׁפָּעוֹת עִנְיָנִים רוּחָנִים אוֹ לְחַיֵּי עוֹלָם הַבָּא וכו', מֵאַחַר שֶׁבְּהַחֶסֶד שֶׁנִּקְצַב בְּרֹאשׁ הַשָּׁנָה אֵינוֹ נִיכָּר עֲדַיִין מַה שֶּׁיִּהְיֶה מִמֶּנּוּ הַהַשְׁפָּעָה בַּעֲשִׂיָּה שֶׁאֵין שָׁם תּוֹאַר זֶה כְּלָל כִּי אִם זֶה תָּלוּי בְּבֵית דִּין שֶׁל מַעְלָה. וְזֶהוּ לְפִי מַעֲשָׂיו, כֵּן הוּא הַדִּין וּמִשְׁפָּט בְּהֵיכָלוֹת דִּבְרִיאָה.\n<b>וְנִמְצָא</b> שְׁנֵיהֶם אֱמֶת, דְּעִיקַּר הַדִּין עַל הַמְשָׁכַת הַחֶסֶד הוּא בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, וּמִכָּל מָקוֹם יֵשׁ דִּין וּמִשְׁפָּט גָּמוּר בְּכָל יוֹם.\nקִיצּוּר.\nקִצְבַת הַחֶסֶד דְּעַתִּיק בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכֵּפּוּרִים אֵין בּוֹ עֲדַיִין שׁוּם תּוֹאַר מֵעִנְיְנֵי עוֹלָם הַזֶּה, גַּם בִּלְתִּי מְחוּלָּק בְּאֵיכוּת וְכַמּוּת בְּבָנֵי חַיֵּי וּמְזוֹנֵי, וְעַל זֶה הוּא הַדִּין בְּכָל יוֹם לְדַעַת רַבִּי יוֹסֵי וּבְכָל שָׁעָה לְדַעַת רַבִּי נָתָן."],[4401900080,"<h2>מַאֲמָר כא.</h2>\nאָמְנָם דַּעַת רַבָּנָן בְּעִנְיַן הַדִּין וּמִשְׁפָּט דִּמְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִין לוֹ מֵרֹאשׁ הַשָּׁנָה וְכָל צְרָכָיו שֶׁל הָאָדָם וּבְנֵי בֵיתוֹ בְּבָנֵי חַיֵּי וּמְזוֹנֵי הֵם בִּכְלַל הַמְּזוֹנוֹת, וּסְבִירָא לְהוּ דִּגְזַר דִּינוֹ שֶׁל אָדָם נֶחְתָּם בְּיוֹם הַכִּפּוּרִים (שָׁם בִּגְמָרָא) דִּבְרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים נִגְמָר פְּרָטֵי עִנְיְנֵי הָאָדָם עַל כָּל הַשָּׁנָה לְחַיִּים אוֹ כו' וְכֵן לְכָל הַמְּאוֹרָעוֹת שֶׁלּוֹ, אִם כֵּן לְפִי זֶה אִי אֶפְשָׁר לוֹמַר שֶׁבְּהַחֶסֶד עֶלְיוֹן הַנִּקְצָב לוֹ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים לֹא נִצְטַיֵּיר מֵעִנְיְנֵי עוֹלָם הַזֶּה כְּלָל, דְּאִם כֵּן מַהוּ עִנְיָן שֶׁנִּכְתָּב וְנֶחְתָּם וּמַהוּ עִנְיָן שֶׁנִּגְמָר כָּל מַה שֶּׁיֶּאֱרַע לוֹ, אֶלָּא בְּהֶכְרַח לוֹמַר דִּבְהַחֶסֶד שֶׁנִּקְצָב לוֹ נִיתַּן תּוֹאַר וּתְמוּנָה מִמַּה שֶּׁיּוּמְשַׁךְ מִזֶּה בָּעוֹלָם הַזֶּה, וְלִכְאוֹרָה אֵין זֶה מוּבָן וַהֲלֹא אֵין עֲרוֹךְ עֲשִׂיָּה לְגַבֵּי אֲצִילוּת וְאִם כֵּן אֵיךְ בְּהַחֶסֶד שֶׁנִּמְשָׁךְ לְמַלְכוּת דַּאֲצִילוּת יִהְיֶה בוֹ תּוֹאַר וְצִיּוּר מֵעִנְיְנֵי עוֹלָם הַזֶּה.\n<b>אַךְ</b> הָעִנְיָן יוּבַן עַל פִּי מַה דְּאִיתָא בְּתוֹרָה אוֹר (פַּרְשַׁת וַיֵּרָא דְּרוּשׁ הַמַּתְחִיל פָּתַח אֵלִיָּהוּ) דְּיוֹתֵר מִמַּה שֶּׁאֵין עֲרוֹךְ עֲשִׂיָּה לְגַבֵּי אֲצִילוּת אֵין עֲרוֹךְ אֲצִילוּת לְגַבֵּי אוֹר אֵין סוֹף עַצְמוּת וּמַהוּת, דְּהִנֵּה הֲגַם שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר יט פֶּרֶק א) דַּאֲצִילוּת מוּבְדָּל מֵעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה, מִכָּל מָקוֹם הֲרֵי אֲצִילוּת הוּא גַם כֵּן עוֹלָם וְיֵשׁ בּוֹ עֶשֶׂר סְפִירוֹת בִּבְחִינַת אוֹרוֹת וְכֵלִים. וַהֲגַם שֶׁהוּא אֱלֹקוּת מַמָּשׁ מִכָּל מָקוֹם נִקְרָא אֱלֹקוּת וְלֹא אֱלֹקַהּ שֶׁמּוֹרֶה עַל הָעַצְמוּת, אֲבָל אֱלֹקות פֵּירוּשׁ גֶעטְלִיךְ, דְּהַיְינוּ שֶׁהוּא הִתְפַּשְּׁטוּת הֶאָרָה לְבָד, וּמִשּׁוּם זֶה שַׁיָּיךְ שָׁם עֶשֶׂר סְפִירוֹת וּבִפְרָט בְּהַכֵּלִים שֶׁהֵם בִּבְחִינַת מְצִיאוּת סְפִירוֹת חָכְמָה וָחֶסֶד, וְלָכֵן הִנֵּה מֵעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת נִמְשָׁכִים עֶשֶׂר סְפִירוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת עִלָּה וְעָלוּל שֶׁיֵּשׁ לָהֶם עֶרֶךְ וְשַׁיָּיכוּת זֶה לָזֶה,\nדְּהִשְׁתַּלְשְׁלוּת וְהִתְהַוּוּת חָכְמָה דַעֲשִׂיָּה מֵחָכְמָה דַאֲצִילוּת הוּא עַל דֶּרֶךְ מָשָׁל מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בְּרֵאשִׁית רַבָּה פַּרְשָׁה יו\"ד) אֵין לְךָ עֵשֶׂב מִלְּמַטָּה שֶׁאֵין לוֹ מַזָּל מִלְמַעְלָה הַמַּכֶּה בוֹ וְאוֹמֵר גְּדַל כו' וְגָבוֹהַּ מֵעַל גָּבוֹהַּ וְגָבוֹהַּ עֲלֵיהֶם דְּכָל הָעִנְיָנִים שֶׁיֶּשְׁנָם בְּעֵשֶׂב וּפְרִי הַגַּשְׁמִים הֲרֵי יֶשְׁנָם בְּמַזָּל הָרוּחָנִי וּבְכָל הַדַּרְגּוֹת דְּגָבוֹהַּ מֵעַל גָּבוֹהַּ. וְהִנֵּה הַתַּפּוּחַ הַגַּשְׁמִי יֵשׁ בּוֹ מְתִיקוּת גַּשְׁמִי הַאִם נֹאמַר שֶׁיֵּשׁ בְּכֹחַ הַצּוֹמֵחַ שֶׁבָּאָרֶץ גַּם כֵּן מְתִיקוּת, וּפְשִׁיטָא שֶׁאִי אֶפְשָׁר לוֹמַר כֵּן עַל הַמַּזָּל הָרוּחָנִי וְעַל הַדַּרְגּוֹת דְּגָבוֹהַּ מֵעַל גָּבוֹהַּ שֶׁאֵינָם בְּעֶרֶךְ וּמַהוּת זֶה, וּבֶאֱמֶת הִנֵּה הַטְּעָמִים דִּמְתִיקוּת וּמְרִירוּת גַּשְׁמִים נִמְשָׁכִים מִשָּׁרְשָׁם בְּחֶסֶד וּגְבוּרָה, שֶׁהַמְּתִיקוּת נִמְשָׁךְ מֵהַחֶסֶד וּמְרִירוּת מִגְּבוּרָה, וַהֲרֵי חֶסֶד וּגְבוּרָה הֵן עִנְיָנִים רוּחָנִים, רַק שֶׁבְּהִשְׁתַּלְשְׁלוּת וְסֵדֶר יְרִידַת הַמַּדְרֵיגוֹת מַדְרֵיגָה אַחַר מַדְרֵיגָה נִתְגַּשְּׁמוּ עַד שֶׁנִּמְשָׁךְ מִבְּחִינַת הַחֶסֶד מְתִיקוּת,\nעִם הֱיוֹת שֶׁאֵין עֲרוֹךְ אֵלָיו מִכָּל מָקוֹם הוּא מִמִּזְגּוֹ וּתְכוּנָתוֹ, וּכְמוֹ שֶׁרוֹאִים כַּמָּה מִינֵי עֲרֵיבוּת וּמְתִיקוּת בְּרוּחָנִיּוּת, וּכְמוֹ תַּעֲנוּג שֶׁל דְּבַר חָכְמָה הוּא גַם כֵּן מְתִיקוּת, וְכֵן תַּעֲנוּג שֶׁל נִיגּוּן שֶׁהוּא לְמַטָּה בְּמַדְרֵיגָה מִמֶּנּוּ, וְלָכֵן בְּכַמָּה יְרִידוֹת וְהִשְׁתַּלְשְׁלֻיּוֹת נַעֲשָׂה מְתִיקוּת גַּשְׁמִי מַמָּשׁ,\nוְכֵן הוּא הָעִנְיָן בְּחָכְמָה שֶׁיֵּשׁ בָּהּ גַּם כֵּן גָּבוֹהַּ מֵעַל גָּבוֹהַּ, וְהַחָכְמָה שֶׁבְּעֶשֶׂר סְפִירוֹת דַּעֲשִׂיָּה יֵשׁ לָהּ גַּם כֵּן עֶרֶךְ וְיִחוּס לְחָכְמָה דַאֲצִילוּת, דְּעַל יְדֵי רִיבּוּי רְבָבוֹת הִשְׁתַּלְשְׁלֻיּוֹת מַדְרֵיגוֹת נִמְשָׁךְ מֵחָכְמָה דַאֲצִילוּת חָכְמָה דַעֲשִׂיָּה,\nוַהֲגַם דְּאֲצִילוּת מוּבְדָּל מִבְּרִיאָה-יְצִירָה-עֲשִׂיָּה וְאֵיךְ הוּא בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת עִלָּה וְעָלוּל, הָעִנְיָן הוּא דְּהַהִשְׁתַּלְשְׁלוּת זֹאת אֵינָהּ כְּמוֹ הַהִשְׁתַּלְשְׁלוּת בְּעוֹלָם אֲצִילוּת גּוּפָא בְּהָעֶשֶׂר סְפִירוֹת שֶׁבּוֹ, אוֹ בְּעוֹלָם הַבְּרִיאָה וּשְׁאָרֵי הָעוֹלָמוֹת בְּסֵדֶר הַהִשְׁתַּלְשְׁלוּת שֶׁבְּאוֹתוֹ הָעוֹלָם, אֶלָּא שֶׁהַהִשְׁתַּלְשְׁלוּת מֵאֲצִילוּת לִבְרִיאָה הוּא עַל יְדֵי הַפַּרְסָא, דְּעִנְיַן הַפַּרְסָא הוּא כְּמוֹ הַמָּשָׁל אֶל הַשֵּׂכֶל, שֶׁהַמָּשָׁל הוּא דָּבָר זָר מֵהַשֵּׂכֶל, וְלָכֵן הוּא מַעְלִים עָלָיו לְגַמְרֵי עַד שֶׁיֵּשׁ כָּאֵלּוּ שֶׁאֵינָם מְבִינִים כְּלָל שֶׁיֵּשׁ בָּזֶה אֵיזֶה נִמְשָׁל, אָמְנָם אַחַר כַּךְ כְּשֶׁמִּתְגַּלֶּה הַשֵּׂכֶל מִן הַמָּשָׁל וַדַּאי שֶׁאֵינוֹ בְּמַהוּת אוֹר הַשֵּׂכֶל כְּמוֹ שֶׁהָיָה קוֹדֶם שֶׁנִּתְלַבֵּשׁ בְּמָשָׁל, וּמִכָּל מָקוֹם הֲרֵי אֵינוֹ שֵׂכֶל אַחֵר, וַהֲרֵי הוּא אוֹתוֹ הַשֵּׂכֶל שֶׁנִּתְלַבֵּשׁ בְּהַמָּשָׁל אֶלָּא שֶׁהוּא בְּאוֹפֶן וּמַהוּת אַחֵר,\nוּכְמוֹ כֵן הוּא עִנְיַן הַפַּרְסָא שֶׁמַּעְלִים וּמַסְתִּיר עַל בְּחִינַת חָכְמָה דַאֲצִילוּת וּכְשֶׁנַּעֲשָׂה בְּחִינַת חָכְמָה דִבְרִיאָה עַל יְדֵי הַפַּרְסָא הוּא כְּמוֹ אוֹר הַשֵּׂכֶל שֶׁמִּתְגַּלֶּה עַל יְדֵי הַמָּשָׁל, הֲרֵי הוּא אוֹר שֶׁל תּוֹלָדָה, וְהַיְינוּ אוֹר שֶׁנִּתְחַדֵּשׁ בְּעוֹלָם הַבְּרִיאָה, לְפִי שֶׁאֵינוֹ כְּלָל כְּמוֹ אוֹפֶן הַחָכְמָה שֶׁהִיא בַּאֲצִילוּת, אֲבָל מִכָּל מָקוֹם גַּם כֵּן אֵינָהּ מַהוּת וְדָבָר אַחֵר לְגַמְרֵי שֶׁהֲרֵי הִיא הַמְשָׁכָה וְהִתְהַוּוּת מִבְּחִינַת חָכְמָה דַאֲצִילוּת אֶלָּא שֶׁהוּא אוֹפֶן אַחֵר,\nוְאֵינוֹ דוֹמֶה כְּמוֹ חָכְמָה דַאֲצִילוּת לְגַבֵּי אוֹר אֵין סוֹף, דִּבְאוֹר אֵין סוֹף עַצְמוּת וּמַהוּת הֲרֵי לֹא יֵשׁ שָׁם בְּחִינַת חָכְמָה כְּלָל וְאֵינוֹ מִגֶּדֶר הַחָכְמָה כְּלָל, וְאִם כֵּן בְּחִינַת חָכְמָה דַאֲצִילוּת הוּא בְּאֵין עֲרוֹךְ מַמָּשׁ לְגַבֵּי אוֹר אֵין סוֹף אֲבָל בַּאֲצִילוּת הֲרֵי כְּבָר יֵשׁ בְּחִינַת חָכְמָה, וְאִם כֵּן בְּחִינַת חָכְמָה דִבְרִיאָה וּכְמוֹ כֵן חָכְמָה דַעֲשִׂיָּה אֵינוֹ בִּבְחִינַת אֵין עֲרוֹךְ לְגַמְרֵי, אֶלָּא שֶׁחָכְמָה דַאֲצִילוּת מוּבְדֶּלֶת מֵחָכְמָה דִבְרִיאָה וְלָכֵן הִנֵּה הִתְהַוּוּתָם הוּא עַל יְדֵי הַפַּרְסָא דְּהַיְינוּ שֶׁבָּא בְּאוֹפֶן אַחֵר מִבְּחִינַת חָכְמָה דַאֲצִילוּת, אֲבָל מִכָּל מָקוֹם יֵשׁ לָהֶם עֶרֶךְ וְיַחַס אֶל חָכְמָה דַאֲצִילוּת.\nקִיצּוּר.\nבְּעוֹלָם אֲצִילוּת עֶשֶׂר סְפִירוֹת אוֹרוֹת וְכֵלִים, חָכְמָה דַעֲשִׂיָּה לְגַבֵּי חָכְמָה דַאֲצִילוּת כְּעֶרֶךְ מְתִיקוּת גַּשְׁמִי לְגַבֵּי חֶסֶד הָרוּחָנִי וְעִם זֶה מִשְׁתַּלְשֵׁל מִמֶּנּוּ, הִשְׁתַּלְשְׁלוּת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה מֵאֲצִילוּת הוּא עַל יְדֵי הַפַּרְסָא כְּדוּגְמַת הַשֵּׂכֶל הַמִּתְגַּלֶּה מֵהַמָּשָׁל, אֲצִילוּת מוּבְדָּל מִבְּרִיאָה-יְצִירָה-עֲשִׂיָּה וְיֵשׁ לָהֶן יַחַס אֵלָיו."],[4401900081,"וְזֶהוּ שֶׁאָמַר רַבֵּינוּ נִשְׁמָתוֹ עֵדֶן דְּיוֹתֵר מִמַּה שֶּׁאֵין עֲרוֹךְ עֲשִׂיָּה לְגַבֵּי אֲצִילוּת אֵין עֲרוֹךְ אֲצִילוּת לְגַבֵּי אוֹר אֵין סוֹף, דִּבְאוֹר אֵין סוֹף עַצְמוּת וּמַהוּת לֹא יֵשׁ כְּלָל עִנְיַן הַסְּפִירוֹת וְעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת הֵן כְּמַהוּת חָדָשׁ מַמָּשׁ, וְלָכֵן הִתְהַוּוּת עֶשֶׂר סְפִירוֹת דַּאֲצִילוּת מֵאוֹר אֵין סוֹף הוּא עַל יְדֵי צִמְצוּם וּמָקוֹם פָּנוּי, שֶׁהוּא עִנְיַן הִתְעַלְּמוּת אוֹר הָרִאשׁוֹן לְגַמְרֵי, וְאָז נַעֲשֶׂה דָּבָר שֶׁאֵינוֹ מִמַּהוּת אוֹר הָרִאשׁוֹן כְּלָל,\nאֲבָל עֲשִׂיָּה לְגַבֵּי אֲצִילוּת יֵשׁ לָהּ עֶרֶךְ וְיַחַס מֵאַחַר שֶׁגַּם בַּאֲצִילוּת יֵשׁ מְצִיאוּת בְּחִינַת חָכְמָה, וְאִם כֵּן אִי אֶפְשָׁר לוֹמַר דְּחָכְמָה דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הוּא מַהוּת חָדָשׁ מַמָּשׁ שֶׁהֲרֵי כְּבָר יֵשׁ בְּחִינַת חָכְמָה גַּם בַּאֲצִילוּת, וּבְהֶכְרַח שֶׁגַּם בְּחִינַת חָכְמָה דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה כְּלוּלָה בְּחָכְמָה דַּאֲצִילוּת מֵאַחַר שֶׁהִיא גַם כֵּן בְּחִינַת חָכְמָה, וְרַק שֶׁהִיא בְּחִינָה וּמַדְרֵיגָה עֶלְיוֹנָה וְיָדוּעַ דְּכָל מַדְרֵיגָה עֶלְיוֹנָה כּוֹלֶלֶת בְּתוֹכָהּ כָּל מַה שֶּׁלְּמַטָּה מִמֶּנָּה,\nוְהִתְהַוּוּת הַחָכְמָה דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה מֵחָכְמָה דַאֲצִילוּת הוּא בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת עִלָּה וְעָלוּל, אֶלָּא שֶׁחָכְמָה דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה נִקְרֵאת אוֹר שֶׁל תּוֹלָדָה וְאוֹר חָדָשׁ, וְטַעַם הַדָּבָר הוּא לְפִי שֶׁהוּא בְּאוֹפֶן אַחֵר מִבְּחִינַת חָכְמָה דַאֲצִילוּת וְנִתְהַוָּוה בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה עַל יְדֵי הַפַּרְסָא, דְּעִנְיַן הַפַּרְסָא הוּא כְּמוֹ הַמָּשָׁל כַּנַ\"ל שֶׁהַמָּשָׁל הוּא בֶּאֱמֶת דָּבָר אַחֵר לְגַמְרֵי מֵהַנִּמְשָׁל, וּכְמוֹ כֵן הוּא עִנְיַן הַפַּרְסָא שֶׁהוּא דָּבָר אַחֵר לְגַמְרֵי שֶׁאֵינוֹ בְּחִינַת אֲצִילוּת וְעַל יְדֵי זֶה נִמְצָא בְּחִינַת חָכְמָה בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה,\nהֲרֵי זֶהוּ שֶׁנִּתְחַדֵּשׁ בְּחִינַת הַחָכְמָה עַל יְדֵי דָבָר זָר לְגַמְרֵי וּמִשּׁוּם זֶה נִקְרָא הִתְחַדְּשׁוּת, אֲבָל מִכָּל מָקוֹם בְּעֶצֶם הֲרֵי הַחָכְמָה אֵינָהּ דָּבָר חָדָשׁ הַיְינוּ שֶׁיִּהְיֶה דָּבָר אַחֵר לְגַמְרֵי, וְלָכֵן הַהִתְהַוּוּת הוּא עַל יְדֵי הַפַּרְסָא שֶׁאֵינוֹ דוֹמֶה לְעִנְיַן הַצִּמְצוּם, דְּעִנְיַן הַצִּמְצוּם הוּא סִילּוּק וְהֶעְלֵם אוֹר הָרִאשׁוֹן, אֲבָל הַפַּרְסָא הֲרֵי הָאוֹר הָרִאשׁוֹן (שֶׁהוּא בְּחִינַת הַחָכְמָה דַאֲצִילוּת) מִתְלַבֵּשׁ וּמִתְעַלֵּם בְּהַפַּרְסָא לְהַוּוֹת בְּחִינַת חָכְמָה בִּבְרִיאָה, וּכְמוֹ בְּהַמָּשָׁל הֲרֵי הַנִּמְשָׁל מְלוּבָּשׁ מַמָּשׁ בְּהַמָּשָׁל וּמִמֶּנּוּ מִתְחַדֵּשׁ הַשֵּׂכֶל אֵצֶל הַמְקַבֵּל, וּכְמוֹ כֵן בְּחִינַת חָכְמָה דַאֲצִילוּת מְלוּבֶּשֶׁת מַמָּשׁ בְּהַפַּרְסָא וּמִזֶּה מִתְחַדֵּשׁ בְּחִינַת חָכְמָה בִּבְרִיאָה, וּמִמֵּילָא יֵשׁ לְחָכְמָה דִבְרִיאָה אֵיזֶה עֶרֶךְ לְחָכְמָה דַאֲצִילוּת, וּכְמוֹ כֵן יֵשׁ לְחָכְמָה דַעֲשִׂיָּה גַם כֵּן אֵיזֶה עֶרֶךְ מִשּׁוּם דְּהַכֹּל הוּא בְּחִינַת הִשְׁתַּלְשְׁלוּת עִלָּה וְעָלוּל.\n<b>וּכְמוֹ</b> שֶׁהוּא בְּחָכְמָה דַעֲשִׂיָּה לְגַבֵּי חָכְמָה עִילָּאָה דַאֲצִילוּת, כְּמוֹ כֵן הוּא בִּבְחִינַת חֶסֶד דַּעֲשִׂיָּה שֶׁהוּא בִּבְחִינַת הִשְׁתַּלְשְׁלוּת מִבְּחִינַת חֶסֶד עֶלְיוֹן דַּאֲצִילוּת, וְאִם כֵּן כֵּיוָן שֶׁבְּחִינַת חֶסֶד דַּעֲשִׂיָּה מוּשְׁרָשׁ מַמָּשׁ בְּחֶסֶד דַּאֲצִילוּת כְּמוֹ עַל דֶּרֶךְ מָשָׁל – לְהַבְדִּיל אֶלֶף הַבְדָּלוֹת – מְתִיקוּת הַתַּפּוּחַ שֶׁמּוּשְׁרָשׁ בְּהַמַּזָּל הָרוּחָנִי, וּבְשֹׁרֶשׁ שָׁרְשָׁן הַחֶסֶד הָרוּחָנִי, וַהֲרֵי מֵחֶסֶד דַּעֲשִׂיָּה נִמְשָׁכִים וְנִשְׁפָּעִים עִנְיְנֵי עוֹלָם הַזֶּה מַמָּשׁ וְחַיּוּת כָּל עוֹלָם הַזֶּה הַגַּשְׁמִיִים אִם כֵּן גַּם בְּחֶסֶד עֶלְיוֹן דַּאֲצִילוּת הַנִּקְצָב לְכָל אָדָם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שַׁפִּיר מוּשְׁרָשִׁים מַמָּשׁ כָּל הַהַשְׁפָּעוֹת גַּשְׁמִים הַנִּמְשָׁכִים מֵחֶסֶד דַּעֲשִׂיָּה, דְּמֵאַחַר דְּחֶסֶד דַּעֲשִׂיָּה מוּשְׁרָשׁ בְּחֶסֶד דַּאֲצִילוּת אִם כֵּן הֲרֵי גַּם כָּל הַדְּבָרִים הַנִּמְשָׁכִים מִבְּחִינַת חֶסֶד דַּעֲשִׂיָּה מוּשְׁרָשִׁים גַּם כֵּן בִּבְחִינַת חֶסֶד דַּאֲצִילוּת, וְהַיְינוּ דִּבְחִינַת חֶסֶד דַּאֲצִילוּת כְּבָר כּוֹלֶלֶת בְּעַצְמָהּ כָּל שָׁרְשֵׁי הַדְּבָרִים הַנִּמְשָׁכִים מִבְּחִינַת חֶסֶד דַּעֲשִׂיָּה.\n<b>וְזֶהוּ</b> עִנְיָן מַה שֶּׁאָדָם נִידּוֹן עַל כָּל הַדְּבָרִים וְהַמְּאוֹרָעוֹת שֶׁל כָּל הַשָּׁנָה בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, לְפִי שֶׁבְּחִינַת הַחֶסֶד שֶׁנִּקְצָב לוֹ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁנִּמְשָׁךְ לִבְחִינַת מַלְכוּת דַּאֲצִילוּת הֲרֵי הוּא כּוֹלֵל כָּל הַדְּבָרִים שֶׁיִּסְתַּעֲפוּ מִמֶּנּוּ.\nקִיצּוּר.\nאֲצִילוּת אֵין עֲרוֹךְ אֶל הָעַצְמוּת דְּאֵין שָׁם עִנְיַן הַסְּפִירוֹת כְּמוֹ בַּאֲצִילוּת וְהִתְהַוּוּת הָעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת הוּא עַל יְדֵי הַצִּמְצוּם וְסִילּוּק, וְהִתְהַוּוּת הָעֶשֶׂר סְפִירוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה מֵאֲצִילוּת הוּא עַל יְדֵי הַפַּרְסָא, וּבְחֶסֶד דַּעֲשִׂיָּה יֶשְׁנָם הַמְּקוֹרִים דְּעִנְיָנִים גַּשְׁמִים אִם כֵּן יֵשׁ לָהֶם יַחַס לְחֶסֶד וְחָכְמָה דַאֲצִילוּת."],[4401900082,"<h2>מַאֲמָר כב.</h2>\nוְהִנֵּה עִם הֱיוֹת דְּדַעַת רַבָּנָן שֶׁמְּזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִין לוֹ מֵרֹאשׁ הַשָּׁנָה, וְנִתְבָּאֵר לְעֵיל שֶׁכָּל צָרְכֵי הָאָדָם וּבְנֵי בֵיתוֹ בְּבָנֵי חַיֵּי וּמְזוֹנֵי הֵם בִּכְלַל הַמְּזוֹנוֹת בְּכָל זֶה גַּם לְדַעַת רַבָּנָן הִנֵּה יֵשׁ דִּין בְּכָל יוֹם, וְלָכֵן אָנוּ מִתְפַּלְלִים וּמְבַקְשִׁים בְּכָל יוֹם רְפָאֵנוּ וּבָרֵךְ עָלֵינוּ, וַהֲגַם דְּבִגְמָרָא (שָׁם) אָמְרוּ כְּמַאן מְצַלִּינָן הַאִידְנָא אַקְּצִירֵי וּמְרִיעֵי כְּמַאן כְּרַבִּי יוֹסֵי, מִכָּל מָקוֹם הֲלֹא גַּם לְרַבָּנָן מִי לָא מְצַלִּינָן וּבָרֵךְ עָלֵינוּ כְּמוֹ שֶׁכָּתוּב בְּתוֹסָפוֹת שָׁם,\nוְהָעִנְיָן הוּא דַּהֲגַם שֶׁהַחֶסֶד נִקְצַב בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים מִכָּל מָקוֹם הוּא עֲדַיִין בִּבְחִינַת מַלְכוּת דַּאֲצִילוּת כְּמוֹ שֶׁהִיא בַּאֲצִילוּת, דְּמַלְכוּת דַּאֲצִילוּת כְּמוֹ שֶׁהִיא בַּאֲצִילוּת הֲרֵי הִיא מוּפְלָא בְּעֶרֶךְ מִבְּרִיאָה-יְצִירָה-עֲשִׂיָּה, וּבְחִינַת רַגְלֶיהָ יוֹרְדוֹת מָוֶת דְּמַלְכוּת דַּאֲצִילוּת הַיּוֹרֶדֶת לִבְרִיאָה-יְצִירָה-עֲשִׂיָּה כְּמוֹ שֶׁכָּתוּב (מִשְׁלֵי לא. טו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ דְּקָאֵי עַל בְּחִינַת חִיצוֹנִיּוּת הַמַּלְכוּת דַּאֲצִילוּת הַיּוֹרֶדֶת לְהַחֲיוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה, הִנֵּה בְּרִיאָה-יְצִירָה-עֲשִׂיָּה לְגַבֵּי אֲצִילוּת נִקְרֵאת מָוֶת דִּכְתִיב (דְּבָרִים ל. טו) רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטּוֹב וְאֶת הַמָּוֶת וְאֶת הָרָע, דְּחַיִּים וָטוֹב מָוֶת וָרָע הֵם תּוֹאֲרֵי הָרוּחָנִי וְהַגַּשְׁמִי. דְּהָרוּחָנִי הוּא חַיִּים וָטוֹב וְהַגַּשְׁמִי הוּא מָוֶת וָרָע. וְזֶהוּ רַגְלֶיהָ יוֹרְדוֹת מָוֶת דִּבְרִיאָה לְגַבֵּי אֲצִילוּת אֵינָהּ בְּעֶרֶךְ כְּלָל,\nלָכֵן הִנֵּה הֲגַם שֶׁהַחֶסֶד בְּבָנֵי חַיֵּי וּמְזוֹנֵי כְּבָר הוּקְצַב בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים אֲבָל הוּא עֲדַיִין בְּמַלְכוּת דַּאֲצִילוּת, וְלִהְיוֹתוֹ עֲדַיִין בְּמַלְכוּת דַּאֲצִילוּת הִנֵּה כְּדֵי שֶׁיּוּמְשַׁךְ לְמַטָּה הוּא עַל יְדֵי הִשְׁתַּלְשְׁלוּת וְהִתְלַבְּשׁוּת בִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה דְּבַר יוֹם בְּיוֹמוֹ, וְיֵשׁ עַל זֶה דִּין וְעִיּוּן אִם רָאוּי וּכְדַאי הָאָדָם שֶׁיּוּמְשַׁךְ וְיִתְלַבֵּשׁ הַחֶסֶד בַּעֲשִׂיָּה בְּגַשְׁמִיּוּת לְטוֹב לוֹ, שֶׁיּוֹסִיף בְּלִימּוּד הַתּוֹרָה בִּמְנוּחָה וּבְקִיּוּם הַמִּצְוֹת בְּהִידּוּר וּכְמוֹ שֶׁכָּתוּב זֶה אֵלִי וְאַנְוֵהוּ וְאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שַׁבָּת קלג. ב) הִתְנָאֶה לְפָנָיו בְּמִצְוֹת וְכֵן בְּמַעֲשֵׂה הַצְּדָקָה בְּיָד רְחָבָה, אוֹ חַס וְשָׁלוֹם שֶׁהַהַשְׁפָּעָה בְּגַשְׁמִיּוּת תִּהְיֶה לְרָעָתוֹ וּכְמוֹ שֶׁכָּתוּב וּמְשַׁלֵּם לְשֹׂנְאוֹ לְהַאֲבִידוֹ מִשָּׂכָר הָרוּחָנִי בָּעוֹלָם הַבָּא, וּכְמוֹ שֶׁהוּא בְּכַמָּה פּוֹשְׁעֵי יִשְׂרָאֵל רַחֲמָנָא לִצְּלָן אֲשֶׁר הַגְּמוּל בְּעַד הַטּוֹב שֶׁעוֹשִׂים מְשַׁלְּמִים לָהֶם בְּטוּב עוֹלָם זֶה שֶׁמַּצְלִיחִים בְּבָנֵי חַיֵּי וּמְזוֹנֵי, וְהוּא מַה שֶּׁדֶּרֶךְ רְשָׁעִים צָלֵחָה אֲבָל הוּא רַק בָּעוֹלָם הַזֶּה וְנֶעֱנָשִׁים בְּעוֹנָשִׁים מָרִים וְקָשִׁים לָעוֹלָם הַבָּא,\nוְלִפְעָמִים הִנֵּה הַפְּסַק דִּין אֲשֶׁר הַטּוֹב שֶׁנִּקְצַב לוֹ יִשָּׁאֵר לְמַעְלָה בָּעוֹלָמוֹת הָרוּחָנִים וִיקַבְּלֶנּוּ לָעוֹלָם הַבָּא,\n(וַהֲגַם דְּלִכְאוֹרָה מֵאַחַר שֶׁהַחֶסֶד הַנִּקְצָב לוֹ כְּבָר כּוֹלֵל בְּחִינַת חֶסֶד דַּעֲשִׂיָּה וְהַהַשְׁפָּעוֹת שֶׁמִּזֶּה, וְאִם כֵּן לִכְאוֹרָה בְּהֶכְרַח שֶׁיּוּמְשַׁךְ בַּעֲשִׂיָּה דַוְקָא אִם כֵּן אֵיךְ הוּא נִשְׁאָר לְמַעְלָה בְּרוּחָנִיּוּת, אַךְ זֶה יוּבַן מִמַּה שֶׁיִּתְבָּאֵר לְקַמָּן בְּפֶרֶק ב' – דִּבְכָל זֶה הִנֵּה רַבָּנָן וְרַבִּי יוֹסֵי כֻּלָּם מַסְכִּימִים)\nוְרַק הַנַּפְקָא מִינָּהּ בֵּין רַבָּנָן לְרַבִּי יוֹסֵי הוּא, דִּלְרַבָּנָן כְּבָר נֶאֱמַר וְנִגְזַר בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים מַה יּוּמְשַׁךְ מֵהַחֶסֶד, וַאֲשֶׁר לְפִי זֶה הַדִּין שֶׁאַחַר כַּךְ בְּכָל יוֹם שֶׁהוּא אִם יְקוּיַּים כְּפִי שֶׁנֶּאֱמַר וְנִגְזַר מִכְּבָר אֵינוֹ תְּחִלַּת דִּין, וְהוּא עַל דֶּרֶךְ שֶׁמְּבוֹאָר בִּגְמָרָא (שָׁם) דִּלְרַבִּי יוֹסֵי דְּאָמַר אָדָם נִידּוֹן בְּכָל יוֹם הָא דִכְתִיב (אִיּוֹב ז. יח) לִרְגָעִים תִּבְחָנֶנּוּ, דְּמַשְׁמָע כָּל שָׁעָה הוּא עִיּוּנֵי בְּעָלְמָא וְאֵינוֹ דִּין מַמָּשׁ, כַּךְ לְרַבָּנָן דְּאָמְרִי אָדָם נִגְמַר גְּזַר דִּינוֹ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים הָא דִכְתִיב (מְלָכִים-א ח. נט) לַעֲשׂוֹת מִשְׁפַּט כו' דְּבַר יוֹם בְּיוֹמוֹ הוּא גַם כֵּן עִיּוּן, אֶלָּא שֶׁאֵינוֹ עִיּוּנֵי בְּעָלְמָא אֶלָּא נִקְרָא פְּקִידָה שֶׁהוּא יוֹתֵר מֵעִיּוּן וְהוּא מַה שֶּׁכָּתוּב (אִיּוֹב ז. יח) וַתִּפְקְדֶנּוּ לִבְקָרִים כו', וְלָכֵן צְרִיכִים לְהִתְפַּלֵּל וּלְבַקֵּשׁ בְּכָל יוֹם גַּם לְרַבָּנָן.\n<b>וְרַבִּי</b> יוֹסֵי סֹבֵר שֶׁבְּכָל יוֹם הוּא דִין גָּמוּר, דְּרַבִּי יוֹסֵי מְפָרֵשׁ פְּקִידָה הַנֶּאֱמַר בַּפָּסוּק וַתִּפְקְדֶנּוּ לִבְקָרִים שֶׁהוּא מִשְׁפָּט גָּמוּר, וְרַבָּנָן מְפָרְשִׁים מִשְׁפָּט הַנֶּאֱמַר בַּפָּסוּק לַעֲשׂוֹת מִשְׁפַּט כו' שֶׁהוּא עִנְיַן פְּקִידָה, וְלִשְׁנֵיהֶם שְׁנֵי הַכְּתוּבִים הָאֵלּוּ מְבָאֲרִים זֶה אֶת זֶה מִשּׁוּם דִּשְׁנֵיהֶם נֶאֶמְרוּ עַל הַדִּין שֶׁבְּכָל יוֹם,\nמַה שֶּׁאֵין כֵּן מַה שֶּׁנֶּאֱמַר (תְּהִלִּים פא. ה) כִּי חֹק לְיִשְׂרָאֵל הוּא מִשְׁפָּט לֵאלֹקֵי יַעֲקֹב קָאֵי עַל הַדִּין דְּרֹאשׁ הַשָּׁנָה, וְהַטַּעַם הוּא לְפִי שֶׁבְּהַחֶסֶד דַּאֲצִילוּת אֵין בּוֹ שׁוּם תּוֹאַר עֲדַיִין מֵחֶסֶד דַּעֲשִׂיָּה וּמֵהַהַשְׁפָּעוֹת הַנִּמְשָׁכוֹת לְמַטָּה לָכֵן בִּכְדֵי שֶׁיִּצְטַיֵּיר בְּהַחֶסֶד צִיּוּר הַשְׁפָּעוֹת דַּעֲשִׂיָּה שֶׁזֶּה בּוֹ הִתְחַדְּשׁוּת, יֵשׁ עַל זֶה דִּין גָּמוּר אִם יִצְטַיֵּיר וּבְאֵיזֶה אוֹפֶן יִצְטַיֵּיר אוֹ שֶׁיִּשָּׁאֵר רַק בָּעוֹלָם הָעֶלְיוֹן בְּרוּחָנִיּוּת וִיקַבֵּל אוֹתוֹ לָעוֹלָם הַבָּא.\nקִיצּוּר.\nהַחֶסֶד שֶׁנִּקְצָב לְאָדָם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים הוּא בְּמַלְכוּת דַּאֲצִילוּת, מַלְכוּת דַּאֲצִילוּת מוּפְלָא בְּעֶרֶךְ מִבְּרִיאָה-יְצִירָה-עֲשִׂיָּה, חַיִּים וָטוֹב מָוֶת וָרָע, וְלָכֵן יֵשׁ דִּין בְּכָל יוֹם אִם רָאוּי הָאָדָם לְמַה שֶּׁנִּקְצַב לוֹ, וְהַדִּין לְדַעַת רַבָּנָן וְרַבִּי יוֹסֵי הוּא עִיּוּן וְרַק שֶׁרַבִּי יוֹסֵי סוֹבֵר דְּעִיּוּן זֶה הוּא דִין גָּמוּר."],[4401900083,"וְהִנֵּה כָּל זֶה הוּא לְפִי הַשִּׁיטָה שֶׁבְּהַחֶסֶד דַּאֲצִילוּת אֵין עֲדַיִין שׁוּם תּוֹאַר מֵחֶסֶד דַּעֲשִׂיָּה בִּכְלָל, וּמִכָּל שֶׁכֵּן מֵהַהַשְׁפָּעוֹת הַגַּשְׁמִיּוֹת הַנִּמְשָׁכוֹת לְמַטָּה, דְּהִנֵּה גַּם בַּעֲשִׂיָּה הָרוּחָנִית אֵינוֹ נוֹפֵל בּוֹ עִנְיַן הַהַגְשָׁמָה וּמִכָּל שֶׁכֵּן בָּעוֹלָמוֹת יְצִירָה וּבְרִיאָה וּבִפְרָט בְּעוֹלָם הָאֲצִילוּת, אֲשֶׁר מַלְכוּת דַּאֲצִילוּת כְּמוֹ שֶׁהִיא בַּאֲצִילוּת הִיא מִסְּפִירוֹת הָעַצְמִיּוֹת דַּאֲצִילוּת דְּאֵין סוֹף לְהִתְפַּשְּׁטוּתָן הִנֵּה גַּם הַחֶסֶד דַּעֲשִׂיָּה הַכָּלוּל בְּחֶסֶד דַּאֲצִילוּת אֵין בּוֹ שׁוּם צִיּוּר עֲדַיִין, וּבִכְדֵי שֶׁיִּהְיֶה אֵיזֶה צִיּוּר הִנֵּה עַל זֶה הוּא הַדִּין וּמִשְׁפָּט,\nאָמְנָם לְפִי הַשִּׁיטָה דְּשָׁרְשֵׁי הַחֶסֶד דַּעֲשִׂיָּה הַכָּלוּל בְּמַלְכוּת דַּאֲצִילוּת הִנֵּה בְּחֶסֶד זֶה כְּבָר יֵשׁ בּוֹ הִצְטַיְּירוּת הַהַשְׁפָּעוֹת—שֶׁנִּמְשְׁכוּ וְנִתְהַוּוּ מִשָּׁרְשֵׁי הַחֶסֶד דַּעֲשִׂיָּה הַכָּלוּל בְּמַלְכוּת דַּאֲצִילוּת—אִם כֵּן הֲרֵי הַמְשָׁכָתָם בְּעוֹלָם הָעֲשִׂיָּה הָרוּחָנִית וְצִיּוּרָם אֵינוֹ הִתְחַדְּשׁוּת, וְלָמָּה יִהְיֶה עַל זֶה דִּין גָּמוּר מֵאַחַר שֶׁכְּבָר נִמְשַׁךְ וְנֶחְתַּם בְּהַדִּין דְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים.\n<b>אַךְ</b> הָעִנְיָן הוּא דְּהִנֵּה כָּל נִבְרָא וְנִבְרָא הֲרֵי הוּא כָּלוּל מִגּוּף וְנֶפֶשׁ, דְּהַגּוּף הוּא גַשְׁמִי וְהַנֶּפֶשׁ רוּחָנִי וְהֵם מְחוּלָּקִים בְּעִנְיַן וְאוֹפֶן הִתְהַוּוּתָם, דְּהִתְהַוּוּת הַנֶּפֶשׁ הִיא בָאָה בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת וּכְמוֹ נַפְשׁוֹת הַבְּהֵמוֹת שֶׁלְּמַטָּה בָּאוֹת בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת מִבְּחִינַת פְּנֵי שׁוֹר שֶׁבְּמֶרְכָּבָה וְנַפְשׁוֹת הַחַיּוֹת מִפְּנֵי אַרְיֵה וְנַפְשׁוֹת הָעוֹפוֹת מִפְּנֵי נֶשֶׁר וְנֶפֶשׁ הָאָדָם מִפְּנֵי אָדָם שֶׁבְּמֶרְכָּבָה,\nוְיָדוּעַ דְּהַד' חַיּוֹת יֵשׁ בְּכָל עוֹלָם וְעוֹלָם וּבָא בִּבְחִינַת הִשְׁתַּלְשְׁלוּת מִמַּדְרֵיגָה לְמַדְרֵיגָה דְּהַיְינוּ מֵרוּחָנִיּוּת לְרוּחָנִיּוּת דְּגַם הַנְּפָשׁוֹת שֶׁלְּמַטָּה הֵן רוּחָנִיּוֹת, אֲבָל לִהְיוֹת הִתְהַוּוּת מְצִיאוּת הַגַּשְׁמִי כְּמוֹ גּוּף הַבַּעֲלֵי חַיִּים וְכַדּוֹמֶה בְּכָל הַדּוֹמֵם-צוֹמֵחַ-חַי-מְדַבֵּר, זֶה אִי אֶפְשָׁר לִהְיוֹת בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת עִלָּה וְעָלוּל, שֶׁאֲפִילוּ יִהְיֶה רִיבּוּי רְבָבוֹת מַדְרֵיגוֹת הִשְׁתַּלְשְׁלוּת לֹא יִתְהַוֶּוה מֵהָרוּחָנִי מְצִיאוּת גַּשְׁמִי כִּי אִם יִהְיֶה הַכֹּל בִּבְחִינַת רוּחָנִי, וְהִתְהַוּוּת הַגַּשְׁמִי מֵהָרוּחָנִי הוּא בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן דַּוְקָא.\n<b>וּכְשֵׁם</b> שֶׁלְּמַטָּה יֵשׁ גּוּף וְנֶפֶשׁ וְהַנֶּפֶשׁ הוּא בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת וְהַגּוּף הוּא בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן, כְּמוֹ כֵן הוּא בְּדוּגְמָא כָזֹאת לְמַעְלָה גַם כֵּן, וּכְמוֹ מַלְאָכִים הֲרֵי יָדוּעַ שֶׁכְּלוּלִים גַּם כֵּן מִגּוּף וְנֶפֶשׁ וּכְמוֹ שֶׁכָּתַב הָרַמְבַּ''ן דְּמַה שֶּׁכָּתוּב (תְּהִלִּים קד. ד) עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט, הַיְינוּ גּוּפוֹת הַמַּלְאָכִים שֶׁהֵן מִיסוֹד הָאֵשׁ וְהָרוּחַ, נִמְצָא יֵשׁ בָּהֶן גּוּף וְנֶפֶשׁ,\nוְכֵן בְּהָעֶשֶׂר סְפִירוֹת שֶׁבָּעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה שֶׁכְּלוּלוֹת מֵאוֹרוֹת וְכֵלִים מְבוֹאָר בְּאִגֶּרֶת הַקֹּדֶשׁ (סִימָּן כ' דְּרוּשׁ הַמַּתְחִיל אִיהוּ וְחַיּוֹהִי חַד) שֶׁהַכֵּלִים דְּעֶשֶׂר סְפִירוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הֵם בְּחִינַת נִבְרָא וְנִבְרְאוּ בְּדֶרֶךְ יֵשׁ מֵאַיִן מִבְּחִינַת אוֹר הַנְּשָׁמָה שֶׁלָּהֶם, וְאִם כֵּן גַּם שָׁם בְּחִינַת הַנֶּפֶשׁ שֶׁהִיא הַנְּשָׁמָה הוּא בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת עִלָּה וְעָלוּל וּבְחִינַת הַכֵּלִים וְכָל שֶׁכֵּן הַלְּבוּשִׁים וְהַהֵיכָלוֹת וְהַמַּלְאָכִים שֶׁבְּכָל עוֹלָם הִתְהַוּוּתָם בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן,\nוּלְפִי זֶה מַה שֶּׁנִּתְבָּאֵר לְעֵיל דְּהַחֶסֶד דַּאֲצִילוּת כּוֹלֵל שָׁרְשֵׁי בְּחִינַת חֶסֶד דַּעֲשִׂיָּה וְהַהַשְׁפָּעוֹת הַבָּאוֹת מִזֶּה, וְהַהַמְשָׁכָה הִיא בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת לְבָד, זֶהוּ בִּבְחִינַת הָאוֹר וְהַחַיּוּת הַיְינוּ בִּבְחִינַת הַנְּשָׁמָה שֶׁבְּכָל הָעוֹלָמוֹת, אֲבָל בְּחִינַת הַכֵּלִים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וְכָל שֶׁכֵּן הַלְּבוּשִׁים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה הֵם בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן.\nקִיצּוּר.\nהַחֶסֶד שֶׁנִּקְצָב בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים הוּא שָׁרְשֵׁי הַחֶסֶד דַּעֲשִׂיָּה שֶׁכָּלוּל בְּמַלְכוּת דַּאֲצִילוּת הֲרֵי כְּבָר יֵשׁ בּוֹ צִיּוּר מִשָּׁרְשֵׁי הַשְׁפָּעוֹת גַּשְׁמִיּוֹת אִם כֵּן מַהוּ עִנְיַן הַדִּין בְּכָל יוֹם, בְּכָל נִבְרָא יֵשׁ גּוּף וְנֶפֶשׁ, הַנֶּפֶשׁ הִתְהַוּוּתוֹ בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת וְהַגּוּף הִתְהַוּוּתוֹ בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן, כֵּן הוּא בְּהָעֶשֶׂר סְפִירוֹת בְּאוֹרוֹת וְכֵלִים."],[4401900084,"וְהִנֵּה עַל פִּי זֶה יוּבַן דַּעַת רַבִּי יוֹסֵי דְּסוֹבֵר שֶׁבְּכָל יוֹם יֵשׁ דִּין גָּמוּר, דְּהִנֵּה זֶה שֶׁיּוּמְשַׁךְ הַשְׁפָּעוֹת חֶסֶד גַּשְׁמִי מַמָּשׁ בְּבָנֵי חַיֵּי וּמְזוֹנֵי צָרִיךְ לִהְיוֹת עַל יְדֵי הַכֵּלִים וְעַל יְדֵי הַלְּבוּשִׁים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה דַּוְקָא, שֶׁעַל יְדֵי זֶה נִצְטַיֵּיר הַדָּבָר בִּבְחִינַת יֵשׁ עַד שֶׁבָּא בִּבְחִינַת צִיּוּר גַּשְׁמִי, וְהַצִּיּוּר הַזֶּה הֲרֵי הוּא הִתְחַדְּשׁוּת שֶׁהֲרֵי הוּא בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן, דְּמַה שֶּׁהַחֶסֶד דַּאֲצִילוּת כּוֹלֵל שָׁרְשֵׁי הַחֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וְנִמְשָׁךְ בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת הוּא בְּחִינַת הַחַיּוּת הָרוּחָנִי וּבְחִינַת הַנְּשָׁמָה שֶׁהוּא הָאוֹר דְּחֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, אֲבָל צִיּוּר הַיֵּשׁ דְּכֵלִים וּלְבוּשִׁים דְּחֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה זֶה אֵינוֹ כָלוּל בְּחֶסֶד דַּאֲצִילוּת וְנִתְחַדֵּשׁ מַמָּשׁ בְּדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן וְלָכֵן עַל זֶה שַׁיָּיךְ דִּין גָּמוּר.\n<b>וּלְפִי</b> זֶה יוּבַן גַּם כֵּן מַה שֶּׁנִּתְבָּאֵר לְעֵיל דְּגַם לְרַבָּנָן אֶפְשָׁר לִהְיוֹת שֶׁלֹּא יוּמְשַׁךְ וְיִתְלַבֵּשׁ בְּחֶסֶד דַּעֲשִׂיָּה, וְלִכְאוֹרָה מֵאַחַר שֶׁכְּבָר כָּלוּל הוּא בְּחֶסֶד דַּאֲצִילוּת הֲרֵי בְּהֶכְרַח שֶׁיּוּמְשַׁךְ, וּלְפִי הַנַ\"ל מוּבָן דְּזֶה שֶׁיִּצְטַיֵּיר בְּצִיּוּר גַּשְׁמִי אֵינוֹ בְּהֶכְרַח כִּי זֶה אֵינוֹ כָלוּל בְּהַחֶסֶד דַּאֲצִילוּת, וְלָכֵן יָכוֹל לִהְיוֹת שֶׁיּוּמְשַׁךְ רַק בִּבְחִינַת הָרוּחָנִיּוּת כְּמוֹ בְּהַגִּילּוּיִם דְּגַן עֵדֶן הַתַּחְתּוֹן וְגַן עֵדֶן הָעֶלְיוֹן (שֶׁזֶּה נִמְשָׁךְ מִבְּחִינַת הַנְּשָׁמָה) וְלֹא יוּמְשַׁךְ בְּגַשְׁמִיּוּת מַמָּשׁ.\n<b>וּלְפִי</b> זֶה יוּבַן דְּרַבָּנָן וְרַבִּי יוֹסֵי מַר אָמַר חֲדָא וּמַר אָמַר חֲדָא וְלֹא פְלִיגִי כְּלָל (וְכֵן כָּתַב בַּעֲשָׂרָה מַאֲמָרוֹת דְּלֹא פְלִיגִי, אֶלָּא שֶׁכַּאן מְבוֹאָר בְּאוֹפֶן אַחֵר) דְּרַבָּנָן מְדַבְּרִים מִבְּחִינַת הַמְשָׁכַת הָאוֹר וְהַחַיּוּת הָרוּחָנִי שֶׁזֶּה נִכְלָל בְּהַדִּין וּמִשְׁפָּט דְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, לְפִי שֶׁהַחֶסֶד שֶׁנִּמְשָׁךְ בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים כּוֹלֵל זֶה וְנִמְשָׁךְ בְּכָל יוֹם בְּדֶרֶךְ הִשְׁתַּלְשְׁלוּת וְאֵינוֹ הִתְחַדְּשׁוּת, וְלָכֵן אֵין עַל זֶה דִּין וּמִשְׁפָּט כִּי אִם פְּקִידָה וְעִיּוּן לְבָד וּבָזֶה גַּם רַבִּי יוֹסֵי מוֹדֶה, אַךְ רַבִּי יוֹסֵי מְדַבֵּר בְּהַמְשָׁכַת בְּחִינַת הַצִּיּוּר הַגַּשְׁמִי מַמָּשׁ שֶׁזֶּהוּ עִיקַּר הַהַמְשָׁכָה דְּבַר יוֹם בְּיוֹמוֹ לִהְיוֹת הַשְׁפָּעוֹת גַּשְׁמִיּוֹת מַמָּשׁ, וְהַמְשָׁכָה זוֹ בְּדֶרֶךְ הִתְחַדְּשׁוּת לָכֵן אוֹמֵר שֶׁיֵּשׁ דִּין גָּמוּר בְּכָל יוֹם עַל הַהַשְׁפָּעָה וְגַם רַבָּנָן מוֹדִים בָּזֶה.\n<b>הַיּוֹצֵא</b> מִכָּל הַנַ\"ל הוּא דְּעִיקַּר הַדִּין וּמִשְׁפָּט הוּא בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וּבָזֶה תָּלוּי כְּלָלוּת הַהַשְׁפָּעָה דְכָל הַשָּׁנָה כְּמָה שֶׁנִּקְצָב וְנִמְשָׁךְ הַחֶסֶד בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים לְכָל הָעוֹלָם בִּכְלָל וּלְכָל בְּרִיָּה בִּפְרָט אִם בְּרִיבּוּי אוֹ כו', אָמְנָם בִּכְדֵי שֶׁיּוּמְשַׁךְ בְּחִינַת הַשְׁפָּעוֹת גַּשְׁמִיּוֹת צָרִיךְ לִהְיוֹת עַל יְדֵי הִתְלַבְּשׁוּת בְּחֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה דַּוְקָא, וּבָזֶה יֵשׁ שְׁנֵי דְבָרִים הַמְשָׁכַת הַחַיּוּת הָרוּחָנִי דְּחֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וּבְחִינַת הַלְּבוּשִׁים וְהַצִּיּוּר מַמָּשׁ דְּחֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה, וְעַל זֶה הוּא הָעִיּוּן וְהַמִּשְׁפָּט בְּכָל יוֹם בִּכְדֵי שֶׁיִּצְטַיֵּיר בִּבְחִינַת חֶסֶד דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה עַד שֶׁיּוּמְשַׁךְ בְּחִינַת הַשְׁפָּעַת חַיִּים וְחֶסֶד גַּשְׁמִי מַמָּשׁ לְמַטָּה.\nקִיצּוּר.\nגִּילּוּי הַחֶסֶד בְּבָנֵי חַיֵּי וּמְזוֹנֵי צָרִיךְ לִהְיוֹת עַל יְדֵי הַכֵּלִים דְּעֶשֶׂר סְפִירוֹת וּבְדֶרֶךְ בְּרִיאָה יֵשׁ מֵאַיִן, וְשַׁיָּיךְ בָּזֶה דִּין גָּמוּר בְּכָל יוֹם לְרַבִּי יוֹסֵי, וּלְרַבָּנָן יָכוֹל לִהְיוֹת שֶׁיִּשָּׁאֵר בְּרוּחָנִיּוּת, רַבָּנָן מְדַבְּרִים בְּעִנְיַן הַחַיּוּת הָרוּחָנִי וְרַבִּי יוֹסֵי מְדַבֵּר בְּעִנְיַן הַגַּשְׁמִי."],[4401900085,"<h2>מַאֲמָר כג.</h2>\nוְהִנֵּה לִהְיוֹת שֶׁהַחֶסֶד הַנִּמְשָׁךְ לְמַטָּה בָּעוֹלָם הַזֶּה צָרִיךְ לִהְיוֹת עַל יְדֵי עֶשֶׂר סְפִירוֹת דַּעֲשִׂיָּה וְדַוְקָא עַל יְדֵי הַכֵּלִים וְהַלְּבוּשִׁים כו', בִּכְדֵי שֶׁתִּצְטַיֵּיר הַהַשְׁפָּעָה בְּצִיּוּר גַּשְׁמִי, יוּבַן עִנְיַן וּבֵרַכְךָ ה' אֱלֹקֶיךָ בְּכֹל אֲשֶׁר תַּעֲשֶׂה (דְּבָרִים טו. יח)\nדְּהִנֵּה בִּפְרִי עֵץ חַיִּים שַׁעַר הַתְּפִלָּה בְּכַוָּונַת פַּרְשַׁת הַתָּמִיד עַל פָּסוּק צַו אֶת בְּנֵי יִשְׂרָאֵל בְּגִימַטְרִיָּא אֵל אד' וְהוּא בַּעֲשִׂיָּה וְלָכֵן אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אֵין צַו אֶלָּא עֲבוֹדָה זָרָה לְפִי שֶׁיּוֹנְקִים מִשֵּׁם אֵל אד', וְלִכְאוֹרָה לְפִי דְבָרָיו אֵינוֹ מוּבָן כְּלָל מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אֵין צַו אֶלָּא כו' מֵאַחַר דְּשֵׁמוֹת אֵל אד' הֵן בְּגִימַטְרִיָּא צַו וְהֵם שֵׁמוֹת עֶלְיוֹנִים, וְאַף שֶׁמֵּהֶם יוֹנְקִים הַקְּלִיפּוֹת דַּעֲשִׂיָּה מִכָּל מָקוֹם הֵם עַצְמָם הֵם שְׁמוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאִם כֵּן מַהוּ עִנְיַן אֵין צַו אֶלָּא כו'.\n<b>אַךְ</b> הָעִנְיָן הוּא דְּהִנֵּה עִנְיַן עֲבוֹדָה זָרָה הוּא שֶׁמִּשְׁתַּחֲוֶה לַשֶּׁמֶשׁ וְלַיָּרֵחַ, וְהַיְינוּ מִפְּנֵי שֶׁמֵּהֶם תֵּצֵא הַשְׁפָּעַת הַמָּזוֹן וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים לג. יד) וּמִמֶּגֶד תְּבוּאֹת שָׁמֶשׁ וּמִמֶּגֶד גֶּרֶשׁ יְרָחִים, וּמִפְּנֵי שֶׁמְּחַשֵּׁב אוֹתָם לִמְקוֹרֵי הַהַשְׁפָּעָה לָכֵן הֲרֵי הוּא מִשְׁתַּחֲוֶה וְעוֹבֵד לָהֶם, וּבֶאֱמֶת זוֹהִי טָעוּת גְּדוֹלָה, דְּעִם הֱיוֹת שֶׁנִּמְשָׁךְ הַהַשְׁפָּעָה עַל יָדָם הֲרֵי בֶּאֱמֶת אֵינָם אֶלָּא שְׁלוּחֵי הַשְׁפָּעָה לְבָד וְאֵין בְּיָדָם לְהָרַע אוֹ לְהֵטִיב מֵעַצְמָם, שֶׁהֵם רַק כַּגַּרְזֶן בְּיַד הַחוֹצֵב בּוֹ שֶׁהַגַּרְזֶן בְּעַצְמוֹ אֵין בִּיכָלְתּוֹ לַעֲשׂוֹת שׁוּם דָּבָר כִּי אִם הָאוּמָּן בּוֹנֶה עַל יְדֵי הַגַּרְזֶן, וּכְמוֹ כֵן כָּל הַכּוֹכָבִים וְהַמַּזָּלוֹת הֵם רַק כַּגַּרְזֶן שֶׁעַל יָדָם נִמְשֶׁכֶת הַהַשְׁפָּעָה, אָמְנָם הַשּׁוֹפֵעַ וְהַנּוֹתֵן אֶת הַהַשְׁפָּעָה הוּא הָאֱלֹקוּת אֶלָּא שֶׁמַּשְׁפִּיעַ עַל יְדֵי הַמַּזָּלוֹת, אֲבָל הֵם מֵעַצְמָם אֵין לָהֶם שׁוּם כֹּחַ לַעֲשׂוֹת דָּבָר כְּלָל, וּמִמֵּילָא אֵין לְחַשְּׁבָם כְּלָל וּכְלָל וּכְמוֹ שֶׁכָּתוּב (יְשַׁעְיָה י. טו) הֲיִתְפָּאֵר הַגַּרְזֶן עַל הַחוֹצֵב בּוֹ,\nוְעַל דֶּרֶךְ מָשָׁל אָדָם הָרוֹאֶה בִּנְיָן גָּדוֹל וּמְפוֹאָר הַאִם יַעֲלֶה עַל הַדַּעַת שֶׁיְּשַׁבַּח אֶת הַגַּרְזֶן שֶׁבָּנָה אֶת הַבִּנְיָן שֶׁיֹּאמַר כַּמָּה מְשׁוּבָּח הַגַּרְזֶן שֶׁבָּנָה בִּנְיָן גָּדוֹל וּמְפוֹאָר כָּזֶה אוֹ יֹאמַר כַּמָּה מְפוֹאָר הַבִּנְיָן שֶׁבָּנָה הַגַּרְזֶן, אֶלָּא יְשַׁבַּח וִיפָאֵר אֶת הָאוּמָּן שֶׁבָּנָה אֶת הַבִּנְיָן וְהַבִּנְיָן נִקְרָא עַל שֵׁם הָאוּמָּן, הֲגַם שֶׁהָאוּמָּן בָּנָה אוֹתוֹ עַל יְדֵי הַגַּרְזֶן מִכָּל מָקוֹם אֵין הַגַּרְזֶן נֶחְשָׁב לִמְאוּמָה אֶלָּא הָאוּמָּן שֶׁבּוֹנֶה עַל יְדֵי הַגַּרְזֶן, וּכְמוֹ כֵן הוּא בְּכָל הַשְׁפָּעוֹת שֶׁפַע חַיּוּת וּמָזוֹן בָּעוֹלָם הֲרֵי מִי הוּא הַשּׁוֹפֵעַ הוּא הָאֱלֹקוּת אֶלָּא שֶׁנִּמְשָׁךְ עַל יְדֵי הַמַּזָּלוֹת (מֵהַטַּעַם שֶׁיִּתְבָּאֵר לְקַמָּן), אֲבָל אֱלֹקוּת הוּא הַשּׁוֹפֵעַ עַל יָדָם וְהוּא הָעִיקָּרִי וְהַמַּזָּלוֹת אֵין נֶחְשָׁבִים לִכְלוּם אֲפִילוּ לֹא כִּטְפֵלִים גַּם כֵּן, וּכְמוֹ שֶׁהַגַּרְזֶן אֵינוֹ נֶחְשָׁב אֲפִילוּ כְּשׁוּתָּף טָפֵל אֶל הָאוּמָּן כְּמוֹ כֵן הַמַּזָּלוֹת אֵינָן אֲפִילוּ כִּטְפֵלִים גַּם כֵּן שֶׁאֵינָן נֶחְשָׁבִים לִמְאוּמָה מַמָּשׁ, מֵאַחַר שֶׁהֵן רַק כִּשְׁלוּחִים לְבָד וְאֵין בָּהֶם כֹּחַ מֵעַצְמָן כְּלָל וּכְלָל וְאֵין בָּהֶם שׁוּם מַמָּשׁ, וְלִפְעָמִים מַרְאִים זֶה לְמַעְלָה אֵיךְ שֶׁאֵין שׁוּם כֹּחַ בַּמַּזָּלוֹת לַעֲשׂוֹת דָּבָר מֵעַצְמָם, וּכְמוֹ בְּמִצְרַיִם שֶׁנִּדּוֹנוּ בְּהָעֶשֶׂר מַכּוֹת וְלֹא הוֹעִילָה לָהֶם יִרְאָתָם שֶׁעָבְדוּ לְמַזָּל טָלֶה לְהַצִּילָם וְאַדְרַבָּא וּבְכָל אֱלֹקֵי מִצְרַיִם אֶעֱשֶׂה שְׁפָטִים כְּתִיב (שְׁמוֹת יב. יב) וּבִזְמַן הַחוּרְבָּן הֶחֱלִיף הַמַּזָּלוֹת וְהַשָּׂרִים הָעֶלְיוֹנִים, וְהַיְינוּ לְפִי שֶׁהֵן רַק שְׁלוּחֵי הַשֶּׁפַע לְבָד וְהָאֱלֹקוּת הוּא הַשּׁוֹפֵעַ עַל יָדָם.\nקִיצּוּר.\nאֵל אד' בְּגִימַטְרִיָּא צַו שֵׁם דַּעֲשִׂיָּה, הַהִשְׁתַּחֲוָאָה לַשֶּׁמֶשׁ וְיָרֵחַ וְהַמַּזָּלוֹת שֶׁעַל יָדָם רַק בָּאָה הַשְׁפָּעָה גַשְׁמִית אֲבָל הַמַּזָּלוֹת עַצְמָם אֵינָם יְכוֹלִים לֹא לְהַשְׁפִּיעַ וְלֹא לִמְנוֹעַ הַהַשְׁפָּעָה, וְהֵם רַק כַּגַּרְזֶן בְּיַד הַחוֹצֵב בּוֹ וְהַשּׁוֹפֵעַ הוּא אֱלֹקוּת וּבִרְצוֹנוֹ מְשַׁדֵּד הַמַּעֲרָכוֹת שֶׁל הַמַּזָלוֹת."],[4401900086,"וְהִנֵּה טַעַם וְסִבַּת הַדָּבָר מַה שֶּׁהַהַשְׁפָּעָה הַגַּשְׁמִית בָּאָה דַוְקָא עַל יְדֵי הַמַּזָּלוֹת הוּא,\nדְּהִנֵּה לְפִי שְׁתֵּי הַשִּׁיטוֹת בְּמַהוּת הַחֶסֶד שֶׁנִּקְצָב לְהָאָדָם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים כְּמוֹ שֶׁהוּא בְּמַלְכוּת דַּאֲצִילוּת הִנֵּה לְפִי דֵיעָה הָא' הוּא חֶסֶד פָּשׁוּט עֲדַיִין וְאֵין בּוֹ עֲדַיִין צִיּוּר וְתוֹאַר הַשְׁפָּעוֹת הַגַּשְׁמִים, וְהַדֵּיעָה הַב' דְּהַחֶסֶד דַּאֲצִילוּת כּוֹלֵל בְּתוֹכוֹ גַּם בְּחִינַת חֶסֶד דַּעֲשִׂיָּה וְכֵן כָּל הַבְּחִינוֹת הַמִּסְתַּעֲפוֹת מִזֶּה זֶהוּ בְּחִינַת הָאוֹר וְהַחַיּוּת רוּחָנִי אֲבָל לֹא עֶצֶם הַדָּבָר הַגַּשְׁמִי,\nוּבִכְדֵי שֶׁיִּהְיֶה חֶסֶד גַּשְׁמִי בְּבָנֵי חַיֵּי וּמְזוֹנֵי הוּא עַל יְדֵי הַכֵּלִים וְהַלְּבוּשִׁים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה שֶׁעַל יְדֵי זֶה נִצְטַיֵּיר בָּהֶם צִיּוּר הַגֶּשֶׁם, וְהַיְינוּ עַל יְדֵי שֶׁמַּעְלִימִים וּמַסְתִּירִים עַל הָאוֹר עַל יְדֵי זֶה נַעֲשֶׂה בִּבְחִינַת מְצִיאוּת יֵשׁ וְגַשְׁמִי וּכְיָדוּעַ דְּכָל עִנְיַן הַמְּצִיאוּת נַעֲשֶׂה עַל יְדֵי הֶסְתֵּר, וּכְמוֹ שֶׁכָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹקִים דְּכָל עִנְיַן הַבְּרִיאָה בְּפוֹעַל הוּא עַל יְדֵי שֵׁם אֱלֹקִים שֶׁהוּא מִדַּת הַדִּין בְּצִמְצוּם הָאוֹר וְהֶעְלֵמוֹ,\nוּכְמוֹ שֶׁכָּתוּב (תְּהִלִּים פד. יב) כִּי שֶׁמֶשׁ וּמָגֵן ה' אֱלֹקִים כְּדוּגְמַת הַמָּגֵן שֶׁהוּא הַנַּרְתֵּק הַמְכַסֶּה עַל עֶצֶם הַשֶּׁמֶשׁ דְּלוּלֵא זֹאת אֵין בִּיכוֹלֶת הַנִּבְרָאִים לְקַבְּלוֹ, הִנֵּה כֵן בְּשֵׁם אֱלֹקִים הַמְכַסֶּה וּמַעְלִים עַל עֶצֶם הָאוֹר דְּשֵׁם הוי' הַמְהַוֶּה.\n<b>וְטַעַם</b> הַדָּבָר הוּא דְּכַאֲשֶׁר הָאוֹר מֵאִיר בְּגִילּוּי אָז אֵין שׁוּם מְצִיאוּת, אַדְרַבָּה גִּילּוּי הָאוֹר פּוֹעֵל בִּיטּוּל הַמְּצִיאוּת וְהֶעְדֵּרוֹ, וְעַל יְדֵי הֶעְלֵם וְהֶסְתֵּר הָאוֹר נַעֲשָׂה בְּחִינַת הַמְּצִיאוּת, וְכָל שֶׁהַהֶסְתֵּר יוֹתֵר נַעֲשָׂה יוֹתֵר בְּחִינַת מְצִיאוּת הַיֵּשׁוּת,\nוְזֶהוּ שֶׁהַחֶסֶד כְּמוֹ שֶׁנִּמְשָׁךְ בָּעוֹלָמוֹת בְּרִיאָה-יְצִירָה-עֲשִׂיָּה הִנֵּה בְּכָל עוֹלָם שֶׁלְּמַטָּה נַעֲשֶׂה בִּבְחִינַת מְצִיאוּת יוֹתֵר, דִּתְחִלָּה מִתְלַבֵּשׁ בִּלְבוּשִׁים דִּבְרִיאָה וְנַעֲשֶׂה בִּבְחִינַת מְצִיאוּת יֵשׁ לְגַבֵּי אֲצִילוּת, אֲבָל לְגַבֵּי לְמַטָּה הַיְינוּ בְּעוֹלָם הַיְצִירָה הוּא רוּחָנִי עֲדַיִין וְצָרִיךְ הָאוֹר לְהִתְעַלֵּם בְּעוֹלָם הַיְצִירָה.\n<b>וּבָזֶה</b> יוּבַן דִּיּוּק לְשׁוֹן רַבֵּינוּ נִשְׁמָתוֹ עֵדֶן בְּאִגֶּרֶת הַקֹּדֶשׁ דְּרוּשׁ הַמַּתְחִיל לְהָבִין מַה שֶּׁכָּתוּב בִּפְרִי עֵץ חַיִּים שֶׁהוּבָא לְעֵיל שֶׁצָּרִיךְ לִהְיוֹת עַל יְדֵי מַעֲבַר יְצִירָה וַעֲשִׂיָּה הַנִּקְרָא גַם כֵּן הִתְלַבְּשׁוּת דְּאִם לֹא כֵן לֹא הָיָה פוֹעֵל בָּעוֹלָם הַזֶּה הַגַּשְׁמִי, וְהַיְינוּ דְּבִכְדֵי שֶׁתִּהְיֶה פְּעוּלַּת הַגַּשְׁמִיּוּת מַמָּשׁ בָּעוֹלָם הַזֶּה אֵינוֹ מַסְפִּיק עֲדַיִין הַיֵּשׁ דְּעוֹלָם הַבְּרִיאָה שֶׁהוּא יֵשׁ לְגַבֵּי אֲצִילוּת, אֲבָל לְגַבֵּי יְצִירָה הוּא רוּחָנִי עֲדַיִין, וְגַם אִם אוֹר הַחֶסֶד שֶׁל הַמְּצִיאוּת דִּבְרִיאָה יַעֲבוֹר בְּדֶרֶךְ מַעֲבַר הָעֶשֶׂר סְפִירוֹת דִּיצִירָה וַעֲשִׂיָּה הִנֵּה עֲדַיִין לֹא תִהְיֶה הַשְׁפָּעָה גַשְׁמִית מַמָּשׁ,\nכִּי אִם צָרִיךְ לִהְיוֹת עַל יְדֵי הִתְלַבְּשׁוּת כֵּלִים וּלְבוּשִׁים דִּיצִירָה שֶׁמַּעְלִימִים וּמַסְתִּירִים יוֹתֵר עַל הָאוֹר הָאֱלֹקִי דִּבְחִינַת חֶסֶד הָעֶלְיוֹן וְנַעֲשֶׂה עַל יְדֵי זֶה בִּבְחִינַת מְצִיאוּת יוֹתֵר וּמִתְלַבֵּשׁ אַחַר כַּךְ בְּכֵלִים וּלְבוּשִׁים דַּעֲשִׂיָּה שֶׁמַּסְתִּירִים עוֹד יוֹתֵר מִלְּבוּשִׁים דִּיצִירָה וְנַעֲשֶׂה יוֹתֵר בִּבְחִינַת מְצִיאוּת יֵשׁ.\n<b>וְזֶהוּ</b> גַם כֵּן הַטַּעַם שֶׁצָּרִיךְ לִהְיוֹת הִתְלַבְּשׁוּת הַהַשְׁפָּעָה בְּהַמַּזָּלוֹת בִּכְדֵי שֶׁתִּתְגַּשֵּׁם הַהַשְׁפָּעָה יוֹתֵר, דְּבִכְדֵי שֶׁתִּהְיֶה הַהַשְׁפָּעָה גַשְׁמִית מַמָּשׁ זֶהוּ עַל יְדֵי הִתְלַבְּשׁוּת הַחֶסֶד בְּהַמַּזָּלוֹת גַּם כֵּן, דְּכָל לְבוּשׁ הוּא מַעְלִים וּמַסְתִּיר וְכָל שֶׁהַלְּבוּשׁ תַּחְתּוֹן יוֹתֵר הֲרֵי הוּא מַעְלִים וּמַסְתִּיר יוֹתֵר, וְלָכֵן עַל יְדֵי הַהִתְלַבְּשׁוּת בְּהַמַּזָּלוֹת בָּא הַחֶסֶד שֶׁלְּמַעְלָה בִּבְחִינַת הַשְׁפָּעָה גַשְׁמִית מַמָּשׁ,\nכִּי הַלְּבוּשִׁים הָעֶלְיוֹנִים גַּם דְּעוֹלָם הָעֲשִׂיָּה הָרוּחָנִית הֵם לְבוּשִׁים רוּחָנִים וּמִמֵּילָא אֵינָם מַעְלִימִים וּמַסְתִּירִים כָּל כַּךְ בְּאוֹפֶן שֶׁתִּתְגַּשֵּׁם עַל יָדָם הַהַשְׁפָּעָה לִהְיוֹת שֶׁפַע גַּשְׁמִיּוּת מַמָּשׁ, כִּי אִם עַל יְדֵי הִתְלַבְּשׁוּת הַמַּזָּלוֹת שֶׁהֵם לְבוּשִׁים הַמַּעְלִימִים וּמַסְתִּירִים לְגַמְרֵי עַל הָאוֹר עַד שֶׁיִּתְהַוֶּוה עַל יְדֵי זֶה הַשְׁפָּעָה גַשְׁמִית מַמָּשׁ וְכָל זֶה הוּא רַק בִּשְׁבִיל שֶׁתִּתְגַּשֵּׁם הַהַשְׁפָּעָה, אֲבָל הַהַשְׁפָּעָה עַצְמָהּ הִיא מִבְּחִינַת חֶסֶד עֶלְיוֹן כַּנַ\"ל וּכְמוֹ שֶׁאָנוּ אוֹמְרִים הַזָּן אֶת הָעוֹלָם כּוּלּוֹ בְּטוּבוֹ בְּחֵן בְּחֶסֶד כו' וְשָׁרְשׁוֹ הוּא מִבְּחִינַת ה' חֲסָדִים וְה' גְבוּרוֹת דְּעַתִּיק כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר יח פֶּרֶק ב), שֶׁמִּשָּׁם נִמְשָׁךְ וְנִתְחַלֵּק שֶׁפַע הַחֶסֶד לְכָל אֶחָד וְאֶחָד בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים לְפִי אוֹפֶן קַבָּלַת מַלְכוּתוֹ יִתְבָּרֵךְ עָלָיו בְּרֹאשׁ הַשָּׁנָה וּלְפִי אוֹפֶן הַתְּשׁוּבָה שֶׁלּוֹ בַּחֲרָטָה אֲמִיתִּית עַל הֶעָבָר וְקַבָּלָה אֲמִיתִּית עַל לְהַבָּא בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת בְּסוּר מֵרָע וַעֲשֵׂה טוֹב בְּפוֹעַל מַמָּשׁ,\nוְהַהַמְשָׁכָה בְּיוֹם הַכִּפּוּרִים הִיא בִּבְחִינַת מַלְכוּת דַּאֲצִילוּת וּבְכָל יוֹם נִמְשֶׁכֶת הַשְׁפָּעַת הַחֶסֶד מִבְּחִינַת מַלְכוּת דַּאֲצִילוּת וּמִתְלַבֵּשׁ בִּלְבוּשִׁים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה לְפִי אוֹפֶן עֲבוֹדָתוֹ וּתְפִלָּתוֹ בְּכָל יוֹם, וְיוֹרֵד הַחֶסֶד הָעֶלְיוֹן מִמַּדְרֵיגָה לְמַדְרֵיגָה לְהִתְלַבֵּשׁ בִּלְבוּשִׁים תַּחְתּוֹנִים יוֹתֵר שֶׁעַל יְדֵי זֶה מִתְגַּשֶּׁמֶת הַהַשְׁפָּעָה יוֹתֵר, עַד שֶׁמִּתְלַבֵּשׁ בִּלְבוּשֵׁי הַמַּזָּלוֹת שֶׁעַל יְדֵי זֶה נַעֲשֶׂה בִּבְחִינַת חֶסֶד גַּשְׁמִי מַמָּשׁ.\nקִיצּוּר.\nהַחֶסֶד הַנִּקְצָב לְאָדָם בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים כְּמוֹ שֶׁהוּא עֲדַיִין בְּמַלְכוּת דַּאֲצִילוּת לְדֵיעָה הָא' הוּא פָּשׁוּט עֲדַיִין וּלְדֵיעָה הַב' הוּא רוּחָנִי, וּבִכְדֵי שֶׁיִּהְיֶה גַּשְׁמִי אֵינוֹ מַסְפִּיק הַהִתְלַבְּשׁוּת בְּכֵלִים וּלְבוּשִׁים דִּיצִירָה וַעֲשִׂיָּה רַק הַהִתְלַבְּשׁוּת בְּהַמַּזָּלוֹת, וְעֶצֶם הַשֶּׁפַע דְּחֶסֶד עֶלְיוֹן הוּא מֵעַתִּיקָא קַדִּישָׁא."],[4401900087,"<h2>מַאֲמָר כד.</h2>\nוְהִנֵּה אוֹר הַחֶסֶד וְהַחַיּוּת בְּהַהַשְׁפָּעָה שֶׁנִּקְצְבָה לוֹ לְאָדָם בְּרֹאשׁ הַשָּׁנָה בְּכָל מִינֵי טוֹב בְּבָנֵי חַיֵּי וּמְזוֹנֵי הוּא מֵאִתּוֹ יִתְבָּרֵךְ, וְהַיְינוּ דְּגוּף וְעֶצֶם הַשֶּׁפַע הוּא מֵעַתִּיקָא קַדִּישָׁא שֶׁהוּא פְּנִימִיּוּת וְעַצְמִיּוּת אֵין סוֹף, וּבָא עַל יְדֵי הִתְעוֹרְרוּת הָעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת דִּלְשָׁם מַגַּעַת הָעֲבוֹדָה דְנִשְׁמוֹת יִשְׂרָאֵל בַּתּוֹרָה וּמִצְוֹת.\n<b>דְּהִנֵּה</b> הָאוֹר וְהַשֶּׁפַע שֶׁנִּקְצָב לוֹ לְהָאָדָם בְּרֹאשׁ הַשָּׁנָה וְנֶחְתָּם בְּיוֹם הַכִּפּוּרִים הוּא לְפִי עֲבוֹדָתוֹ בַּתּוֹרָה וּמִצְוֹת בְּשָׁנָה הֶעָבְרָה, וּכְמוֹ שֶׁכָּתוּב כִּי חֹק לְיִשְׂרָאֵל הוּא מִשְׁפָּט לֵאלֹקֵי יַעֲקֹב וּפֵירוּשׁוֹ כִּי הַחֹק הַנִּקְצָב לְיִשְׂרָאֵל בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים תָּלוּי בְּמִשְׁפָּט, וְהַמִּשְׁפָּט הוּא בָּזֶה כַּמָּה אוֹר וְגִילּוּי אֱלֹקוּת, שֶׁהוּא עִנְיַן אֱלֹקֵי יַעֲקֹב, הִמְשִׁיךְ בְּשָׁנָה הֶעָבְרָה,\nוְכֵן תָּלוּי בְּאוֹפֶן הַתְּשׁוּבָה בַּעֲבוֹדָה דְחֹדֶשׁ אֱלוּל שֶׁהוּא חֹדֶשׁ הָרַחֲמִים שֶׁמְּאִירִים אָז י\"ג מִדּוֹת הָרַחֲמִים וְהוּא זְמַן עֵת רָצוֹן וְנָקָל יוֹתֵר עִנְיַן הַתְּשׁוּבָה, וְאַחַר כַּךְ בִּימֵי הַסְּלִיחוֹת שֶׁהֵם זְמַנֵּי עֵת רָצוֹן עוֹד יוֹתֵר מֵחֹדֶשׁ אֱלוּל, וּכְמַאֲמָר הַיָּדוּעַ מֵרַבֵּינוּ בְּשֵׁם הַבַּעַל שֵׁם טוֹב נִשְׁמָתוֹ עֵדֶן דְּבִימֵי אֱלוּל אָז מְאִירִים י\"ג מִדּוֹת הָרַחֲמִים לְעוֹרֵר דִּין וְחֶשְׁבּוֹן,\nוְהַמָּשָׁל בָּזֶה סוֹחֵר גָּדוֹל שֶׁמּוֹכֵר סְחוֹרָתוֹ בְּהַקָּפָה הִנֵּה בְּסוֹף הַשָּׁנָה מְעוֹרֵר אֶת הַקּוֹנִים לַעֲשׂוֹת חֶשְׁבּוֹן כַּמָּה נִמְכַּר וְכַמָּה שִׁלְּמוּ וְכַמָּה עוֹד חַיָּיבִים לְשַׁלֵּם וּמְעוֹרֵר לְשַׁלֵּם אֶת הַמַּגִּיעַ, וְהַסּוֹחֵר עַצְמוֹ בְּשִׂמְחָה גְדוֹלָה שֶׁמָּכַר סְחוֹרָה הַרְבֵּה וּבְמִקָּחִים טוֹבִים וְהָיְתָה לוֹ פַּרְנָסָה מְרוּבָּה, אֲבָל עִם זֶה תּוֹבֵעַ אֶת קוֹנָיו לְשַׁלֵּם הַמַּגִּיעַ מֵהֶם וּמַזְכִּירָם אֲשֶׁר לְקִיחַת סְחוֹרָה בְּהַקָּפָה בְּשָׁנָה הַבָּאָה תָּלוּי בִּזְרִיזוּת פִּרְעוֹן הַחוֹבוֹת מֵהָעָבָר וְקוֹבֵעַ זְמַן בְּמֶשֶׁךְ כִּשְׁלֹשָׁה שָׁבוּעוֹת, שִׂמְחָתוֹ וּצְהִילַת פְּנֵי הַסּוֹחֵר מוֹעִיל לַקּוֹנִים שֶׁעֲמֵלִים בְּעָמָל רַב וּבִיגִיעָה עֲצוּמָה לְשַׁלֵּם חוֹבוֹתֵיהֶם, וּבִכְלוֹת מוֹעֵד הַקָּצוּב בָּא הַסּוֹחֵר הַגָּדוֹל לַעֲשׂוֹת חֶשְׁבּוֹן מִכָּל הַחוֹבוֹת וּכְשֶׁרוֹאֶה עֲמַל הַקּוֹנִים וִיגִיעָתָם הָעֲצוּמָה לִפְרוֹעַ חוֹבוֹתֵיהֶם וּמַכִּיר שֶׁבֶּאֱמֶת חָפְצוּ לִפְרוֹעַ אֲבָל עֲנִיִּים הֵמָּה וְאֵין יָדָם מַשֶּׂגֶת, אֲזַי עוֹשֶׂה חֶסֶד עִמָּהֶם וְסוֹלֵחַ וּמוֹחֵל לָהֶם מַה שֶּׁאִי אֶפְשָׁר לָהֶם לְשַׁלֵּם וּמַגְבִּיל לָהֶם אֵיזֶה זְמַן לְהָכִין עַצְמָם לְהַהַקָּפָה דִסְחוֹרָה חֲדָשָׁה,\nוְהֵם יְמֵי הַסְּלִיחוֹת, דְּכַאֲשֶׁר הָעֲבוֹדָה דִימֵי אֱלוּל הִיא עֲבוֹדָה שְׁלֵמָה בִּתְשׁוּבָה מֵעוּמְקָא דְלִיבָּא הִנֵּה בִּימֵי הַסְּלִיחוֹת מִתְקַבֶּלֶת תְּשׁוּבָתוֹ בְּקַבָּלָה טוֹבָה עַל לְהַבָּא, אֲשֶׁר כְּכָל הַתְּשׁוּבָה דֶאֱלוּל וִימֵי הַסְּלִיחוֹת וְקַבָּלַת עוֹל מַלְכוּתוֹ יִתְבָּרֵךְ בְּרֹאשׁ הַשָּׁנָה הִנֵּה לְפִי עֶרֶךְ זֶה נִקְצָב לוֹ הַחֶסֶד בְּבָנֵי חַיֵּי וּמְזוֹנֵי בְּרֹאשׁ הַשָּׁנָה וְנֶחְתָּם בְּיוֹם הַכִּפּוּרִים,\nאֲבָל חֶסֶד זֶה הוּא עֲדַיִין חֶסֶד פָּשׁוּט וְגַם שָׁרְשֵׁי הַחֶסֶד דַּעֲשִׂיָּה הַכָּלוּל בְּמַלְכוּת דַּאֲצִילוּת הוּא רוּחָנִי עֲדַיִין, וּבִכְדֵי שֶׁיָּבֹא בְּגַשְׁמִיּוּת הָעוֹלָם הַזֶּה הוּא עַל יְדֵי הִתְלַבְּשׁוּת בְּכֵלִים וּלְבוּשִׁים דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וְאַחַר כַּךְ בְּהַמַּזָּלוֹת דְּכָל אוֹפַנֵּי הַהִתְלַבְּשׁוּת הָאֵלּוּ הוּא מֵחֶסֶד ה' עָלֵינוּ לְהַשְׁפִּיעַ לָנוּ שֶׁפַע חַיּוּת כְּפִי עֶרְכֵּנוּ וּמַהוּתֵנוּ, מַה שֶּׁיִּהְיֶה טוֹב לָנוּ שֶׁנּוּכַל לְקַבֵּל שֶׁבִּשְׁבִיל זֶה מִתְצַמְצֵם וּמִתְלַבֵּשׁ הַחֶסֶד בְּכָל הַהִתְלַבְּשׁוּת הַנַ\"ל,\nוּכְמוֹ עַל דֶּרֶךְ מָשָׁל אָב הָרוֹצֶה לְשַׁעֲשֵׁעַ אֶת בְּנוֹ, הֲרֵי הוּא מְצַמְצֵם אֶת עַצְמוֹ וּמִתְלַבֵּשׁ בְּעִנְיָנִים קְטַנִּים מְאֹד, שֶׁהֵן לְפִי עֶרֶךְ הַקַּטְנוּת שֶׁל הַבֵּן, כְּמוֹ לְשַׂחֵק עִמּוֹ בֶּאֱגוֹזִים וְעוֹד בִּקְלִיפּוֹת הָאֱגוֹזִים, כִּי הַבֵּן מִצַּד קַטְנוּת שֶׁלּוֹ אֵינוֹ מַכִּיר בְּהַטּוֹב שֶׁבְּהַפְּרִי שֶׁבְּתוֹכָהּ כְּלָל, רַק הַקְּלִיפָּה תִּהְיֶה לוֹ לְטוֹב וּלְחֶסֶד בִּהְיוֹתוֹ יָכוֹל לְגַלְגְּלָהּ וְכַדּוֹמֶה, וּבְדוּגְמָא כָזֹאת מִפְּנֵי חֶסֶד ה' עָלֵינוּ מִתְצַמְצֵם הָאוֹר הָאֱלֹקִי וּמִתְלַבֵּשׁ בְּכַמָּה לְבוּשִׁים עַד הַלְּבוּשִׁים הַגַּסִּים דְּמַזָּלוֹת הַנַ\"ל, בִּכְדֵי שֶׁיִּתְהַוֶּוה בְּחִינַת חֶסֶד גַּשְׁמִי לְפִי עֶרֶךְ הַנִּבְרָאִים מַה שֶּׁטּוֹב לָהֶם,\nוְהַכַּוָּונָה פְנִימִית בָּזֶה הִיא אֲשֶׁר נִשְׁמוֹת יִשְׂרָאֵל עַל יְדֵי עֲבוֹדָתָם בַּתּוֹרָה וּמִצְוֹת יְבָרְרוּ אֶת נִיצוֹץ הַטּוֹב שֶׁבְּדָבָר הַגַּשְׁמִי וִיזַכְּכוּהוּ וְיַעֲלוּהוּ לְשָׁרְשׁוֹ וּמְקוֹרוֹ, אֲשֶׁר עַל יְדֵי זֶה נַעֲשֶׂה בֵּירוּר כְּלָלִי בִּכְלָלוּת הָעוֹלָם הַזֶּה אֲשֶׁר הוּא תַּכְלִית כָּל הָעוֹלָמוֹת וְכָל הַהִשְׁתַּלְשְׁלוּת, וּמֵהַאי טַעְמָא הִנֵּה רוֹב סוּגֵי הַתּוֹרָה וְהַמִּצְוָה נִתְלַבְּשׁוּ בִּדְבָרִים גַּשְׁמִים,\nדְּהִנֵּה עִיקַּר עִנְיַן לִימּוּד הַתּוֹרָה הוּא שֶׁיִּהְיֶה מוּבָן וּמוּשָּׂג בְּשֵׂכֶל הַטִּבְעִי וְהָאֱנוֹשִׁי, וְגַם אֲפִילוּ פְּנִימִיּוּת הַתּוֹרָה בַּהֲבָנַת וְהַשָּׂגַת אֱלֹקוּת בְּעִנְיַן יִחוּדוֹ וְאַחְדּוּתוֹ יִתְבָּרֵךְ וְכֵן בְּעִנְיַן גְּדוּלָּתוֹ בְּמָה רַבּוּ מַעֲשֶׂיךָ ה' וּבְמַה גָּדְלוּ מַעֲשֶׂיךָ ה' וּבְרִיבּוּי הָעוֹלָמוֹת וּפַרְצוּפִים הָעֶלְיוֹנִים, הִנֵּה הָעִיקָּר הוּא שֶׁיְּבָאֵר וְיַסְבִּיר הָעִנְיָנִים לְעַצְמוֹ עַד אֲשֶׁר יַשִּׂיגֵם בְּהַשָּׂגָה שִׂכְלִית בְּשֵׂכֶל אֱנוֹשִׁי,\nוְכֵן בְּעִנְיַן הַמִּצְוֹת הֲרֵי גַם הַמִּצְוֹת דְּחוֹבַת הַמּוֹחַ בִּידִיעַת אֱלֹקוּת, כְּמַאֲמָר שֶׁיֵּשׁ שָׁם מָצוּי רִאשׁוֹן מַמְצִיא כָּל נִמְצָא וְכָל הַנִּמְצָאִים בַּשָּׁמַיִם וּבָאָרֶץ וּמַה שֶּׁבֵּינֵיהֶם הֵם מֵאֲמִיתִּית הִמָּצְאוֹ, וְחוֹבוֹת הַלֵּב בְּאַהֲבָה וְיִרְאָה הֲרֵי מֵעִיקָּרֵי הַמִּצְוָה שֶׁתִּהְיֶה הַשָּׂגַת אֱלֹקוּת נִתְפֶּסֶת בְּמוֹחוֹ הַגַּשְׁמִי וְהָאַהֲבָה וְיִרְאָה יִהְיוּ נִרְגָּשִׁים בִּבְשַׂר הַלֵּב מַמָּשׁ, דְּכָל הָעֲבוֹדוֹת הָאֵלּוּ הֵם דַּוְקָא בָּעוֹלָם הַזֶּה שֶׁהוּא עוֹלָם גַּשְׁמִי,\nוּמִטַּעַם זֶה נִתְּנוּ הַהַשְׁפָּעוֹת בְּגַשְׁמִיּוּת עוֹלָם הַזֶּה בִּכְדֵי לַעֲבוֹד בָּהֶן אֶת ה' כְּפִי דִינֵי הַתּוֹרָה וְהַמִּצְוָה.\nקִיצּוּר.\nהַשֶּׁפַע בְּחֶסֶד הַנִּקְצָב הוּא מֵעַתִּיקָא, אֲבָל בָּא עַל יְדֵי הִתְעוֹרְרוּת הָעֶשֶׂר סְפִירוֹת דַּאֲצִילוּת דִּלְשָׁם מַגִּיעַ עֲבוֹדַת הַנִּבְרָאִים וּמַחְסוֹרָם, דִּלְפִי עֶרֶךְ הָעֲבוֹדָה בְּשָׁנָה הֶעָבְרָה כֵּן הִיא קִצְבַת שָׁנָה הַבָּאָה, וּתְלוּיָה בִּתְשׁוּבָה דֶאֱלוּל וַעֲבוֹדָה דִימֵי הַסְּלִיחוֹת וְהַקַּבָּלַת עֹל דְּרֹאשׁ הַשָּׁנָה. הַמָּשָׁל מֵהַסּוֹחֵר וְקוֹנָיו, הַכַּוָּונָה פְנִימִית בְּשֶׁפַע הַגַּשְׁמִי הִיא בִּשְׁבִיל קִיּוּם הַתּוֹרָה וּמִצְוֹת."],[4401900088,"וְהִנֵּה מֵהַמְבוֹאָר בַּאֲרוּכָה מוּבָן הֵיטֵב דְּהָעִיקָּר הוּא הָאֱלֹקוּת וְהַמַּזָּלוֹת הֵם רַק לְבוּשִׁים וּשְׁלוּחֵי הַשֶּׁפַע לְבָד וְאֵין בָּהֶם מַמָּשׁ מִצַּד עַצְמָם, אֲבָל הַמִּשְׁתַּחֲוֶה וְעוֹבֵד אוֹתָם, הֲרֵי זֶה שֶׁמְּחַשֵּׁב אוֹתָם לְדָבָר עִיקָּרִי בְּהַהַשְׁפָּעָה שֶׁהֵן הֵמָּה הַמַּשְׁפִּיעִים מִצַּד עַצְמָם, הֲרֵי זוֹ כְּפִירָה רַחֲמָנָא לִצְּלָן בְּהַשְׁגָּחַת אֱלֹקוּת וּבְהַשְׁפָּעַת הַחַיּוּת מֵאִתּוֹ יִתְבָּרֵךְ, וּמְחַשֵּׁב אֶת הַמַּזָּלוֹת לְמַשְׁפִּיעִים דְּמִשּׁוּם זֶה מִשְׁתַּחֲוֶה לָהֶם הֲרֵי זוֹ עֲבוֹדָה זָרָה מַמָּשׁ,\nוְכָל זֶה הוּא מִפְּנֵי שֶׁהַמַּזָּלוֹת הֵם בִּבְחִינַת לְבוּשׁ שַׂק, שֶׁמַּסְתִּירִים מְאֹד עַל הָאוֹר הָאֱלֹקִי שֶׁאֵינוֹ מֵאִיר בְּגִילּוּי כְּלָל וּמִתְלַבֵּשׁ עַל יְדֵי הַהַשְׁפָּעָה בִּלְבוּשֵׁי הַטֶּבַע, מִשּׁוּם זֶה יֵשׁ לָהֶם מָקוֹם לְדַמּוֹת שֶׁהַהַשְׁפָּעָה הִיא מֵהַמַּזָּלוֹת, שֶׁאִם לֹא הָיָה הָאוֹר הָאֱלֹקִי מוּסְתָּר וְנֶעְלָם כָּל כַּךְ, הָיוּ הַכֹּל יוֹדְעִים שֶׁהַהַשְׁפָּעָה מֵאֵת ה' הִיא, רַק מִפּנֵי רִיבּוּי הַהַעְלָמוֹת וְהַהֶסְתֵּרִים הַנַּעֲשִׂים עַל יְדֵי לְבוּשֵׁי הַמַּזָּלוֹת הִנֵּה מִשּׁוּם זֶה טָעוּ הַטּוֹעִים לַחְשׁוֹב גַּם אֶת הַלְּבוּשִׁים לִמְצִיאוּת דְּבַר מָה,\nאָמְנָם בִּשְׁבִיל הַנְהָגַת הָעוֹלָם כְּפִי רְצוֹנוֹ יִתְבָּרֵךְ שֶׁיִּהְיֶה גַּשְׁמִי וְהַהִתְהַוּוּת וְהַחַיּוּת יִהְיֶה בְּדֶרֶךְ הֶעְלֵם וְהֶסְתֵּר הַבּוֹרֵא מֵהַנִּבְרָא, הָיָה צָרִיךְ לִהְיוֹת הִתְלַבְּשׁוּת הַנַ\"ל בִּשְׁבִיל זֶה גּוּפָא שֶׁיִּתְלַבֵּשׁ הַחֶסֶד בִּלְבוּשֵׁי הַטֶּבַע וְיִהְיֶה לְפִי עֶרֶךְ הַנִּבְרָאִים שֶׁלְּמַטָּה, דְּאִם הָיָה הָאֱלֹקוּת מֵאִיר בְּגִילּוּי שֶׁלֹּא הָיָה מוּסְתָּר בִּלְבוּשִׁים הַנַ\"ל, הָיְתָה הַהַשְׁפָּעָה לְמַעְלָה מֵהַטֶּבַע וְלֹא הָיוּ נִבְרָאִים שֶׁבְּטֶבַע יְכוֹלִים לְקַבֵּל הַהַשְׁפָּעָה דְּהַיְינוּ טוֹב כָּזֶה שֶׁאֵינוֹ לְפִי עֶרְכָּם, וּמִשּׁוּם זֶה צָרִיךְ לִהְיוֹת הַהִתְלַבְּשׁוּת בִּלְבוּשִׁים הַנַ\"ל, רַק צְרִיכִים לֵידַע שֶׁזֶּהוּ הַחֶסֶד עֶלְיוֹן הַנִּקְצָב לָנוּ מֵאֵת ה' דַּוְקָא הוּא אֲשֶׁר נִתְלַבֵּשׁ בִּלְבוּשִׁים הַנַ\"ל אֲשֶׁר זֶה עַצְמוֹ הוּא מֵחֶסֶד ה' עָלֵינוּ,\nוּמִמּוֹצָא דָבָר אָנוּ יוֹדְעִים דְּכָל עִנְיַן הַהִתְלַבְּשׁוּת בְּהַמַּזָּלוֹת וְשָׂרִים הָעֶלְיוֹנִים שַׁיָּיךְ רַק בְּעוֹלָם הָעֲשִׂיָּה, כִּי הַהִתְלַבְּשׁוּת הִיא גַם כֵּן בְּסֵדֶר וְהַדְרָגָה דִּתְחִלָּה מִתְלַבֵּשׁ הָאוֹר בִּלְבוּשֵׁי עוֹלָם הַבְּרִיאָה וְנִתְבָּאֵר לְעֵיל (מַאֲמָר כג פֶּרֶק ב) דְּשָׁם עֲדַיִין הַחֶסֶד בִּבְחִינַת רוּחָנִי לְגַבֵּי לְמַטָּה, לְפִי שֶׁשָּׁם מֵאִיר עֲדַיִין הַגִּילּוּי אוֹר דַּאֲצִילוּת וּמִמֵּילָא אֵינוֹ בִּבְחִינַת מְצִיאוּת עֲדַיִין כַּנַ\"ל, וּמִתְלַבֵּשׁ אַחַר כַּךְ בִּלְבוּשֵׁי הַיְצִירָה וַעֲשִׂיָּה, וּבְעוֹלָם הָעֲשִׂיָּה שֶׁהוּא הָעוֹלָם שֶׁלְּמַטָּה מִכּוּלָּם, שָׁם מוּסְתָּר הָאוֹר יוֹתֵר אָז הוּא בְּעֶרֶךְ שֶׁיִּתְלַבֵּשׁ בִּלְבוּשׁ שַׂק דְּהַמַּזָּלוֹת, דִּלְמַעְלָה מִזֶּה כְּמוֹ בְּעוֹלָם יְצִירָה שֶׁאֵין הוּא מוּסְתָּר כָּל כַּךְ אִי אֶפְשָׁר שֶׁיִּתְלַבֵּשׁ בִּלְבוּשִׁים אֵלּוּ, כִּי אִם כַּאֲשֶׁר יוֹרֵד הָאוֹר וּמִתְלַבֵּשׁ בִּלְבוּשֵׁי עֲשִׂיָּה שֶׁהוּא מוּסְתָּר יוֹתֵר אָז יָכוֹל לְהִתְלַבֵּשׁ גַּם כֵּן בִּלְבוּשִׁים אֵלּוּ.\n<b>וְזֶהוּ</b> דְּאִיתָא בִּפְרִי עֵץ חַיִּים דְּאֵל אד' שֶׁהוּא שֵׁם דַּעֲשִׂיָּה הוּא בְּגִימַטְרִיָּא צַו וְאֵין צַו אֶלָּא כו', לְפִי שֶׁכַּאֲשֶׁר נִתְלַבֵּשׁ הָאוֹר הָאֱלֹקִי בִּלְבוּשֵׁי עֲשִׂיָּה יָכוֹל לְהִתְלַבֵּשׁ בִּלְבוּשׁ שַׂק דְּמַזָּלוֹת עֶלְיוֹנִים שֶׁמַּעְלִימִים וּמַסְתִּירִים מְאֹד עַד שֶׁיָּכוֹל לְדַמּוֹת שֶׁהֵם הַמַּשְׁפִּיעִים מִכֹּחַ עַצְמָם מִפְּנֵי שֶׁאֵין הָאֱלֹקוּת נִרְאֶה וְנִגְלֶה בְּגִילּוּי כְּלָל כַּנַ\"ל, וְלָכֵן אֵל אד' בְּגִימַטְרִיָּא צַו וְאֵין צַו אֶלָּא כו', דַּהֲגַם דְּאֵל אד' הֵם שֵׁמוֹת קְדוֹשִׁים אַךְ לְפִי שֶׁעַל יְדֵי זֶה בָּאָה הַהִתְלַבְּשׁוּת בְּהַמַּזָּלוֹת שֶׁהֵם מַסְתִּירִים לְגַמְרֵי עַד שֶׁנּוֹתֵן מָקוֹם לְחַשְּׁבָם וּלְדַמּוֹת שֶׁהֵם עַצְמָם הַמַּשְׁפִּיעִים וְלַעֲבוֹד אוֹתָם מִשּׁוּם זֶה, לָכֵן הַשֵּׁם שֶׁעַל יְדֵי זֶה בָּאָה הַהִתְלַבְּשׁוּת הַזֹּאת הוּא בְּגִימַטְרִיָּא צַו כו', אָמְנָם כְּבָר נִתְבָּאֵר לְעֵיל (פֶּרֶק א) שֶׁבֶּאֱמֶת הִתְלַבְּשׁוּת זוֹ הִיא מֵחַסְדֵי ה' עָלֵינוּ, לְפִי שֶׁעַל יְדֵי הִתְלַבְּשׁוּת זוֹ בָּא הַחֶסֶד הָעֶלְיוֹן בִּבְחִינַת טוֹב וְחֶסֶד גַּשְׁמִי. שֶׁבָּזֶה תָּלוּי כָּל עִנְיַן הָעֲבוֹדָה לְהַשְׁלִים הַכַּוָּונָה עֶלְיוֹנָה בְּעִנְיַן הַבְּרִיאָה.\nקִיצּוּר.\nהַמַּזָּלוֹת הֵם רַק שְׁלוּחִים לְגַשֵּׁם הַשֶּׁפַע הַבָּא מֵאִתּוֹ יִתְבָּרֵךְ וְהַמִּשְׁתַּחֲוֶה לָהֶם עוֹבֵד עֲבוֹדָה זָרָה. בִּכְדֵי שֶׁיִּהְיֶה הָעוֹלָם וְהַנְהָגָתוֹ כְּפִי רְצוֹנוֹ יִתְבָּרֵךְ בְּגַשְׁמִיּוּת, הוּא רַק עַל יְדֵי הֶסְתֵּר וְהֶעְלֵם הָאוֹר דְּשֵׁם דַּעֲשִׂיָּה שֶׁהוּא בְּגִימַטְרִיָּא צַו, וְלִהְיוֹתוֹ הֶעְלֵם גָּמוּר עַד שֶׁטּוֹעִים לַחְשׁוֹב אֶת הַמַּזָּלוֹת לִמְצִיאוּת לָכֵן אֵין צַו אֶלָּא עֲבוֹדָה זָרָה."],[4401900089,"<h2>מַאֲמָר כה.</h2>\nוְעַל פִּי זֶה יוּבַן מַה שֶּׁכָּתוּב (דְּבָרִים טו. יח) וּבֵרַכְךָ ה' אֱלֹקֶיךָ בְּכֹל אֲשֶׁר תַּעֲשֶׂה וְאִיתָא בְּסִפְרֵי יָכוֹל אֲפִילוּ יְהֵא יוֹשֵׁב וּבָטֵל תַּלְמוּד לוֹמַר בְּכֹל אֲשֶׁר תַּעֲשֶׂה, שֶׁצְּרִיכָה לִהְיוֹת עֲשִׂיָּה וְהַיְינוּ הֲכָנַת כְּלִי שֶׁל פַּרְנָסָה,\nדְּזֶהוּ א' הַהֶבְדֵּלִים בֵּין זְמַן הַגָּלוּת בַּעֲבוֹדַת הַבֵּירוּרִים וּבֵין הַזְּמַן דְּלֶעָתִיד בְּבִיאַת הַמָּשִׁיחַ, דְּלֶעָתִיד הִנֵּה שֶׁפַע חֶסֶד הָעֶלְיוֹן יָבֹא מֵאִתּוֹ יִתְבָּרֵךְ בְּלֹא שׁוּם הִתְעַסְּקוּת וַהֲכָנַת כְּלִי עֵסֶק בִּשְׁבִיל פַּרְנָסָה, מַה שֶּׁאֵין כֵּן בִּזְמַן הַגָּלוּת צְרִיכִים הִתְעַסְּקוּת בַּהֲכָנַת כְּלִי לְפַרְנָסָה,\nוְטַעַם הַדָּבָר שֶׁצְּרִיכָה לִהְיוֹת עֲשִׂיָּה דַוְקָא הוּא מֵאַחַר שֶׁהַהַשְׁפָּעָה צְרִיכָה לִהְיוֹת נִמְשֶׁכֶת עַל יְדֵי לְבוּשֵׁי הָעֲשִׂיָּה עַל כֵּן גַּם הָאָדָם אַתֶּם שֶׁהוּא בְּדוּגְמָא שֶׁלְּמַעְלָה צָרִיךְ גַּם כֵּן לַעֲשׂוֹת לְבוּשׁ וְעֵסֶק פַּרְנָסָה שֶׁבָּזֶה תִּתְלַבֵּשׁ הַבְּרָכָה שֶׁלְּמַעְלָה בִּלְבוּשֵׁי הַטֶּבַע,\nדְּהִנֵּה כְּתִיב (יְשַׁעְיָה מה. טו) אָכֵן אַתָּה אֵל מִסְתַּתֵּר, דְּבֵאלֹקוּת (אִין גֶעטְלִיכְקַיְיט) יֵשׁ אֵל הַגָּלוּי וְיֵשׁ אֵל הַמִּסְתַּתֵּר, וְהֵם בִּשְׁתֵּי דַּרְגּוֹת הֲפָכִים, טֶבַע וּלְמַעְלָה מֵהַטֶּבַע, דְּבֶאֱמֶת מוּבָן וּמוּשָּׂג גַּם בְּשֵׂכֶל אֱנוֹשִׁי שֶׁהָאֱלֹקוּת הַמִּתְלַבֵּשׁ בִּלְבוּשֵׁי הַטֶּבַע הוּא הָאֱלֹקוּת מַה שֶּׁלְּמַעְלָה מֵהַטֶּבַע, רַק הַהֶבְדֵּל בֵּין הָאֱלֹקוּת שֶׁבְּטֶבַע לְהָאֱלֹקוּת שֶׁלְּמַעְלָה מֵהַטֶּבַע הוּא רַק לְגַבֵּי הַנִּבְרָאִים, דְּלֵאלֹקוּת אֵין הֶבְדֵּל כְּלָל אִם הוּא בִּלְבוּשֵׁי הַטֶּבַע אוֹ שֶׁהוּא גָלוּי בְּלֹא לְבוּשׁ הַטֶּבַע וְהַהֶפְרֵשׁ הוּא רַק לְגַבֵּי הֵנִּבְרָאִים, דְּהָאֱלֹקוּת שֶׁמִּתְלַבֵּשׁ בְּטֶבַע צְרִיכִים הִתְבּוֹנְנוּת וְהָאֱלֹקוּת שֶׁלְּמַעְלָה מֵהַטֶּבַע אֵין צְרִיכִים הִתְבּוֹנְנוּת,\nדְּזֶהוּ פֵּירוּשׁ טֶבַע כִּפְשׁוּטוֹ מִלְּשׁוֹן טֻבְּעוּ בְיַם סוּף, שֶׁהַדָּבָר שֶׁנִּטְבַּע בַּיָּם הִנֵּה מֵי הַיָּם מְכַסִּים עָלָיו שֶׁאֵינוֹ נִיכָּר כְּלָל שֶׁיֶּשְׁנוֹ אֵיזֶה מְצִיאוּת דָּבָר מִלְּבַד הַמַּיִם, אֲבָל בֶּאֱמֶת הִנֵּה בְּזֶה שֶׁהַדָּבָר מְכוּסֶּה הֲרֵי אֵין הַכִּיסּוּי מְבַטֵּל מְצִיאוּתוֹ כְּלָל וְאֵין זֶה אֶלָּא שֶׁאֵינוֹ נִרְאֶה לְהָרוֹאִים רַק דָּבָר הַמְכַסֶּה אֲבָל בֶּאֱמֶת הִנֵּה הַמְכוּסֶּה הוּא בִּמְצִיאוּתוֹ וּמַהוּתוֹ כְּמוֹ שֶׁהוּא בְּגָלוּי מַמָּשׁ,\nוְכֵן הוּא בָּאֱלֹקוּת הַמִּסְתַּתֵּר בִּלְבוּשֵׁי הַטֶּבַע דִּלְבוּשֵׁי הַטֶּבַע הֵם רַק הַמְכַסִּים עַל הָאֱלֹקוּת, וּבֶאֱמֶת הִנֵּה הַמָּשָׁל שֶׁל מֵי הַיָּם הַמְכַסִּים עַל דָּבָר הַמְכוּסֶּה אֵינוֹ מָשָׁל אֱמִיתִּי עַל לְבוּשֵׁי הַטֶּבַע הַמְכַסִּים עַל אֱלֹקוּת, דְּהַמַּיִם הַמְכַסִּים הַנִּמְצָא בְתוֹכָם הֲרֵי הַדָּבָר הַנִּמְצָא וְהַמַּיִם הֵם שְׁנֵי עִנְיָנִים נִבְדָּלִים, לֹא הַמַּיִם יָצְרוּ אֶת הַדָּבָר הַנִּטְבַּע בָּהֶם וְלֹא הַדָּבָר הַמְכוּסֶּה בְּהַמַּיִם בָּרָא אֶת הַמַּיִם הַמְכַסִּים עָלָיו, מַה שֶּׁאֵין כֵּן הָאֱלֹקוּת הַמְלוּבָּשׁ בְּטֶבַע הֲרֵי הָאֱלֹקוּת בָּרָא וְהִמְצִיא אֶת לְבוּשֵׁי הַטֶּבַע וְהָאֱלֹקוּת הַמְלוּבָּשׁ בָּהֶם הִנֵּה הוּא יִתְבָּרֵךְ הַמְחַיֶּה אוֹתָם וּמְקַיְּימָם, אִם כֵּן הֲרֵי הָאֱלֹקוּת הַמְלוּבָּשׁ בְּטֶבַע הוּא עַצְמוֹ הָאֱלֹקוּת שֶׁלְּמַעְלָה מֵהַטֶּבַע,\nוּכְמוֹ שֶׁפֵּירֵשׁ רַבֵּינוּ נִשְׁמָתוֹ עֵדֶן (סֵפֶר שֶׁל בֵּינוֹנִים פֶּרֶק י\"ט) דְּשֵׁם טֶבַע הוּא תּוֹאַר לִדְבַר מָה שֶׁהוּא לְמַעְלָה מִטַּעַם וָדַעַת הַמּוּבָן וּמוּשָּׂג בְּשֵׂכֶל הַטִּבְעִי, וְהַנִּבְרָאִים הִנֵּה מִצַּד הָרְגִילוּת וְהַתְּמִידוּת שֶׁהַשֶּׁמֶשׁ זוֹרֵחַ בְּמִזְרָח וְשׁוֹקֵעַ בְּמַעֲרָב וְכֵן בִּשְׁאָרֵי הָעִנְיָנִים שֶׁהָאֱלֹקוּת מִסְתַּתֵּר בִּלְבוּשִׁים שׁוֹנִים הִנֵּה אֵינָם מִתְפָּעֲלִים מִזֶּה, וּצְרִיכִים הִתְעוֹרְרוּת הַהִתְבּוֹנְנוּת וְאָז מַשִּׂיגִים אֶת הָאֱמֶת הַגָּמוּר דְּטֶבַע עַצְמוֹ הוּא לְמַעְלָה מֵהַטֶּבַע, אָמְנָם דָּבָר זֶה לְהָבִין דְּטֶבַע עַצְמוֹ הוּא לְמַעְלָה מֵהַטֶּבַע אֵינוֹ מוּבָן כִּי אִם עַל יְדֵי הִתְבּוֹנְנוּת וְהַעֲמָקַת הַדַּעַת, וְהַיְינוּ דִּבְהַשְׁקָפָה רִאשׁוֹנָה יְכוֹלִים לִטְעוֹת בָּזֶה וְרַק כְּשֶׁמִּתְבּוֹנְנִים אָז עוֹמְדִים עַל אֲמִיתַּת הַדָּבָר דְּטֶבַע עַצְמוֹ הוּא עִנְיָן אֱלֹקִי שֶׁלְּמַעְלָה מֵהַטֶּבַע,\nדְּכָל זֶה הוּא בָּאֱלֹקוּת הַמְלוּבָּשׁ בְּדַרְכֵי לְבוּשֵׁי הַטֶּבַע שֶׁהוּא אֵל מִסְתַּתֵּר, אֲבָל אֵל הַגָּלוּי, אִין אָפֶענֶע גֶעטְלִיכְקַיְיט, הֲרֵי נִרְאֶה וְנִגְלֶה לַכֹּל וְאֵין צְרִיכִים עַל זֶה שׁוּם הִתְבּוֹנְנוּת.\nקִיצּוּר.\nמֵאַחַר שֶׁהַחֶסֶד שֶׁנִּקְצַב בְּרֹאשׁ הַשָּׁנָה צָרִיךְ לְהִתְגַּשֵּׁם עַל יְדֵי הַכֵּלִים דְּעֶשֶׂר סְפִירוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וְהַלְּבוּשִׁים דְּמַזָּלוֹת הִנֵּה מִשּׁוּם זֶה צָרִיךְ הָאָדָם לַעֲשׂוֹת כְּלִי לְפַרְנָסָה שֶׁיִּהְיֶה בִּלְבוּשֵׁי הַטֶּבַע, טֶבַע הוּא אֱלֹקוּת הַמּוּסְתָּר וּמוּשָּׂג בִּכְלָלוּתוֹ עַל יְדֵי הִתְבּוֹנְנוּת וּבֶאֱמֶת הוּא עַצְמוֹ לְמַעְלָה מֵהַטֶּבַע, אֱלֹקוּת הַגָּלוּי נִרְאֶה גַּם בְּלִי הִתְבּוֹנְנוּת."],[4401900090,"וְהִנֵּה לְבוּשֵׁי הַטֶּבַע עִם הֱיוֹת שֶׁזֶּהוּ כְּפִי הַכַּוָּונָה הָעֶלְיוֹנָה יִתְבָּרֵךְ וְיִתְעַלֶּה שֶׁעָלָה בִּרְצוֹנוֹ יִתְבָּרֵךְ לִבְרֹא עוֹלָם גַּשְׁמִי וַאֲשֶׁר כָּל עִנְיָן וְדָבָר אַף גַּם הָאוֹר הָאֱלֹקִי בָּעוֹלָם יִהְיֶה מִתְעַלֵּם וּמִסְתַּתֵּר בִּלְבוּשֵׁי הַטֶּבַע, הִנֵּה עִם כָּל זֶה הִנֵּה לְבוּשֵׁי הַטֶּבַע מִצַּד עֶצֶם מַהוּתָם הֲרֵי הֵם מַעְלִימִים וּמַסְתִּירִים אֶת הָאוֹר וְהַשֶּׁפַע הָאֱלֹקִי, עַד אֲשֶׁר הָאָדָם הָעוֹסֵק בְּמִסְחָר יוּכַל לִטְעוֹת וּלְדַמּוֹת בְּעַצְמוֹ כְּאִלּוּ חַס וְשָׁלוֹם כֹּחוֹ וְעוֹצֶם יָדוֹ עָשָׂה לוֹ אֶת הַחַיִל הַזֶּה, וְחָכְמָתוֹ עָמְדָה לוֹ שֶׁנִּתְחַכֵּם בְּעֵסֶק הַמִּקָּח וְהַמִּמְכָּר שֶׁהִתְנַהֵג עַל פִּי הַטֶּבַע לַחֲקוֹר וְלִדְרוֹשׁ בְּכָל עִנְיְנֵי הַקְּנִיּוֹת בָּחַר בִּדְרָכִים הַיּוֹתֵר נְאוֹתִים לְפִי דַרְכֵי הַטֶּבַע, וְכֵן בְּעִנְיַן אוֹפַנֵּי הַמְּכִירָה שֶׁעָשָׂה בָזֶה כַּמָּה תַּחְבּוּלוֹת וְהִתְחַכְּמוּת עַל פִּי דַרְכֵי הַטֶּבַע וְכָל אֵלֶּה עָמְדוּ לוֹ לְהַרְוִיחַ רֶיוַח גָּדוֹל,\nוּבֶאֱמֶת הִנֵּה כָּל אֵלֶּה לְבוּשֵׁי הַטֶּבַע אֵינָם אֶלָּא לְבוּשׁ לְבָד אֲבָל הַבְּרָכָה נִמְשֶׁכֶת מִלְמַעְלָה עַל יְדֵי הַלְּבוּשׁ וְלֹא מִצַּד עַצְמוּת הַלְּבוּשׁ חַס וְשָׁלוֹם, וּכְמוֹ שֶׁגִּידּוּל הַתְּבוּאוֹת נִמְשָׁךְ עַל יְדֵי הַשֶּׁמֶשׁ וְהַיָּרֵחַ וּכְמוֹ שֶׁכָּתוּב (דְּבָרִים לג. יד) וּמִמֶּגֶד תְּבוּאוֹת שָׁמֶשׁ וּמִמֶּגֶד גֶּרֶשׁ יְרָחִים וְעִם זֶה אֵינָן אֶלָּא שְׁלוּחֵי הַהַשְׁפָּעָה וְאֵין בְּיָדָם לְהָרַע וּלְהֵטִיב כִּי אִם אֶת אֲשֶׁר יֹאמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר כג פֶּרֶק א), כַּךְ הָעֵסֶק וְהַלְּבוּשׁ הוּא רַק כְּשָׁלִיחַ לְבָד וְהַהַשְׁפָּעָה הִיא בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא שֶׁצָּרִיךְ לְהִתְלַבֵּשׁ בִּלְבוּשׁ וְעֵסֶק שֶׁהֵן לְבוּשֵׁי הַטֶּבַע,\nוּלְפִי זֶה מוּבָן שֶׁאֵין צְרִיכִים לְהַאֲרִיךְ בְּהַלְּבוּשׁ יוֹתֵר מִדַּאי כִּי זֶה לְלֹא צוֹרֶךְ מֵאַחַר שֶׁלֹּא הַלְּבוּשׁ הוּא הָעִיקָּר כִּי אִם הַשְׁפָּעָתוֹ יִתְבָּרֵךְ שֶׁמַּשְׁפִּיעַ עַל יְדֵי הַלְּבוּשׁ, וְאִם כֵּן הָעִיקָּר הוּא שֶׁיִּתְפַּלֵּל לְמִי שֶׁהָעוֹשֶׁר וְהַנְּכָסִים שֶׁלּוֹ וִייַשֵּׁר דַּרְכּוֹ בְּדֶרֶךְ הַתּוֹרָה וְהַמִּצְוֹת שֶׁיִּהְיֶה רָאוּי לְבִרְכַּת ה' וְהַשְׁפָּעַת חֶסֶד, וְהַיְינוּ שֶׁיּוּמְשַׁךְ לוֹ קִצְבַת הַחֶסֶד בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים עַל יְדֵי קַבָּלַת עוֹל מַלְכוּתוֹ יִתְבָּרֵךְ וְעַל יְדֵי תְּשׁוּבָתוֹ הָאֲמִיתִּית,\nוְהַיְינוּ שֶׁלֹּא בִּשְׁבִיל זֶה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁפִּיעַ לוֹ קִצְבַת הַחֶסֶד שֶׁהוּקְצְבָה לוֹ יְקַבֵּל עָלָיו עוֹל מַלְכוּתוֹ וְיַעֲשֶׂה תְשׁוּבָה, אֶלָּא שֶׁהַקַּבָּלַת עוֹל מַלְכוּת שָׁמַיִם וְהַתְּשׁוּבָה תִּהְיֶה אֲמִיתִּית מִצַּד עַצְמָהּ מִפְּנֵי שֶׁכֵּן צָרִיךְ לִהְיוֹת וְיִהְיֶה חָזָק בְּקִיּוּם הַתּוֹרָה וּמִצְוֹת כָּל הַשָּׁנָה לְהִתְפַּלֵּל תְּפִלָּה בִּזְמַנָּהּ וּבְכַוָּונָה וְיִשְׁאַל צְרָכָיו גַּם כֵּן וְיִלְמוֹד תּוֹרָה בִּזְמַנִּים קְבוּעִים בְּלִי שׁוּם מְנִיעוֹת וְעִכּוּבִים וְאַחַר כַּךְ יַעֲסוֹק בְּמַשָּׂא וּמַתָּן וְיַסְפִּיק לוֹ גַּם מְעַט זְמַן עַל עֵסֶק, דְּמֵאַחַר שֶׁכְּבָר נִקְצַב לוֹ הַחֶסֶד עֶלְיוֹן וְנִמְשַׁךְ וְנִתְלַבֵּשׁ בִּלְבוּשִׁים שֶׁהֵם הַכֵּלִים דְּעֶשֶׂר סְפִירוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וְאֵינוֹ חָסֵר רַק לְבוּשׁ הַטֶּבַע שֶׁל הַמַּזָּלוֹת וְכֵן לְבוּשֵׁי הַטֶּבַע שֶׁל כְּלִי הַפַּרְנָסָה וַאֲשֶׁר עַל כֵּן הִנֵּה בִּמְעַט עֵסֶק שֶׁיַּעֲשֶׂה יוּמְשַׁךְ וְיִתְלַבֵּשׁ הַחֶסֶד בִּלְבוּשׁ הָעֵסֶק וְתוּמְשַׁךְ הַהַשְׁפָּעָה,\nוְהַיְינוּ כַּאֲשֶׁר הָאָדָם הוּא רָאוּי עַל פִּי מַעֲשָׂיו בַּתּוֹרָה וּמִצְוֹת לְחֶסֶד עֶלְיוֹן הֲרֵי אָז נִמְשָׁךְ הַחֶסֶד מֵעַתִּיקָא קַדִּישָׁא עַל יְדֵי הִתְעוֹרְרוּת הַסְּפִירוֹת דַּאֲצִילוּת כַּנַ\"ל (מַאֲמָר כד פֶּרֶק א) בְּמַלְכוּת דַּאֲצִילוּת וְיוֹרֵד וְנִמְשָׁךְ בִּלְבוּשִׁים וְכֵלִים דְּעֶשֶׂר סְפִירוֹת דִּבְרִיאָה-יְצִירָה-עֲשִׂיָּה וּמִתְגַּשֵּׁם בִּלְבוּשֵׁי הַמַּזָּלוֹת וַהֲרֵי הוּא נִמְשָׁךְ לְמַטָּה עַל יְדֵי לְבוּשׁ הָעֵסֶק וְאָז דַּי גַּם מְעַט עֵסֶק,\nאֲבָל אִם חַס וְשָׁלוֹם אֵינוֹ רָאוּי לְהַשְׁפָּעַת הַחֶסֶד וְהַיְינוּ כַּאֲשֶׁר לֹא נִמְשַׁךְ קִצְבַת הַחֶסֶד לְמַעְלָה בַּאֲצִילוּת, וְהַיְינוּ דְּמִי יֹאמַר כְּשֶׁלֹּא נִמְשַׁךְ חַס וְשָׁלוֹם קִצְבַת הַחֶסֶד בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים כְּלָל, אֶלָּא אֲפִילוּ גַּם אִם נִמְשַׁךְ לְמַעְלָה בְּמַלְכוּת דַּאֲצִילוּת הִנֵּה אִם אֵינוֹ נִמְשָׁךְ וּמִצְטַיֵּיר בִּלְבוּשֵׁי בְּרִיאָה-יְצִירָה-עֲשִׂיָּה בְּאוֹפֶן שֶׁיּוּכַל לִהְיוֹת מִזֶּה הַשְׁפָּעָה גַשְׁמִית וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר יט פֶּרֶק א), מַה מּוֹעִיל לוֹ רִיבּוּי הַהִתְעַסְּקוּת מֵאַחַר שֶׁאֵין חַס וְשָׁלוֹם הַמְשָׁכַת הַחֶסֶד מִלְמַעְלָה רַחֲמָנָא לִצְּלָן,\nוְאִם כֵּן הָעִיקָּר הוּא שֶׁיִּהְיֶה מָסוּר לֵאלֹקוּת וּכְשֶׁנִּמְשָׁךְ בְּחִינַת הַחֶסֶד עֶלְיוֹן הִנֵּה בִּרְכַּת ה' הִיא תַעֲשִׁיר גַּם בִּמְעַט עֵסֶק.\nקִיצּוּר.\nלְבוּשֵׁי הַטֶּבַע הֲגַם שֶׁהֵם עַל פִּי סֵדֶר שֶׁלְּמַעְלָה הִנֵּה הֵמָּה מַעְלִימִים בִּמְאֹד, וּבֶאֱמֶת הֵם רַק לְבוּשִׁים בִּלְבָד שֶׁאֵין לְהַאֲרִיךְ בָּהֶם וְהָעִיקָּר הוּא אֱלֹקוּת הַשּׁוֹפֵעַ וְצָרִיךְ לִהְיוֹת זָהִיר בִּתְפִלָּה בְּצִבּוּר וּבִמְתִינוּת וְלִקְבּוֹעַ עִתִּים לַתּוֹרָה, דְּכַאֲשֶׁר חַס וְשָׁלוֹם אֵינוֹ רָאוּי לֹא יוֹעִיל גַּם רִיבּוּי הִתְעַסְּקוּת וּכְשֶׁרָאוּי הִנֵּה גַּם בִּמְעַט עֵסֶק בִּרְכַּת ה' תַּעֲשִׁיר."],[4401900091,"וְהִנֵּה כַּמָּה וְכַמָּה מִבַּעֲלֵי עֲסָקִים וּמִבַּעֲלֵי עֲבוֹדָה וּמְלָאכָה שֶׁהֵם יִרְאֵי אֱלֹקִים וַחֲבִיבָה עֲלֵיהֶם הַתְּפִלָּה וְכֵן הַקְּבִיעוּת עִתִּים לַתּוֹרָה בְּשִׁיעוּרִים שׁוֹנִים בְּנִגְלָה וּבִדְאַ\"ח [וּבְדִבְרֵי אֱלֹקִים חַיִּים] וְלִבָּם יִכְאַב עֲלֵיהֶם בִּמְאֹד כְּשֶׁאֵינָם יְכוֹלִים לְהִתְפַּלֵּל בְּצִבּוּר וְאֵינָם יְכוֹלִים לְהִשְׁתַּתֵּף בְּהַשִּׁיעוּרֵי לִמּוּדִים בִּקְבִיעוּת עִתִּים לַתּוֹרָה בָּרַבִּים, מֵהֶם הַמִּתְאַמְּצִים בְּאוֹמֶץ רַב לְהִתְפַּלֵּל תְּפִלָּה בְּצִבּוּר וְחוֹטְפִים אֶת תְּפִלָּתָם וּמְמַהֲרִים לָרוּץ לְעִסְקֵיהֶם וּמִסְחָרָם, וּלְהִשְׁתַּתֵּף בְּאֵיזֶה שִׁיעוּר שֶׁל לִימּוּד הַתּוֹרָה אֵין בְּדַעְתָּם כְּלָל, כִּי לְבַד זֹאת שֶׁהֵם עֲסוּקִים בִּמְאֹד וְאֵין לָהֶם שׁוּם פְּנַאי לִלְמוֹד הִנֵּה לְבַד זֹאת הֲרֵי כָּל דַּעְתָּם וְשִׂכְלָם עָסוּק וּמְמוּלָּא מִמִּסְחָרָם וְעִנְיְנֵיהֶם הַגַּשְׁמִים מִבִּלְתִּי יְכוֹלֶת לְקַבֵּל דִּבְרֵי תוֹרָה וְגַם תְּפִלָּתָם מְהוּלָה בְּמַחֲשָׁבוֹת זָרוֹת עַד שֶׁכַּמָּה פְעָמִים בִּלְתִּי יוֹדְעִים מָה הֵמָּה מִתְפַּלְלִים וּבְאֵיזֶה מִזְמוֹר הֵם עוֹמְדִים וְרַק מִשִּׁיגְרָא דְלִישְׁנָא הִנֵּה שִׂפְתוֹתֵיהֶם נָעוֹת וְלִבָּם בַּל עִמָּם, וּבְכָל זֶה הֲרֵי יֵשׁ לָהֶם הַקַּבָּלַת עֹל לְהִתְפַּלֵּל בְּצִבּוּר עַל כָּל פָּנִים, וְיֵשׁ שֶׁהֵם טְרוּדִים כָּל כַּךְ עַד אֲשֶׁר רַק בְּשֵׁנִי וּבַחֲמִישִׁי בָּאִים לְהִתְפַּלֵּל בְּצִבּוּר,\nוְכוּלָּם מִתְנַצְּלִים שֶׁלְּסִבַּת טִרְדוֹת פַּרְנָסָתָם אֵין בִּיכָלְתָּם לְהִתְפַּלֵּל בְּצִבּוּר וּבִפְרָט לְהִשְׁתַּתֵּף בְּאֵיזֶה שִׁיעוּר שֶׁל לִימּוּד מִפְּנֵי שֶׁכָּל שִׂכְלָם עָסוּק בְּמִסְחָרָם וְאֵינָם יְכוֹלִים לְקַבֵּל דִּבְרֵי תוֹרָה, וְהַהַנְהָגָה הָרָעָה הַלֵּזּוּ הִנֵּה לְבַד זֹאת אֲשֶׁר כָּל יְמֵי הַשָּׁבוּעַ חַיִּים חַיֵּי בְהֵמָה וְעוֹד גָּרוּעַ מִזֶּה כְּמוֹ שֶׁמִּתְאוֹנֵן הַנָּבִיא (יְשַׁעְיָה א. ג) יָדַע שׁוֹר קוֹנֵהוּ וַחֲמוֹר אֵבוּס בְּעָלָיו יִשְׂרָאֵל לֹא יָדַע עַמִּי לֹא הִתְבּוֹנָן, הִנֵּה לְבַד זֹאת הֲרֵי דַּרְכָּם הַמּוּזָרָה וְהַנְהָגָתָם הָרָעָה בִּימֵי הַחוֹל גּוֹרֵם רָעָה אֲשֶׁר גַּם בְּיוֹם הַשַּׁבָּת שֶׁאָז הֵם פְּנוּיִים מֵעִסְקֵיהֶם וּמִסְחָרָם הִנֵּה מִשְׁתַּמְּשִׁים בּוֹ לְעִנְיְנֵי חוּלִּין, שֶׁמִּלְּבַד זֹאת שֶׁמִּפְּנֵי גוֹדֶל הַיְגִיעָה וְהֶעָמָל בְּכָל עִסְקֵיהֶם בִּימֵי הַחוֹל שֶׁהֵם מְעוּנִּים בִּמְאוֹד הִנֵּה בְּיוֹם הַשַּׁבָּת נָחִים בִּמְנוּחַת הַגּוּף, הִנֵּה מִלְּבַד זֹאת הַרֵי עַל יְדֵי הַנְהָגָתָם בִּימוֹת הַחוֹל נִתְעַבּוּ וְנִתְגַּשְּׁמוּ כָּל כַּךְ עַד כִּי גַם בְּיוֹם הַשַּׁבַּת קֹדֶשׁ שֶׁהוּא יוֹם הַמְּנוּחָה בִּשְׁבִיל לְהַרְבּוֹת בִּתְפִלָּה וּבְלִימּוּד הַתּוֹרָה, הִנֵּה בַּעֲלֵי הָעֲסָקִים הַטְּרוּדִים מִסּוּגִים הַנַ\"ל מְחַלְּלִים אֶת קְדוּשַּׁת הַשַּׁבָּת בְּעִנְיְנֵי הֶבֶל וּדְבָרִים בְּטֵלִים,\nאֲשֶׁר בֶּאֱמֶת הִנֵּה כָּל יְסוֹד בִּנְיָנוֹ מַה שֶּׁטָּרוּד בְּעֵסֶק וּמְדַמֶּה שֶׁאֵין בְּאֶפְשָׁרוּתוֹ לַעֲסוֹק בַּתּוֹרָה וּלְהִתְפַּלֵּל כִּדְבָעֵי מִפְּנֵי שֶׁיַּפְסִיד חַס וְשָׁלוֹם עַל יְדֵי זֶה הוּא דִמְיוֹן כּוֹזֵב וּשְׁטוּת גְּדוֹלָה בֶּאֱמֶת, דְּמִמָּה נַפְשָׁךְ אִם חַס וְשָׁלוֹם לֹא יֵשׁ קִצְבַת וְהַמְשָׁכַת הַחֶסֶד מִלְמַעְלָה רַחֲמָנָא לִצְּלָן מַה יּוֹעִיל לוֹ רִיבּוּי הַהִתְעַסְּקוּת, וְאִם יֵשׁ קִצְבַת וְהַמְשָׁכַת הַחֶסֶד מִלְמַעְלָה אֵין צְרִיכִים רִיבּוּי עֵסֶק וְדַי גַּם בִּמְעַט עֵסֶק מֵאַחַר שֶׁהוּא לְבוּשׁ לְבָד, וְרִיבּוּי טִרְדוֹתָיו וּמַה שֶּׁזֶּה לוֹ מְנִיעָה וְעִיכּוּב הוּא רַק מִשְּׁטוּתֵי הַיֵּצֶר, וּמַרְאֶה בָזֶה כְּאִלּוּ חַס וְשָׁלוֹם חוֹשֵׁב אֶת הַלְּבוּשׁ הַיְינוּ אֶת הָעֵסֶק לְעִיקָּר וְשֶׁזֶּה מְקוֹר פַּרְנָסָתוֹ לָכֵן הוּא טָרוּד בָּזֶה בְּרִיבּוּי הִתְעַסְּקוּת וְגַם בְּתַחְבּוּלוֹת מִפְּנֵי שֶׁחוֹשֵׁב זֶה לְעִיקָּר,\nוַהֲרֵי זֶה כְּעוֹבֵד עֲבוֹדָה זָרָה מַמָּשׁ שֶׁנִּתְבָּאֵר לְעֵיל (מַאֲמָר כג פֶּרֶק א) שֶׁזֶּהוּ שֶׁמִּשְׁתַּחֲוֶוה לַשֶּׁמֶשׁ וְיָרֵחַ מִפְּנֵי שֶׁמְּחַשֵּׁב אוֹתָם לְעִיקָּר שֶׁהֵם הַמַּשְׁפִּיעִים וּבֶאֱמֶת הֵמָּה רַק שְׁלוּחֵי הַהַשְׁפָּעָה וּלְבוּשִׁים לְבָד כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל, כְּמוֹ כֵן הִנֵּה כְּשֶׁמְּחַשֵּׁב אֶת הָעֵסֶק לְעִיקָּר וּמִשּׁוּם זֶה הוּא טָרוּד בְּרִיבּוּי הִתְעַסְּקוּת וְתַחְבּוּלוֹת שֶׁזֶּהוּ גַם כֵּן כְּעִנְיַן הִשְׁתַּחֲוָאָה, דִּכְמוֹ הִשְׁתַּחֲוָאָה בְּגַשְׁמִיּוּת הוּא שֶׁכּוֹפֵף וּמַרְכִּין רֹאשׁוֹ כְּמוֹ כֵן כְּשֶׁמֵנִיחַ שִׂכְלוֹ רֹאשׁוֹ וְרוּבּוֹ בְּעֵסֶק מַשָּׂא וּמַתָּן עַד שֶׁמּוֹנֵעַ אוֹתוֹ מִתּוֹרָה וַעֲבוֹדָה, הֲרֵי זֶה גַם כֵּן עִנְיַן הִשְׁתַּחֲוָאָה בְּרוּחָנִיּוּת וַהֲרֵי הוּא כְּעוֹבֵד עֲבוֹדָה זָרָה מַמָּשׁ חַס וְשָׁלוֹם.\nקִיצּוּר.\nבַּעֲלֵי הָעֲסָקִים וּבַעֲלֵי עֲבוֹדָה אֵינָם מִתְפַּלְלִים תְּפִלָּה בְּצִבּוּר בִּקְבִיעוּת וּתְפִלָּתָם חֲטוּפָה וּמְלֵאַָה מַחֲשָׁבוֹת זָרוֹת, וְאֵינָם מִשְׁתַּתְּפִים בְּשִׁיעוּרֵי לִימּוּד הַתּוֹרָה בָּרַבִּים בְּהִתְנַצְּלוּת טִרְדָּתָם בַּעֲמַל הַפַּרְנָסָה, וְזֶה גוֹרֵם הִתְגַּשְּׁמוּתָם שֶׁמְּחַלְּלִים מְנוּחַת וּקְדוּשַּׁת הַשַּׁבָּת בְּעִנְיְנֵי הֶבֶל, וִיסוֹד הִתְנַצְּלוּתָם הוּא דִמְיוֹן שָׁוְא."],[4401900092,"וְהִנֵּה יִשְׂרָאֵל הֵם מַאֲמִינִים בְּנֵי מַאֲמִינִים, דֶּאֱמוּנָה הִיא בְּטֶבַע תּוֹלַדְתָּם, שֶׁבָּזֶה חֲלוּקִים עַם יִשְׂרָאֵל מִכָּל הָעַמִּים אֲשֶׁר עַל פְּנֵי הָאֲדָמָה, דְּכָל הָעַמִּים הִנֵּה עִם הֱיוֹת שֶׁגַּם בֵּינֵיהֶם נִמְצָאִים בַּעֲלֵי אֱמוּנָה בֶּאֱמוּנָתָם וְאַף גַּם כָּאֵלּוּ שֶׁהֵם אֲדוּקִים בֶּאֱמוּנָתָם, הִנֵּה אֵין זֶה בְּטֶבַע תּוֹלְדוֹתָם וְהוּא רַק כְּדָבָר הַנִּקְנֶה עַל יְדֵי דְבַר מָה, וּכְמוֹ שֶׁאָנוּ רוֹאִים בְּמוּחָשׁ בְּעִנְיַן הַשֵּׂכֶל שֶׁיֵּשׁ שֵׂכֶל עַצְמִי וְיֵשׁ שֵׂכֶל הַנִּקְנֶה עַל יְדֵי דָבָר זוּלָתוֹ, שֶׁבִּכְלָלוּת הוּא הַהֶפְרֵשׁ בֵּין שִׂכְלֵי הַבַּעֲלֵי חַיִּים לְשֵׂכֶל הָאָדָם, שֶׁהָאָדָם הוּא שִׂכְלִי בְּעֶצֶם מַהוּתוֹ וְלָכֵן הִנֵּה כְּלָלוּת מַהוּת שֵׂכֶל הָאָדָם הוּא שֵׂכֶל עַצְמִי וְשֵׂכֶל הַבַּעֲלֵי חַיִּים הוּא שֵׂכֶל הַנִּקְנֶה, וּכְמוֹ יָדַע שׁוֹר קוֹנֵהוּ וַחֲמוֹר אֵבוּס בְּעָלָיו וְכֵן יֵשׁ כַּמָּה עִנְיָנִים מַה שֶּׁבָּהֶם וְעַל יָדָם מַכְנִיסִים שֵׂכֶל בְּבַעֲלֵי חַיִּים וּכְמוֹ הַמַּרְדַּעַת שֶׁמּוֹרֶה דֵעָה בַּבְּהֵמָה שֶׁכָּל זֶה הוּא רַק שֵׂכֶל הַנִּקְנֶה אֲבָל שֵׂכֶל הָאָדָם הוּא עַצְמִי,\nוְכֵן הוּא בְּעִנְיַן הָאֱמוּנָה דְּכָל הָעַמִּים הִנֵּה אֱמוּנָתָם הִיא כְּדָבָר הַנִּקְנֶה עַל יְדֵי דָבָר שֶׁחוּץ מִמֶּנּוּ, אֲבָל לְהַבְדִּיל, יִשְׂרָאֵל הִנֵּה אֱמוּנָתָם בַּה' וּבְתוֹרָתוֹ יִתְבָּרֵךְ הִיא עַצְמִית, וּכְמוֹ שֶׁאָנוּ רוֹאִים בְּמוּחָשׁ אֲשֶׁר בְּכָל עִנְיָן וְעִנְיָן, בֵּין שֶׁהוּא טוֹב וּבֵין שֶׁהוּא הַפְכִּי, הִנֵּה שֵׁם שָׁמַיִם שָׁגוּר בְּפִי כֹל בְּנוּסְחָאוֹת שׁוֹנוֹת, יְרַחֵם הַשֵּׁם יִתְבָּרֵךְ, יָחוּס הַשֵּׁם יִתְבָּרֵךְ תּוֹדָה לְהַשֵּׁם יִתְבָּרֵךְ, וְכַיּוֹצֵא בָהֶם בְּסִגְנוֹנוֹת תְּפִלָּה וְתַחֲנוּנִים וְתוֹדָה, דְּכָל זֶה מִפְּנֵי שֶׁבְּנִשְׁמוֹת יִשְׂרָאֵל הִנֵּה אֱמוּנָתָם בְּהַשֵּׁם יִתְבָּרֵךְ וּבְתוֹרָתוֹ יִתְבָּרֵךְ הִיא עַצְמִית, הֵם חַיֵּינוּ וְאוֹרֶךְ יָמֵינוּ וַעֲלֵיהֶם הוֹרַגְנוּ כָּל הַיָּמִים בִּימֵי הַגָּלוּת הַמַּר,\nוְכֵן הוּא בְּעִנְיַן הַפַּרְנָסָה דְּבֶאֱמֶת הִנֵּה הַכֹּל יוֹדְעִים שֶׁהָעִיקָּר הוּא בִּרְכַּת ה' וְכָל מִי שֶׁהוּא יְהוּדִי אֵינוֹ חוֹשֵׁב בְּשׁוּם אוֹפֶן שֶׁהָעֵסֶק הוּא מְקוֹר פַּרְנָסָתוֹ חַס וְשָׁלוֹם וְיוֹדֵעַ הֵיטֵב שֶׁהַהַשְׁפָּעָה מֵאֵת ה' הִיא וְהוּא הַנּוֹתֵן לוֹ אֶת פַּרְנָסָתוֹ עַל יְדֵי הָעֵסֶק, אֶלָּא שֶׁהָרוּחַ שְׁטוּת שֶׁהַיֵּצֶר הָרָע מַשְׁטֶה אוֹתוֹ שֶׁאֵינוֹ מֵשִׂים אֶל לִבּוֹ לָדַעַת אֲמִיתִּית הַדְּבָרִים הַנַ\"ל דְּמֵאַחַר שֶׁהָעִיקָּר הוּא הַהַשְׁפָּעָה הָעֶלְיוֹנָה הֲרֵי אֵינוֹ צָרִיךְ לִהְיוֹת שׁוּם מְנִיעָה וְעִיכּוּב וְשׁוּם קוֹצֶר בְּהַדְּבָרִים אֲשֶׁר חִיֵּיב אוֹתוֹ הַבּוֹרֵא לַעֲשׂוֹת, וְאַף שֶׁבִּשְׁבִיל זֶה לֹא יוּכַל לַעֲסוֹק הַרְבֵּה בְּעֵסֶק מַשָּׂא וּמַתָּן יַסְפִּיק לוֹ גַּם מְעַט עֵסֶק וְהַשֵּׁם יִתְבָּרֵךְ יַמְצִיא לוֹ לְהַרְוִיחַ בִּמְעַט זְמַן שֶׁבִּמְעַט הָעֵסֶק שֶׁיַּעֲשֶׂה יוּמְשַׁךְ וְיִתְלַבֵּשׁ הַחֶסֶד הַנִּקְצַב וְהַנִּמְשַׁךְ אֵלָיו,\nוְכַאֲשֶׁר נִפְתֶּה לַהֲסָתַת הַיֵּצֶר וּמַשְׁטֶה אֶת עַצְמוֹ בְּרוּחַ שְׁטוּת שֶׁצָּרִיךְ לְהִתְעַסֵּק הַרְבֵּה דַוְקָא וְאִי אֶפְשָׁר לוֹ לִקְבּוֹעַ עִתִּים לַתּוֹרָה וּלְהִתְפַּלֵּל כִּדְבָעֵי מִצַּד הַזְּמַן וְהַטִּרְדָּא וְנִדְמֶה לוֹ שֶׁנָּכוֹן כֵּן כְּפִי אֲשֶׁר מְדַמֶּה בְּשִׂכְלוֹ הַסָּכָל וְהַמְּעוּקָּל עַל יְדֵי רוּחַ שְׁטוּת הַנַ\"ל, מַרְאֶה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵינוֹ מוֹעִיל לוֹ רִיבּוּי הָעֵסֶק וַהֲרֵי הוּא הוֹלֵךְ סוֹבֵב כָּל הַיּוֹם בַּשְּׁוָקִים וּבָרְחוֹבוֹת מִבְּלִי יִמְצָא שׁוּב רֶיוַח כְּלָל, וּמִדָּה כְּנֶגֶד מִדָּה מְשַׁלֵּם לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ שֶׁכָּתוּב (דְּבָרִים כח. לד) וְהָיִיתָ מְשׁוּגָּע כו' אֲשֶׁר תִּרְאֶה, וּמֵרוֹב הַדְּאָגָה מִשְׁתּוֹמֵם מוֹחוֹ עַד שֶׁכִּמְשׁוּגָּע יֵחָשֵׁב שֶׁזֶּהוּ עַצְמוֹ עִנְיַן שְׁטוּת שֶׁהֲרֵי הַמְשׁוּגָּע וְהַשּׁוֹטֶה עִנְיָן אֶחָד לָהֶם, כִּי כְּמוֹ שֶׁאֵצֶל הַמְּשׁוּגָּע נִדְמֶה שֶׁצָּרִיךְ לִהְיוֹת דָּבָר שֶׁהוּא מוּפְרָךְ אֵצֶל הַבָּרִיא וְחָלִים, כֵּן הַשּׁוֹטֶה בְּרוֹב שְׁטוּתָיו גַּם כֵּן מִתְנַהֵג עַל דֶּרֶךְ זֶה וּכְמוֹ שֶׁכָּתוּב (שְׁמוּאֵל-א כא. טז) חֲסַר מְשׁוּגָּעִים אָנִי שֶׁכִּינָּה לְדָוִד שֶׁהִנִּיחַ לִימָּשֵׁךְ רִיר אֶל זְקָנוֹ בְּשֵׁם מְשׁוּגָּע עַל שֵׁם שֶׁהוּא הֵיפֶךְ הַדַּעַת כו',\nוְכָל זֶה גּוֹרֵם לוֹ מַה שֶּׁנִּפְתָּה לְהָרוּחַ שְׁטוּת שֶׁל הַיֵּצֶר הָרָע, אֲשֶׁר אִם הָיָה מֵשִׂים לִבּוֹ לְהַדְּבָרִים הָאֲמִיתִּים הַנַ\"ל הָיָה בְּאוֹפֶן אַחֵר לְגַמְרֵי, שֶׁלֹּא הָיָה צָרִיךְ לְהִתְעַסֵּק בְּרִיבּוּי עֵסֶק כְּלָל וְהָיָה נִמְשָׁךְ לוֹ הַחֶסֶד עֶלְיוֹן גַּם בִּמְעַט עֵסֶק בְּרִיבּוּי שֶׁפַע פַּרְנָסָה בְּרֶיוַח.\nקִיצּוּר.\nיִשְׂרָאֵל אֱמוּנָתָם בַּה' וּבְתוֹרָתוֹ הִיא עַצְמִית, אֱמוּנַת כָּל הָעַמִּים גַּם הָאֲדוּקִים הִיא כְּדָבָר הַנִּקְנֶה עַל יְדֵי דָבָר שֶׁחוּץ מִמֶּנּוּ, שֵׂכֶל עַצְמִי וְשֵׂכֶל הַנִּקְנֶה, הַכֹּל יוֹדְעִים שֶׁרַק בִּרְכַּת ה' הִיא תַעֲשִׁיר וְהַנִּפְתֶּה לַהֲסָתַת הַיֵּצֶר הָרָע מְאַבֵּד פַּרְנָסָתוֹ, שׁוֹטֶה וּמְשׁוּגָּע עִנְיָנָם אֶחָד."],[4401900093,"<h2>מַאֲמָר כו.</h2>\nוְזֶהוּ וּמַעְיָן מִבֵּית ה' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים דְּהִנֵּה יֵשׁ בִּקְדוּשָּׁה גַּם כֵּן בְּחִינַת שְׁטוּת וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (כְּתוּבּוֹת יז. א) אַהַנְיָא לֵיהּ שְׁטוּתֵיהּ לְסַבָּא, וּפֵירוּשׁ וְעִנְיַן שְׁטוּת זוֹ הוּא עִנְיָן שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת, וְעַל דֶּרֶךְ מַה שֶּׁכָּתוּב (מְלָכִים-ב ט. יא) מַדּוּעַ בָּא הַמְּשׁוּגָּע הַזֶּה שֶׁקָּרְאוּ לַנָּבִיא מְשׁוּגָּע, וְהַיְינוּ כִּי עִנְיָנוֹ הוּא הֵיפֶךְ עֵץ הַדַּעַת טוֹב וָרָע וְהַיְינוּ הֶעְדֵּר הַהֶרְגֵּשׁ שֶׁמִּצַּד הַחוּשִׁים הַטִּבְעִיִּים שֶׁזֶּה עִנְיַן עֵץ הַדַּעַת, וּכְיָדוּעַ שֶׁעַל יְדֵי חֵטְא עֵץ הַדַּעַת נַעֲשָׂה עִנְיַן הַהֶרְגֵּשׁ, וּכְמוֹ שֶׁכָּתוּב (בְּרֵאשִׁית ג. ז) וַיֵּדְעוּ כִּי עֵרוּמִּים הֵם, וְכִי מִתְּחִלָּה לֹא יָדְעוּ שֶׁהֵם עֵרוּמִּים, אֶלָּא שֶׁמִתְּחִלָּה לֹא הִרְגִּישׁוּ זֶה וְאַחַר כַּךְ הִרְגִּישׁוּ שֶׁהֵם עֲרוּמִּים, וּכְמוֹ שֶׁכָּתוּב תְּחִלָּה (בְּרֵאשִׁית ב. כה) וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים כו' וְלֹא יִתְבֹּשָׁשׁוּ, וְהַיְינוּ שֶׁלֹּא הִרְגִּישׁוּ זֹאת לְחִסָּרוֹן וְאַחַר כַּךְ וַיֵּדְעוּ כו' שֶׁהִרְגִּישׁוּ,\nוּכְמוֹ שֶׁכָּתוּב בְּמוֹרֵה נְבוּכִים (חֵלֶק א פֶּרֶק ב) שֶׁהִקְשָׁה לוֹ חָכָם אֶחָד אֵיךְ עַל יְדֵי הַחֵטְא נִתּוֹסְפָה לוֹ מַעֲלַת הַיְדִיעָה וְהַהַשְׂכָּלָה, כְּמוֹ שֶׁכָּתוּב (שָׁם ג. ז) וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם, וְתֵירֵץ הוּא זִכְרוֹנוֹ לִבְרָכָה שֶׁיְּדִיעָה זוֹ אֵינָהּ מַעֲלָה כְּלָל דִּתְחִלָּה הָיְתָה יְדִיעָתוֹ בִּידִיעוֹת הַמּוּשְׂכָּלוֹת וְלֹא הָיָה לוֹ כֹּחַ לְהִשְׁתַּמֵּשׁ בִּמְפוּרְסָמוֹת (הַיְינוּ בְּנָאֶה וּמְגוּנֶּה) בְּשׁוּם פָּנִים וְאַחַר כַּךְ נֶחְסְרָה מֵאִתּוֹ יְדִיעַת הַמּוּשְׂכָּלוֹת וּבָא לִידֵי דַעַת הַמְפוּרְסָמוֹת הַיְינוּ הֶרְגֵּשׁ הַטֶּבַע בְּנָאֶה וּמְגוּנֶּה שֶׁזֶּה יְרִידָה גְדוֹלָה מִמַּעֲלָתוֹ.\n<b>וּבְזֹהַר</b> (חֵלֶק ג רסא. סוֹף עַמּוּד ב) אִיתָא וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם בְּעִיפּוּשָׁא דְהַאי עָלְמָא מַה דְלָא הֲוָה קוֹדֶם דַּהֲווּ מַשְׁגְּחִין וּפַקְחִין לְעֵילָּא,\nוְכֵן הַנְּבִיאִים בְּעֵת שֶׁהִגִּיעָה עֲלֵיהֶם הַנְּבוּאָה הָיוּ בִּבְחִינַת הַפְשָׁטַת הַגַּשְׁמִיּוּת שֶׁבָּאוּ לְמַעֲלַת וּמַדְרֵיגַת אָדָם הָרִאשׁוֹן כְּמוֹ שֶׁהָיָה קוֹדֶם הַחֵטְא, וְהַיְינוּ שֶׁנִּתְבַּטְּלוּ אֶצְלָם הַחוּשִׁים הַטִּבְעִיִּים וְלֹא הִרְגִּישׁוּ בְּעִנְיָנִים הַגַּשְׁמִים. וְזֶהוּ עִנְיַן הַפְשָׁטַת הַבְּגָדִים שֶׁהָיָה בִּנְבִיאִים בְּעֵת נְבוּאָתָם וּכְמוֹ שֶׁכָּתוּב בְּשָׁאוּל (שְׁמוּאֵל-א יט. כד) וַיַּפְשֵׁט גַּם הוּא אֶת בְּגָדָיו וַיִּתְנַבֵּא כו' וַיִּפּוֹל עָרוֹם כו', וּכְמוֹ אָדָם הָרִאשׁוֹן קוֹדֶם הַחֵטְא שֶׁלֹּא הִרְגִּישׁ כְּלָל צוֹרֶךְ בִּלְבוּשִׁים כְּמוֹ כֵן הַנְּבִיאִים בְּעֵת נְבוּאָתָם לֹא יָדְעוּ וְלֹא הִכִּירוּ צוֹרֶךְ לִלְבוּשִׁים כְּלָל מִפְּנֵי הֶעְדֵּר הֶרְגֵּשׁ הַטִּבְעִי (וְעִנְיַן הַפְשָׁטַת הַבְּגָדִים הוּא עִנְיַן הַפְשָׁטַת הַחוּשִׁים הַטִּבְעִיִּים),\nוְזֶהוּ שֶׁקָּרְאוּ לַנָּבִיא בְּשֵׁם מְשׁוּגָּע מִפְּנֵי בִּיטּוּל הַחוּשִׁים הַטִּבְעִיִּים דְּעֵץ הַדַּעַת, וְעַל דֶּרֶךְ זֶה הוּא גַם כֵּן עִנְיַן אַהַנְיָא לֵיהּ שְׁטוּתֵיהּ לְסַבָּא, וְכֵן מַה שֶּׁאָמַר עֲקַבְיָא בֶּן מַהֲלַלְאֵל (עֵדֻיּוֹת פֶּרֶק ה מִשְׁנָה ו) מוּטָב לִי לְהִקָּרֵא שׁוֹטֶה כָּל יָמַי וְלֹא לֵיעָשׂוֹת שָׁעָה אַחַת רָשָׁע כו' שֶׁזֶּה עִנְיַן שְׁטוּת דִּקְדוּשָּׁה שֶׁהוּא הַהֵיפֶךְ מֵהַשְּׁטוּת דִּלְעוּמַּת זֶה, דְּהַשְּׁטוּת דִּלְעוּמַּת זֶה הוּא מַה שֶּׁעוֹשֶׂה הֵיפֶךְ הַדַּעַת וּכְמוֹ שֶׁנִּתְבָּאֵר לְעֵיל בְּכָל אוֹפַנֵּי הַשְּׁטוּתִים שֶׁמִּצַּד הַיֵּצֶר הָרָע שֶׁמַּשְׁטֶה וּמַטְעֶה אֶת הָאָדָם וּמַטֵּהוּ מִדֶּרֶךְ הָאֱמֶת, וְהַסִּיבָּה לָזֶה הוּא מִצַּד הַדַּעַת וְהַהֶרְגֵּשׁ דְּעֵץ הַדַּעַת טוֹב וָרָע שֶׁמְּכַסֶּה עַל הָאֱמֶת.\nקִיצּוּר.\nהַהַשְׂכָּלָה הַבָּאָה בְּסִבַּת חֵטְא עֵץ הַדַּעַת הִיא יְרִידָה מֵהַמּוּשְׂכָּלוֹת הָאֱלֹקִית לְעִיפּוּשָׁא דְהַאי עָלְמָא, הַפְשָׁטַת הַבְּגָדִים בִּנְבִיאִים וְאַהַנְיָא לֵי[הּ] שְׁטוּתֵיהּ לְסַבָּא הוּא הַיְצִיאָה מֵהֶרְגֵּשׁ הַחוּשִׁים הַטִּבְעִיִּים, וְהִיא הָעֲבוֹדָה שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת שֶׁנִּקְרֵאת שְׁטוּת דִּקְדוּשָּׁה."],[4401900094,"וּבֵיאוּר הָעִנְיָן הוּא דְּהִנֵּה הָאֱלֹקִים עָשָׂה אֶת הָאָדָם יָשָׁר וּמִצַּד הַכֹּחַ וְהַהֶרְגֵּשׁ הָאֱלֹקִי הַנִּיתַּן לוֹ הָיָה צָרִיךְ לֵידַע וּלְהַרְגִּישׁ אֶת הָאֱמֶת אֵיךְ שֶׁכָּל טוּבוֹ בָּעוֹלָם הוּא בִּבְחִינַת הַטּוֹב הָרוּחָנִי וְלַעֲלוֹת בְּמַעֲלַת הַדְּבֵקוּת בֵּאלֹקוּת וּבְתוֹרָתוֹ וּבְמִצְוֹתָיו וְאֵיךְ שֶׁהַהֵיפֶךְ רַע וּמַר בְּתַכְלִית וּכְכָל הַחֶשְׁבּוֹנוֹת שֶׁנִּתְבָּאֲרוּ לְעֵיל אֵיךְ שֶׁהֲסָתַת הַיֵּצֶר הוּא שֶׁקֶר גָּמוּר וְרָע, דְּבֶאֱמֶת הָיָה צָרִיךְ הָאָדָם לְהַרְגִּישׁ כָּל זֶה מִצַּד הַהֶרְגֵּשׁ אֱלֹקִי שֶׁבּוֹ וּמֵאַיִן הִיא הַסִּבָּה שֶׁנִּפְתֶּה לַהֲסָתַת הַיֵּצֶר, אָמְנָם זֶהוּ שֶׁגָּרַם חֵטְא דְּעֵץ הַדַּעַת טוֹב וָרָע,\nדְּהִנֵּה גַּם קוֹדֶם הַחֵטְא הָיָה בוֹ יֵצֶר הָרָע וּכְמַאֲמַר רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (בְּרָכוֹת סא. א) עַל פָּסוּק וַיִּיצֶר בִּשְׁנֵי יוּדִי\"ן שְׁנֵי יְצָרִים כו' אֶלָּא שֶׁאָז הָיָה בוֹ תּוֹקֶף הַהֶרְגֵּשׁ הָאֱלֹקִי עַד שֶׁלֹּא הִרְגִּישׁ עִנְיָנִים הַטִּבְעִיִּים וְכַנַ\"ל בְּשֵׁם הַמּוֹרֵה נְבוּכִים שֶׁהָיָה בוֹ יְדִיעַת הַמּוּשְׂכָּלוֹת וְלֹא הִרְגִּישׁ כְּלָל יְדִיעַת הַמְפוּרְסָמוֹת מִפְּנֵי תּוֹקֶף הַהֶרְגֵּשׁ בְּעִנְיְנֵי אֱלֹקוּת, וּלְאַחַר חֵטְא עֵץ הַדַּעַת נַעֲשָׂה לְהֵיפֶךְ שֶׁנַעֲשָׂה בּוֹ תּוֹקֶף הַהֶרְגֵּשׁ הַטִּבְעִי, הַיְינוּ שֶׁמַּרְגִּישׁ מְאֹד הַטּוֹב שֶׁבְּעִנְיָנִים הַגַּשְׁמִים וְכָל עִנְיָן טִבְעִי וְגַשְׁמִי שֶׁבָּעוֹלָם הוּא מַרְגִּישׁ מְאֹד, וְהַהֶרְגֵּשׁ הַזֶּה הוּא גוֹרֵם לוֹ הֶעְדֵּר הַהֶרְגֵּשׁ הָאֱלֹקִי לֵידַע וּלְהַרְגִּישׁ אֲמִיתַּת טוֹבָתוֹ שֶׁנִּתְבָּאֵר לְעֵיל.\n<b>וְזֶהוּ</b> עִנְיַן הַשְּׁטוּת שֶׁמִּצַּד הַיֵּצֶר הָרָע, שֶׁמִּפְּנֵי תּוֹקֶף הַהֶרְגֵּשׁ בְּעִנְיָנִים הַגַּשְׁמִים הוּא מַשְׁטֶה אֶת עַצְמוֹ בְּיוֹתֵר וְיוֹתֵר הוֹלֵךְ וְיוֹרֵד רַחֲמָנָא לִצְּלָן וְאֵינוֹ מִתְנַהֵג בְּדַעַת וְחֶשְׁבּוֹן אֲמִיתִּי וְזֶהוּ הַשְּׁטוּת דִּלְעוּמַּת זֶה שֶׁהוּא לְמַטָּה מִן הַדַּעַת, וְהַהֵיפֶךְ מִזֶּה הוּא הַשְּׁטוּת דִּקְדוּשָּׁה שֶׁהוּא גַם כֵּן מַה שֶּׁמִּתְנַהֵג שֶׁלֹּא עַל פִּי דַעַת וְחֶשְׁבּוֹן אֶלָּא שֶׁהוּא לְמַעְלָה מִטַּעַם וָדַעַת, וְהַיְינוּ שֶׁאֵינוֹ עַל פִּי הַדַּעַת וְהַהֶרְגֵּשׁ הַטִּבְעִי דְּעֵץ הַדַּעַת טוֹב וָרָע וְגַם אֵינוֹ עַל פִּי הַדַּעַת דִּקְדוּשָּׁה גַּם כֵּן, וְהַיְינוּ שֶׁאֵינוֹ נִכְנָס כְּלָל בְּחֶשְׁבּוֹנוֹת עַל פִּי הַדַּעַת וְהַשָּׂגָה שֶׁצָּרִיךְ לִהְיוֹת כַּךְ וְכַךְ אֶלָּא עוֹשֶׂה כָּל הַדְּבָרִים מִצַּד תּוֹקֶף הַנֶּפֶשׁ שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת,\nוּכְיָדוּעַ שֶׁבִּנְשָׁמוֹת יֵשׁ ב' מַדְרֵיגוֹת הָא' כֹּחוֹת הַגְּלוּיִם שֶׁל הַנְּשָׁמָה שֶׁהֵן בְּחִינַת מוֹחִין וּמִדּוֹת וְהַב' הוּא עֶצֶם הַנְּשָׁמָה שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת,\nוְהִנֵּה בְּחִינָה זוֹ שֶׁהָיְתָה בְּהִתְגַּלּוּת וּבְהִתְגַּבְּרוּת בְּאָדָם הָרִאשׁוֹן קוֹדֶם הַחֵטְא שֶׁהָיָה כָּל עִיּוּנוֹ בֵּאלֹקוּת שֶׁזֶּהוּ מִצַּד הַמּוֹחִין דְּנֶפֶשׁ הָאֱלֹקִית שֶׁהָיוּ מְאִירִים בּוֹ בְּהִתְגַּלּוּת,\nוּכְמוֹ כֵן יֵשׁ נְשָׁמוֹת שֶׁגַּם לְאַחַר הַחֵטְא לֹא יָרְדוּ מִמַּדְרֵיגָתָן כָּל כַּךְ וּמֵאִיר בָּהֶם אוֹר נַפְשָׁם הָאֱלֹקִית וְיֵשׁ לָהֶם דַּעַת וְהַשָּׂגָה בֵּאלֹקוּת וּבָזֶה כָּל עִסְקָם תָּמִיד וְאֵינָם שַׁיָּיכִים לְעִנְיָנִים אֲחֵרִים לְהַרְגִּישׁ כָּל כַּךְ אֶת הַטּוֹב הַטִּבְעִי הַבַּהֲמִי מֵעִנְיְנֵי עוֹלָם הַזֶּה, וַהֲגַם שֶׁאֵינוֹ בְּאוֹפֶן כְּמוֹ אָדָם הָרִאשׁוֹן קוֹדֶם הַחֵטְא שֶׁלֹּא הָיָה לוֹ הֶרְגֵּשׁ הַטִּבְעִי כְּלָל מִכָּל מָקוֹם אֵין בָּהֶם הֶרְגֵּשׁ הַטִּבְעִי כָּל כַּךְ, וְאֵינָם נִפְתִּים בִּשְׁטוּתֵי הַיֵּצֶר הָרָע וְיוֹדְעִים וּמַשִּׂיגִים אֶת הָאֱמֶת כְּפִי הַחֶשְׁבּוֹנוֹת הַנַ\"ל.\nקִיצּוּר.\nהָאֱלֹקִים נָתַן לְהָאָדָם הֶרְגֵּשׁ אֱלֹקִי אֲשֶׁר מִצַּד זֶה צָרִיךְ לֵידַע שֶׁטּוֹבָתוֹ הָאֲמִיתִּית הִיא בַּתּוֹרָה וּמִצְוֹת וַהֲסָתַת הַיֵּצֶר הָרָע שֶׁקֶר וְרָע, אָמְנָם הַהֶרְגֵּשׁ הַטִּבְעִי בְּסִבַּת חֵטְא עֵץ הַדַּעַת שׁוֹמֵעַ לִשְׁטוּתֵי הַיֵּצֶר הָרָע שֶׁלְּמַטָּה מִטַּעַם וָדַעַת, וּשְׁטוּת דִּקְדוּשָּׁה לְמַעְלָה מִטַּעַם וָדַעַת. אֵלּוּ שֶׁמֵּאִיר בָּהֶם אוֹר נַפְשָׁם הָאֱלֹקִית."],[4401900095,"<h2>מַאֲמָר כז.</h2>\nוְהִנֵּה אֵלּוּ אֲשֶׁר אוֹר נַפְשָׁם הָאֱלֹקִית מֵאִיר בָּהֶם בְּגִילּוּי וְיֵשׁ לָהֶם דַּעַת וְהַשָּׂגָה בֵּאלֹקוּת וְהָעִיקָּר שֶׁהֵם בַּעֲלֵי עֲבוֹדָה וְהַיְינוּ דְּאֵין זֶה מַה שֶּׁהֵם בַּעֲלֵי יְדִיעָה וְהַשָּׂגָה בֵּאלֹקוּת אֶלָּא שֶׁהֵם בַּעֲלֵי עֲבוֹדָה, אֲשֶׁר מִכָּל דְּבַר הַשָּׂגָה יֵשׁ לָהֶם תּוֹעֶלֶת בַּעֲבוֹדָה בְּפוֹעַל, וְהַהֶרְגֵּשׁ הָאֱלֹקִי מִתְגַּבֵּר עַל הַהֶרְגֵּשׁ הַטִּבְעִי דְּלֹא זוֹ בִּלְבָד שֶׁאֵינָם נִפְתִּים בִּשְׁטוּתֵי הַיֵּצֶר הָרָע אֶלָּא עוֹד זֹאת מִתְחַדֵּשׁ אֶצְלָם עִנְיְנֵי בֵּיאוּרִים וְהֶסְבֵּרִים שִׂכְלִים בְּחֶשְׁבּוֹנוֹת הַנַ\"ל (מַאֲמָר א' פֶּרֶק ג-ד) בְּמַעֲלוֹת מִין אֱנוֹשִׁי וּבְתַכְלִית בְּרִיאָתוֹ בָּעוֹלָם, וְטַעַם הַדָּבָר הוּא לְפִי שֶׁהֵם בַּעֲלֵי עֲבוֹדָה וּמִזְדַּכְּכִים מִזְּמַן לִזְמַן בְּעִילּוּי אַחַר עִילּוּי בְּהַגְבָּרַת הַצּוּרָה עַל הַחוֹמֶר,\nאֲבָל מִי שֶׁאֵין אוֹר נִשְׁמָתוֹ מֵאִיר בּוֹ בְּגִילּוּי כָּל כַּךְ וְנִפְתֶּה בְּפִיתּוּי הַיֵּצֶר, זֹאת הִיא עֲצָתוֹ שֶׁלֹּא לָבֹא כְּלָל לִידֵי חֶשְׁבּוֹנוֹת פְּרָטִים אֶלָּא לַעֲמוֹד נֶגֶד כָּל מוֹנֵעַ וּמְעַכֵּב בְּתוֹקֶף גָּדוֹל מִצַּד הַבְּחִינָה הַב' שֶׁבַּנֶּפֶשׁ וְהוּא בְּחִינַת עֶצֶם הַנְּשָׁמָה שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת.\n<b>דְּהִנֵּה</b> שֵׂכֶל וּמִדּוֹת הֵן רַק כֹּחוֹת הַנֶּפֶשׁ וְלֹא הָעֶצֶם אֲבָל עֶצֶם הַנְּשָׁמָה לְמַעְלָה מִבְּחִינַת הַשֵּׂכֶל וְעַל זֶה נֶאֱמַר (שְׁמוֹת לד. ט) כִּי עַם קְשֵׁה עוֹרֶף הוּא וְסָלַחְתָּ דְּמַה שֶּׁהֵם קְשֵׁה עוֹרֶף הוּא לְמַעַלְיוּתָא (דְּמִשּׁוּם זֶה הוּא טַעַם שֶׁבִּשְׁבִיל זֶה תִּהְיֶה הַסְּלִיחָה) וְהַיְינוּ הַתּוֹקֶף שֶׁיֵּשׁ בִּנְשָׁמוֹת לִהְיוֹת סוּר מֵרָע וַעֲשֵׂה טוֹב בְּלִי שׁוּם טַעַם וּבְלִי שׁוּם טַעֲנָה וּמַעֲנֶה כְּלָל,\nוּכְמוֹ הָעִיקֵּשׁ הוּא שֶׁאֵינוֹ מִתְנַהֵג עַל פִּי הַטַּעַם וְאָנוּ רוֹאִים בְּחוּשׁ שֶׁהָעִיקֵּשׁ רְצוֹנוֹ חָזָק בְּיוֹתֵר הַרְבֵּה מִזֶּה שֶׁמִּתְנַהֵג עַל פִּי הַשֵּׂכֶל, דְּזֶה שֶׁמִּתְנַהֵג עַל פִּי הַשֵּׂכֶל הֲרֵי רְצוֹנוֹתָיו הֵן עַל פִּי הַדַּעַת וְחִיּוּב שִׂכְלִי, וּכְיָדוּעַ שֶׁהַשֵּׂכֶל מַחֲלִישׁ אֶת הָרָצוֹן וּמַגְבִּיל אוֹתוֹ כַּמָּה יִתְפַּשֵּׁט אֲבָל הָרָצוֹן שֶׁאֵינוֹ עַל פִּי הַשֵּׂכֶל הוּא מִתְפַּשֵּׁט בְּיוֹתֵר בְּלִי הַגְבָּלָה. וְזֶהוּ שֶׁהָעִיקֵּשׁ רְצוֹנוֹ בְּתוֹקֶף בְּיוֹתֵר.\n<b>וּכְמוֹ</b> כֵן יֵשׁ בְּנִשְׁמוֹת יִשְׂרָאֵל עִנְיַן הָעִקְשׁוּת בִּקְדוּשָּׁה בְּתוֹקֶף גָּדוֹל וּכְמוֹ בִּמְסִירַת נֶפֶשׁ עַל קִדּוּשׁ הַשֵּׁם שֶׁיֵּהָרֵג וְלֹא יַעֲבוֹר חַס וְשָׁלוֹם, וְכֵן יָכוֹל לִהְיוֹת בְּכָל דָּבָר לִהְיוֹת בְּתוֹקֶף גָּדוֹל שֶׁלֹּא לָלֶכֶת בְּדַרְכֵי הַיֵּצֶר הָרָע וְהַנֶּפֶשׁ הַבַּהֲמִית וְלֹא לְהִמָּשֵׁךְ אַחֲרֵי תַּאֲווֹת לִבּוֹ, אַחֲרֵי שֶׁיּוֹדֵעַ כְּלַל הַדָּבָר שֶׁכָּל הַתַּאֲווֹת וְהַתַּעֲנוּגִים הַגַּשְׁמִים הֵמָּה תּוֹעֲבַת ה' אֲשֶׁר שָׂנֵא, וּבִפְרָט דְּבַר אִיסּוּר וְרָע מַמָּשׁ אֵינוֹ נִכְנָס כְּלָל בִּטְעָנוֹת וְחֶשְׁבּוֹנוֹת בָּזֶה,\nוּכְמוֹ כֵן אַחֲרֵי שֶׁיּוֹדֵעַ שֶׁצָּרִיךְ לְהִתְפַּלֵּל וְלִשְׁמוֹעַ פֵּירוּשׁ הַמִּלּוֹת עַל כָּל פָּנִים וְלִקְבּוֹעַ עִתִּים לַתּוֹרָה, אֵינוֹ נִכְנָס כְּלָל בְּשׁוּם טַעֲנָה וּמַעֲנֶה וְאֵינוֹ מַבִּיט כְּלָל אִם יַפְסִיד אוֹ לֹא יַפְסִיד, לִהְיוֹת כִּי מוּחְלָט אֶצְלוֹ בְּהֶחְלֵט גָּמוּר אֲשֶׁר הוּא צָרִיךְ לַעֲשׂוֹת אֶת שֶׁלּוֹ הַמְצֻוֶּוה עָלָיו עַל פִּי הַתּוֹרָה וְהַמִּצְוָה וְלַעֲמוֹד חָזָק נֶגֶד תַּאֲווֹת הַנֶּפֶשׁ הַבַּהֲמִית שֶׁלֹּא לַעֲשׂוֹת מַה שֶּׁמִּתְאַוֶּה לִבּוֹ בְּשׁוּם אוֹפֶן בְּכֹחַ וְתוֹקֶף גָּדוֹל, וְהוּא עִנְיַן בְּחִינַת הַשְּׁטוּת דִּקְדוּשָּׁה שֶׁהוּא הֵיפֶךְ הַדַּעַת דְּעֵץ הַדַּעַת טוֹב וָרָע וְגַם לֹא עַל פִּי הַדַּעַת דִּקְדוּשָּׁה כִּי אִם בְּהַתּוֹקֶף שֶׁמִּצַּד עֶצֶם הַנְּשָׁמָה וְאָז יוּכְשַׁר אַחַר כַּךְ לִבְחִינַת הַדַּעַת דִּקְדוּשָּׁה, כִּי עַל יְדֵי שֶׁיִּתְנַהֵג בִּבְחִינַת הַתּוֹקֶף שֶׁמִּצַּד עֶצֶם הַנְּשָׁמָה יִפְעוֹל עַל יְדֵי זֶה חֲלִישׁוּת הֶרְגֵּשׁ הַטִּבְעִי דְּנֶפֶשׁ הַבַּהֲמִית וְגַם שֶׁיִּהְיֶה הִתְגַּלּוּת הַכֹּחוֹת דְּנֶפֶשׁ הָאֱלֹקִית, וּמִמֵּילָא יָכוֹל לִהְיוֹת אַחַר כַּךְ בְּחִינַת הַדַּעַת וְהַהֶרְגֵּשׁ אֱלֹקִי בְּנַפְשׁוֹ לַעֲשׂוֹת מַעֲשָׂיו בְּהַשְׂכֵּל עַל פִּי הַדַּעַת וְהַחֶשְׁבּוֹנוֹת שֶׁנִּתְבָּאֲרוּ לְעֵיל.\nקִיצּוּר.\nמִי שֶׁאוֹר נַפְשׁוֹ הָאֱלֹקִית בִּלְתִּי מֵאִיר לוֹ בְּגִילּוּי, צָרִיךְ בְּקַבָּלַת עוֹל לְעוֹרֵר אֶת תּוֹקֶף הַהִתְקַשְּׁרוּת שֶׁבְּנַפְשׁוֹ לַה' וְלַתּוֹרָה וּמִצְוֹת בְּלִי חֶשְׁבּוֹנוֹת פְּרָטִים. שֵׂכֶל מַחֲלִישׁ אֶת הָרָצוֹן, מַעֲלַת הָעִקְשׁוּת בְּרָצוֹן בִּלְתִּי מוּגְבָּל, עִקְשׁוּת דִּקְדוּשָּׁה בִּקְבִיעוּת עִתִּים לַתּוֹרָה וּבְהִידּוּר מִצְוָה מַחֲלִישׁ אֶת הַהֶרְגֵּשׁ הַטִּבְעִי."],[4401900096,"וְזֶהוּ וּמַעְיָן מִבֵּית ה' יֵצֵא, דְּהִנֵּה מַעְיָן הוּא בְּחִינַת חָכְמָה וּכְמוֹ שֶׁכָּתוּב בְּסֵפֶר קְהִלַּת יַעֲקֹב בְּשֵׁם הָרַעְיָא מְהֵימְנָא, וּכְיָדוּעַ בְּעִנְיַן נָהָר וּמַעְיָן דְּנָהָר הוּא סְפִירַת הַבִּינָה וְנִקְרֵאת רְחוֹבוֹת הַנָּהָר לִהְיוֹת כָּל עִנְיַן הַנָּהָר אוֹרֶךְ וְרוֹחַב הַנִּמְשָׁךְ לְמֵרָחוֹק וּמִתְפַּשֵּׁט בְּרוֹחַב גָּדוֹל וּמַעְיָן הוּא סְפִירַת הַחָכְמָה, שֶׁהַהֶפְרֵשׁ בֵּינֵיהֶם דְּנָהָר הֲגַם שֶׁמִּתְפַּשֵּׁט בַּאֲרִיכוּת וּבְרוֹחַב גָּדוֹל שֶׁמִּתְמַלֵּא עַל כָּל גְּדוֹתָיו, בְּכָל זֶה אֶפְשָׁר שֶׁנִּפְסָק וּכְמוֹ שֶׁכָּתוּב (יְשַׁעְיָה יט. ה) וְנָהָר יֶחֱרַב וְיָבֵשׁ, וְהַמַּעְיָן עִם הֱיוֹת שֶׁנּוֹטֵף טִיפִּין טִיפִּין הִנֵּה אֵין לוֹ הֶפְסֵק,\nוְרַבֵּינוּ נִשְׁמָתוֹ עֵדֶן בֵּיאֵר (סֵפֶר שֶׁל בֵּינוֹנִים פֶּרֶק י\"ח וּפֶרֶק י\"ט) דְּחָכְמָה שֶׁבְּנֶפֶשׁ הוּא בְּחִינָה שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת וּמִשָּׁם כֹּחַ הַמְּסִירַת נֶפֶשׁ שֶׁיֵּשׁ בְּכָל אֶחָד וְאֶחָד לִמְסוֹר נַפְשׁוֹ עַל קִדּוּשׁ הַשֵּׁם וּמֵבִיא עַל זֶה פָּסוּק פֶּתִי יַאֲמִין לְכָל דָּבָר (מִשְׁלֵי יד. טו) שֶׁזֶּהוּ בְּחִינַת שְׁטוּת דִּקְדוּשָּׁה שֶׁנִּתְבָּאֵר לְעֵיל שֶׁזֶּהוּ מִבְּחִינַת כֹּחַ הַחָכְמָה שֶׁבְּנֶפֶשׁ כֹּחַ מָה, וּצְרִיכִים לוֹמַר דִּבְחִינַת כֹּחַ מָה שֶׁבְּנֶפֶשׁ הוּא בְּחִינָה עֶלְיוֹנָה שֶׁבְּחָכְמָה,\nדְּהִנֵּה בְּחָכְמָה יֵשׁ ב' מַדְרֵיגוֹת הָא' מַה שֶּׁחָכְמָה הִיא רֵאשִׁית הַגִּילּוּי וְרֵאשִׁית הַהִשְׁתַּלְשְׁלוּת וְהַב' מַה שֶּׁלְּמַעְלָה מִזֶּה וְהוּא לְמַעְלָה מֵהִשְׁתַּלְשְׁלוּת וְאֵינֶנָּה מִתְגַּלֵּית בְּאוֹתוֹ הָאוֹפֶן וּבְאוֹתוֹ הַסֵּדֶר כְּמוֹ שֶׁמִּתְגַּלָּה מַדְרֵיגָה הָא' שֶׁבְּחָכְמָה שֶׁהִיא רֵאשִׁית הַהִשְׁתַּלְשְׁלוּת,\nוְעִנְיָנָם בְּכֹחַ הַחָכְמָה שֶׁבְּנֶפֶשׁ הוּא כְּעִנְיַן בְּרִיקַת וּסְקִירַת הַשֵּׂכֶל, דְּעִם הֱיוֹת שֶׁהִיא עֲדַיִין לְמַעְלָה מֵהַשָּׂגָה מַמָּשׁ לְפִי שֶׁהִיא בִּבְחִינַת נְקוּדָּה כְּלָלִית עֲדַיִין וְאֵינוֹ נִתְפָּס בְּהַשָּׂגָה, מִכָּל מָקוֹם הוּא בִּבְחִינַת שֵׂכֶל גָּלוּי עַל כָּל פָּנִים שֶׁהֲרֵי כְּשֶׁנּוֹפֵל לוֹ הַבָּרָק הַמַּבְרִיק הֲרֵי הוּא יוֹדֵעַ אֶת הַשֵּׂכֶל בִּכְלָל עַל כָּל פָּנִים, וְזֶהוּ בְּחִינַת חִיצוֹנִיּוּת הַחָכְמָה, אֲבָל בְּחִינַת פְּנִימִית הַחָכְמָה הוּא מַה שֶּׁמּוֹחִין דְּאַבָּא הֵן לְמַעְלָה מֵהִשְׁתַּלְשְׁלוּת, וְהֵם ב' הַבְּחִינוֹת וּמַדְרֵיגוֹת כֹּחַ וּמָה דְּחָכְמָה, דִּבְחִינַת כֹּחַ דְּחָכְמָה זֶהוּ עִנְיַן הִתְפַּשְּׁטוּתָהּ אֶל הַבִּינָה וּבְחִינַת מָה דְחָכְמָה הוּא עִנְיַן הִתְדַּבְּקוּתָהּ אֶל הַכֶּתֶר, וּבְחִינָה זוֹ דְחָכְמָה הִנֵּה זֶהוּ מַה שֶּׁחָכְמָה הוּא בְּחִינַת הַבִּיטּוּל שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת.\n<b>וְזֶהוּ</b> שֶׁכָּתוּב וּמַעְיָן מִבֵּית ה' יֵצֵא הִנֵּה בַּיִת הוּא בְּחִינַת מַקִּיף, וְעַיֵּן מַה שֶּׁכָּתוּב מֵעִנְיַן בַּיִת בְּלִקּוּטֵי תוֹרָה בְּסוֹפוֹ בִּדְּרוּשׁ הַמַּתְחִיל מִזְמוֹר שִׁיר חֲנוּכַּת הַבַּיִת דְּרוּשׁ הַב' שֶׁזֶּהוּ בְּחִינַת פְּנִימִיּוּת הַכֶּתֶר, וְזֶהוּ עִנְיַן וּמַעְיָן מִבֵּית ה' יֵצֵא הַיְינוּ בְּחִינַת הַחָכְמָה כְּמוֹ שֶׁנִּמְשֶׁכֶת מִבְּחִינַת הַכֶּתֶר (וְעַיֵּן מַה שֶּׁכָּתַב הַפַּרְדֵּס בְּשַׁעַר עֶרְכֵי הַכִּנּוּיִם עֶרֶךְ מַעְיָן) וְהוּא בְּחִינַת מָה דְחָכְמָה הַנַ\"ל, וּמַעְיָן זֶה יַשְׁקֶה אֶת נַחַל הַשִּׁטִּים בְּחִינַת הַשְּׁטוּת דִּלְעוּמַּת זֶה שֶׁיִּתְהַפֵּךְ לִשְׁטוּת דִּקְדוּשָּׁה וְהַיְינוּ בַּעֲבוֹדָה בְּפוֹעַל לִהְיוֹת בִּבְחִינַת שְׁטוּת דִּקְדוּשָּׁה שֶׁלֹּא עַל פִּי דַעַת וְחֶשְׁבּוֹן כַּנַ\"ל,\nדְּהִנֵּה מַה שֶּׁחָכְמָה הִיא לְמַעְלָה מִטַּעַם וָדַעַת זֶהוּ בַּעֲבוֹדָה בִּבְחִינַת רְעוּתָא דְלִבָּא שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת, וְזֶהוּ בְּחִינַת מַעְיָן וְהִיא הָעֲבוֹדָה שֶׁמִּצַּד עֶצֶם הַנְּשָׁמָה, וְזֶה יַשְׁקֶה אֶת נַחַל הַשִּׁטִּים שֶׁמִּצַּד הַנֶּפֶשׁ הַבַּהֲמִית לִהְיוֹת הַהַנְהָגָה בְּפוֹעַל בְּכָל דָּבָר בִּבְחִינַת שְׁטוּת דִּקְדוּשָּׁה, הֵן בְּעֵסֶק מַשָּׂא וּמַתָּן שֶׁלֹּא יִהְיֶה לוֹ שׁוּם מְנִיעוֹת וְעִכּוּבִים כְּלָל, וּכְמוֹ כֵן לַעֲמוֹד עַל נַפְשׁוֹ בְּכָל הַתַּאֲווֹת וְתַעֲנוּגִים שֶׁלֹּא לְהִמָּשֵׁךְ אַחֲרֵיהֶם כְּלָל וּכְלָל, וְעַל יְדֵי זֶה יִפְעוֹל הַהַכְנָעָה בְּהַנֶּפֶשׁ הַבַּהֲמִית בִּכְלָל שֶׁבֶּאֱמֶת לֹא יִהְיֶה אֶצְלוֹ כָּל כַּךְ הֶרְגֵּשׁ הַטּוֹב דְּהָעִנְיָנִים הַגַּשְׁמִים, וְגַם יִהְיֶה עַל יְדֵי זֶה הִתְגַּלּוּת הַכֹּחוֹת מוֹחִין וּמִדּוֹת דְּנֶפֶשׁ הָאֱלֹקִית שֶׁיִּהְיֶה אָז הַנְהָגָתוֹ בְּכָל עִנְיָנָיו עַל פִּי בְּחִינַת הַדַּעַת דִּקְדוּשָּׁה.\nקִיצּוּר.\nחָכְמָה פֵּירֵשׁ רַבֵּינוּ שֶׁהִיא בְּחִינָה שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת, מַעְיָן, וּמִשָּׁם כֹּחַ הַמְּסִירַת נֶפֶשׁ עַל קִדּוּשׁ הַשֵּׁם וְנִסְיוֹנוֹת, חָכְמָ\"ה, כֹּחַ הִתְפַּשְּׁטוּת אֶל הַבִּינָה, מָ\"ה הִתְדַּבְּקוּתָהּ אֶל הַכֶּתֶר, מָ\"ה דְחָכְמָה מַשְׁקֶה נַחַל הַשִּׁטִּים שֶׁמְּהַפֵּךְ הַשְּׁטוּת דִּלְעוּמַּת זֶה לִשְׁטוּת דִּקְדוּשָּׁה וְאָז הַנְהָגָתוֹ בְּכָל עִנְיָנָיו עַל פִּי דַעַת דִּקְדוּשָּׁה."],[4401900097,"<h2>מַאֲמָר כח.</h2>\nתּוֹכֶן הַדְּבָרִים בְּעִנְיַן וּמַעְיָן מִבֵּית ה' יֵצֵא וְהִשְׁקָה כו' הוּא\nכִּי מִי שֶׁכְּבָר נִפְתָּה בְּפִיתּוּי וּשְׁטוּתֵי הַיֵּצֶר הָרָע מֵאֶחָד מֵהַדְּבָרִים הַנַ\"ל, אִם בְּתַאֲווֹת וְתַעֲנוּגֵי עוֹלָם הַזֶּה שֶׁנִּמְשָׁךְ אַחַר הַטּוֹב הַטִּבְעִי הַבַּהֲמִי בְּעִנְיָנִים הַגַּשְׁמִיִים מִפְּנֵי שֶׁמִּצַּד חֻמְרוֹ הַגַּס מַרְגִּישׁ מְאֹד הַטּוֹב בָּזֶה וְזֶה מַעֲבִירוֹ עַל דַּעְתּוֹ וְשִׂכְלוֹ לֵידַע וּלְהָבִין שֶׁאֵין זֶה טוֹב שֶׁלּוֹ כְּלָל, וּבִפְרָט בִּדְבָרִים הָאֲסוּרִים רַחֲמָנָא לִצְּלָן שֶׁגַּם בָּזֶה הָרוּחַ שְׁטוּת שֶׁל הַיֵּצֶר הָרָע שׁוֹלֵט עָלָיו לַהֲסִיתוֹ וּלְכַסּוֹת עַל הָאֱמֶת אֵיךְ שֶׁאֵינוֹ נַעֲשֶׂה נִפְרָד עַל יְדֵי זֶה וַעֲדַיִין הוּא בְּיַהֲדוּתוֹ וְיִתְבָּרֵךְ בִּלְבָבוֹ לֵאמֹר שָׁלוֹם יִהְיֶה לוֹ וּמִי יִרְאֶנּוּ וּמִי יוֹדֵעַ אֶת עִנְיָנוֹ וּמַעֲשָׂיו, דְּכָל אֵלֶּה הֵמָּה רַק דִּמְיוֹנוֹת כּוֹזְבִים וְשֶׁקֶר מוּחְלָט כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל בְּאוֹרֶךְ, וְהוּא מִצַּד חוּמְרוֹ הַגַּס נִתְפָּס בְּרוּחַ שְׁטוּת הַנַ\"ל,\nאוֹ בְּעֵסֶק מַשָּׂא וּמַתָּן בְּרִיבּוּי הִתְעַסְּקוּת וְרִיבּוּי טִרְדּוֹת וְתַחְבּוּלוֹת עַד שֶׁמּוֹנֵעַ אוֹתוֹ מִקְּבִיעוּת עִתִּים לַתּוֹרָה וּמִתְּפִלָּה כִּדְבָעֵי,\nוּמִפְּנֵי רִיבּוּי הַשִּׁיקּוּעַ בְּאֶחָד מֵהַדְּבָרִים הַנַ\"ל שֶׁהַיֵּצֶר הָרָע הִכְתִּירוֹ וְהִלְבִּישׁוֹ לְהַטּוֹתוֹ מִדֶּרֶךְ הָאֱמֶת וְאֵין בִּיכָלְתּוֹ לְהִתְגַּבֵּר עָלָיו עַל פִּי הַדַּעַת וְחֶשְׁבּוֹן צֶדֶק הַנַ\"ל מִפְּנֵי תּוֹקֶף חוֹמֶר יִצְרוֹ (אֲשֶׁר בְּמֶשֶׁךְ הַזְּמַן מִתְגַּבֵּר וְהוֹלֵךְ וּכְמוֹ שֶׁכָּתוּב בְּסֵפֶר שֶׁל בֵּינוֹנִים פֶּרֶק י\"ג וְזֶה לְשׁוֹנוֹ וְאַדְרַבָּא נִתְחַזֵּק יוֹתֵר בְּהֶמְשֵׁךְ הַזְּמַן שֶׁנִּשְׁתַּמֵּשׁ בּוֹ הַרְבֵּה בַּאֲכִילָה וּשְׁתִיָּה וּשְׁאָר עִנְיְנֵי עוֹלָם הַזֶּה עַד כַּאן לְשׁוֹנוֹ) שֶׁבְּבוֹאוֹ לְאֶחָד מֵהַדְּבָרִים שֶׁהוּא מְשׁוּקָּע בָּהֶם הוּא מִתְפָּעֵל מְאֹד בְּהֶרְגֵּשׁ הַטִּבְעִי הַבַּהֲמִי וּמְאַבֵּד דַּעְתּוֹ וְשִׂכְלוֹ וּמַשְׁטֶה אֶת עַצְמוֹ מִמֵּילָא,\nוְעוֹד זֹאת שֶׁהֲרֵי הַכֹּחוֹת דְּנַפְשׁוֹ הָאֱלֹקִית חֲלוּשִׁים אֶצְלוֹ דְּתוּקְפָּא דְגוּפָא חוּלְשָׁא דְנִשְׁמְתָא, וּמִפְּנֵי כָּל זֶה אִי אֶפְשָׁר לוֹ לָלֶכֶת עַל פִּי דַעַת וְחֶשְׁבּוֹן צֶדֶק\nכִּי אִם זֹאת הִיא הָעֵצָה הַיְּעוּצָה לְהִתְגַּבֵּר עַל הָרוּחַ שְׁטוּת דְּהַיֵּצֶר הָרָע דְּזֶה עִנְיַן נַחַל הַשִּׁטִּים עַל יְדֵי זֶה שֶׁיִּתְנַהֵג בִּבְחִינַת שְׁטוּת דִּקְדוּשָּׁה וְהוּא שֶׁיִּתְגַּבֵּר כָּאֲרִי לַעֲשׂוֹת רַק הַהֵיפֶךְ מִיִּצְרוֹ הָרָע בְּלִי שׁוּם טַעֲנָה וּמַעֲנֶה וּבְלִי שׁוּם חֶשְׁבּוֹן כִּי אִם בְּתוֹקֶף גָּדוֹל, שֶׁבְּהַדָּבָר הַהוּא שֶׁשָּׁקוּעַ בּוֹ מֵאֶחָד מֵהַדְּבָרִים הַנַ\"ל יַעֲשֶׂה הֵיפֶךְ לְגַמְרֵי וְלֹא יַחְשׁוֹב כְּלָל מַה יִּהְיֶה מֵאִתּוֹ, וְזֶה יֵשׁ בְּכֹחַ נִשְׁמוֹת יִשְׂרָאֵל מִצַּד עֶצֶם נִשְׁמָתָם שֶׁיֵּשׁ בָּהֶם תּוֹקֶף גָּדוֹל לְמַעְלָה מִטַּעַם וָדַעַת שֶׁזֶּהוּ עִנְיַן בְּחִינַת קְשֵׁה עוֹרֶף שֶׁהוּא לְמַעַלְיוּתָא וּבְחִינָה זוֹ זֶהוּ עִנְיַן הַמַּעְיָן שֶׁיֵּצֵא מִבֵּית ה', דִּלְמַעְלָה הוּא בְּחִינַת פְּנִימִית הַחָכְמָה כְּמוֹ שֶׁהִיא דְבוּקָה בַּכֶּתֶר, וּבַנֶּפֶשׁ הוּא בְּחִינַת עֶצֶם נִשְׁמָתוֹ שֶׁלְּמַעְלָה מִטַּעַם וָדַעַת.\n<b>וְזֶהוּ</b> וּמַעְיָן מִבֵּית ה' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים, דְּהַתּוֹקֶף שֶׁמִּצַּד עֶצֶם הַנְּשָׁמָה יֵשׁ בְּכֹחוֹ לְהִתְגַּבֵּר עַל הָרוּחַ שְׁטוּת דְּיֵצֶר הָרָע וּלְהַפְּכוֹ לִבְחִינַת שְׁטוּת דִּקְדוּשָּׁה, לַעֲמוֹד עַל נַפְשׁוֹ בְּתוֹקֶף גָּדוֹל לַעֲשׂוֹת בְּפוֹעַל הֵיפֶךְ מֵהַהֶרְגֵּשׁ הַטִּבְעִי שֶׁלּוֹ בְּהַפְּרָט שֶׁהוּא שָׁקוּעַ בּוֹ רַחֲמָנָא לִצְּלָן. וְכַאֲשֶׁר כָּכָה יִתְנַהֵג בְּפוֹעַל מֶשֶׁךְ זְמַן עַל יְדֵי זֶה יַחֲלִישׁ אֶת חוּמְרוֹ הַגַּס וְהַהֶרְגֵּשׁ הַטִּבְעִי הַבַּהֲמִי וְיִתְגַּלֶּה וְיִתְגַּבֵּר בּוֹ הַהֶרְגֵּשׁ מֵהַכֹּחוֹת הַגְּלוּיִם דְּנַפְשׁוֹ הָאֱלֹקִית וְיוּכַל אָז לִהְיוֹת בִּבְחִינַת דַּעַת דִּקְדוּשָּׁה וּכְמוֹ שֶׁכָּתוּב (מִשְׁלֵי ג. ו) בְּכָל דְּרָכֶיךָ דָעֵהוּ, דְּהַיְינוּ שֶׁגַּם בִּדְרָכָיו הַגַּשְׁמִים הַמּוּכְרָחִים לְקִיּוּם וְחַיּוּת גּוּפוֹ וּבְעִנְיְנֵי מַשָּׂא וּמַתָּן לֹא יַשְׁטֶה אֶת עַצְמוֹ חַס וְשָׁלוֹם בְּרוּחַ שְׁטוּת שֶׁל הַיֵּצֶר הָרָע כִּי אִם יִהְיֶה בִּבְחִינַת הַדַּעַת הָאֱלֹקִי הָאֲמִיתִּי וְיֵלֵךְ לָבֶטַח דַּרְכּוֹ.\nקִיצּוּר.\nבְּכָל אֶחָד מִיִּשְׂרָאֵל יֵשׁ בּוֹ הַתּוֹקֶף דְּמָ\"ה דְחָכְמָה שֶׁבַּנֶּפֶשׁ וְהוּא הַמַּעְיָן הַמַּשְׁקֶה גַּם אֶת נַחַל הַשִּׁטִּים, הַנִּלְכָּד בְּפִתּוּיֵי הַיֵּצֶר הָרָע צָרִיךְ לְעוֹרֵר תּוֹקֶף זֶה, וּבְכֹחוֹ לַעֲשׂוֹת בְּפוֹעַל הַהֵיפֶךְ מֵהַהֶרְגֵּשׁ הַטִּבְעִי וּבָזֶה יְבָרֵר חוּמְרוֹ הַגַּס וְיִתְנַהֵג עַל פִּי הַדַּעַת דִּקְדוּשָּׁה."],[4401900098,"<h2>הערות לקונטרס ומעין מבית ד'</h2>\nמאת כ\"ק אדמו\"ר זי\"ע\n<b>פ\"א ואילך</b> ראה המשך וככה - תרל\"ז פל\"ט ואילך.\n<b>החינוך:</b> בחנוך לא מצאתיו. ובכלל צ\"ע, כי ידוע שהחנוך הולך בעקבות מנין המצות של הרמב\"ם (אלא שמזכיר השגות הרמב\"ן. ראה לדוגמא מצוה יב ומז). ולולא דמסתפינא נ\"ל לפענ\"ד שטעה המעתיק, כי הי' כתוב בר\"ת <b>הח'</b> ופירשו<b> החינוך</b>, אבל צ\"ל <b>החרדים</b>, והוא שם (סוף חלק מ\"ע מה\"ת) בשם גאון ורשב\"ג, מן הכתוב קדושים תהיו (ויקרא יט, ב. ועיי\"ש ברמב\"ן הובא בחרדים). ויש להעיר אשר בקונטרס עץ החיים (וכנראה מיוסד על דרוש הצ\"צ בס' שמות פ' יתרו ד\"ה ויאמר אם שמוע) מבאר דהתאוה בדברים המותרים הוא איסור של תורה וכמ\"ש <b>החינוך</b> סי' שפ\"ז ובסהמ\"צ להרמב\"ם ל\"ת מז והוא מל\"ת דלא תתורו. עיי\"ש.\n<b>ותכלית כל:</b> מובא בכ\"מ מס' העקרים. ראה שם מ\"ג פ\"א.\n<b>וכמאמר:</b> ראה זח\"א קפ, ב. שם קמ, ב.\n<b>בתו\"א והוספות:</b> הכוונה ללקו\"ת לג' פרשיות.\n<b><b>יאר</b> . . עשיתי:</b> יאור לי ואני עשיתני. כן הוא בגתי\"ק ובסש\"ב ספכ\"ב. והוא חיבור ב' כתובים ביחזקאל כט, ט; כט, ג. אבל בהערה לתיקון חצות שבסי', בלקו\"ת בי' לד\"ה זאת חוקת ס\"ד, שם שה\"ש עוד בי' לד\"ה יונתי ס\"ב: <b>לי יאורי ואני עשיתני</b>.\n<b>בגמרא:</b> סוף מנחות.\n<b><b>נהורא</b> תתאה:</b> ראה זח\"ב קמ, א. זח\"א קעח, ב. עז, ב. פו, ב.\n<b>מאמרז\"ל:</b> ת\"ז ת\"ה (יט, ב).\n<b><b>והיכל</b> קדה\"ק הוא הלב:</b> לכאורה צ\"ע דבסש\"ב פנ\"ב, שמציין תיכף אח\"ז, כתב דהיכל קדה\"ק הוא חב\"ד. וכן הוא בע\"ח שער כסה\"כ. ובכ\"מ. ויש לבאר עפמש\"כ בד\"ה וירד העיט תרנ\"ח וז\"ל (בקיצור קצת): קה\"ק הוא בחי' פנימיות הכתר כו' ונמשך מפנימיות הכתר לחו\"ב כו' למל' ובבחי' זו נק' המל' קה\"ק כו' הכוונה על אור בחי' פני' הכתר שבמל'. - ובהגהות הרח\"ז בזהר שם (ח\"ג קסא, ב) פי' קה\"ק ותמן הוא לבא - היכל הז' דבריאה (שהוא כנ\"ל בסש\"ב) ותמן לבא - מלכות. ולהעיר מלקו\"ת סד\"ה שבת שבתון וביאורו.\n<b>מעורבים:</b> ראה ת\"ז תי' סט (קט, ב). ע\"ח שמ\"ח פ\"ג. שם שמ\"ז פ\"ד (ובהגהות שם). לקו\"ת במדבר (ד, ב).\n<b><b>שהבחירה</b> ניתנה לאדם:</b> ראה סש\"ב רפל\"ג. לקו\"ת אמור (לח, ב).\n<b>עד\"מ: </b>ראה סידור ד\"ה עבדים היינו.\n<b>והנה גם:</b> להעיר מהל' ת\"ת לרבנו הזקן פ\"ד ס\"ג.\n<b>הענין הוא:</b> ראה בכ\"ז הוספות לתו\"א בתחלתו.\n<b><b>והוא</b> מסבות:</b> ראה בכ\"ז שערי תשובה לאדהאמ\"צ ח\"א ד\"ה ראה נתתי.\n<b>טבע או טבע שני:</b> ראה סש\"ב פי\"ד-טו, ופמ\"ד. ועצ\"ע.\n<b><b>דהנה</b> באמת:</b> ראה בכ\"ז הגהות הצ\"צ לתניא ד\"ה משביעין אותו. ד\"ה עם לבן גרתי (בס' אוה\"ת).\n<b>והנה גוף:</b> ראה בכ\"ז תו\"א בראשית ג, ד.\n<b>וחטא הגאוה:</b> ראה שער רוה\"ק להאריז\"ל (טז, ב).\n<b>והרבב:</b> ראה מקואות ספ\"ט.\n<b><b>והנה</b> להבין:</b> ראה בכ\"ז לקו\"ת ס\"פ קורח. הקדמה לדרך חיים. סהמ\"צ להצ\"צ מצות תגלחת מצורע.\n<b>בזהר:</b> זח\"ג צד, ב.\n<b>כמא':</b> רמב\"ם בתחלתו."]]});
